                            $sem('div', 'row', array(
                                $field('col-12 col-md-3 mb-3', 'Selamlama',  'shipping_salutation',  'text', 'Bay/Bayan'),
                                $sem('div', 'col-md-9'),
                                $field('col-12 col-md-6 mb-3', 'Ad',         'shipping_first_name',  'text', '', true),
