// Takes a comment label, sets it to the default ("Comment") if blank,
// and pluralizes it if necessary.
function get_comment_label($properties)
{
    $label = $properties['label'];
    if (isset($properties['number'])) {
        $number = $properties['number'];
    }
    if ($label == '') {
        $label = lang('Comment');
    }
    if (isset($number)) {
        $label = pluralize(array(
            'word' => $label,
            'number' => $number
        ));
    }
    return $label;
}
// Takes a word, in singular form, and the number of items
// and it will convert it to plural if necessary.
// Only supports English. Does not support all plural cases.
function pluralize($properties)
{
    $word = $properties['word'];
    $number = $properties['number'];
    if (lang(array('info' => '')) == 'en') {
        if ($number == 1) {
            return $word;
        }
        $last_character = mb_substr($word, -1);
        $last_two_characters = mb_substr($word, -2);
        if (($last_character == 'x') || ($last_character == 's') || ($last_character == 'z') || ($last_two_characters == 'sh') || ($last_two_characters == 'ch')) {
            return $word . 'es';
        }
        if ($last_character == 'y') {
            $second_to_last_character = mb_substr($word, -2, 1);
            if (($second_to_last_character != 'a') && ($second_to_last_character != 'e') && ($second_to_last_character != 'i') && ($second_to_last_character != 'o') && ($second_to_last_character != 'u')) {
                return mb_substr($word, 0, -1) . 'ies';
            }
        }
        return $word . 's';
    } else {
        /*
        turkish language requre no pluralize
        example: 
        1 command = 1 yorum
        5 commands = 5 yorum
        Commands = Yorumlar
        check this area for other languages
        */

        return $word;
    }
}

function render_layout($properties)
{
    extract($properties);
    // If a page id was supplied, then get page info.
    if ($page_id) {
        $page = db_item("SELECT
                page_type AS type,
                layout_type,
                layout_modified
            FROM page
            WHERE page_id = '" . e($page_id) . "'");
        // Otherwise a page id was not supplied,
        // because we are loading a system screen, like forgot password,
        // where a page for that system screen does not exist.
    } else {
        $page['layout_type'] = 'system';
        $page['type'] = $page_type;
    }
    // If the style that is being used for the current page,
    // has an override layout type, then use it.
    if (pg_render_layout_type()) {
        $page['layout_type'] = pg_render_layout_type();
    }
    ob_start();
    if ($page['layout_type'] == 'system') {
        $template_name = str_replace(' ', '_', $page['type']) . '_system.php';
        include(dirname(__FILE__) . '/assets/templates/' . $template_name);
    } else {
        require_once(dirname(__FILE__) . '/generate_layout_content.php');
        if ($page['layout_modified']) {
            include(LAYOUT_DIRECTORY_PATH . '/' . $page_id . '.php');
        } else {
            $template_name = str_replace(' ', '_', $page['type']) . '.php';
            include(dirname(__FILE__) . '/assets/templates/' . $template_name);
        }
    }
    return ob_get_clean();
}

function render($properties)
{
    extract($properties);
    ob_start();
    include(dirname(__FILE__) . '/assets/templates/' . $template);
    return ob_get_clean();
}

// Gets a URL for a page type that should just have one page (e.g. change password).
function get_page_type_url($page_type)
{
    $page_name = db_value("SELECT page_name

        FROM page

        WHERE page_type = '" . e($page_type) . "'

        LIMIT 1");
    if ($page_name != '') {
        return PATH . encode_url_path($page_name);
    } else {
        return false;
    }
}
// Gets flat array of product groups for menu on catalog and catalog detail pages.
function get_product_groups($properties)
{
    $id = $properties['id'];
    $display_type = $properties['display_type'];
    if (isset($properties['level'])) {
        $level = $properties['level'];
    } else {
        $level = 0;
    }
    $status = $properties['status'];
    // Get info for this product group.
    $product_group = db_item("SELECT

            id,

            name

        FROM product_groups

        WHERE id = '" . e($id) . "'");
    $product_group['level'] = $level;
    $product_groups = array();
    $product_groups[] = $product_group;
    $sql_status = "";
    if ($status != '') {
        if ($status == 'enabled') {
            $sql_status = "AND (enabled = '1')";
        } else {
            $sql_status = "AND (enabled = '0')";
        }
    }
    $sql_display_type = "";
    if ($display_type) {
        $sql_display_type = "AND (display_type = '" . e($display_type) . "')";
    }
    $child_product_groups = db_items("SELECT id

        FROM product_groups

        WHERE

            (parent_id = '" . e($id) . "')

            $sql_status

            $sql_display_type

        ORDER BY sort_order, name");
    foreach ($child_product_groups as $product_group) {
        $product_groups = array_merge($product_groups, get_product_groups(array(
            'id' => $product_group['id'],
            'level' => $level + 1,
            'display_type' => $display_type,
            'status' => $status
        )));
    }
    return $product_groups;
}
// Looks at 3 different areas of a submitted form in order to determine
// which we consider to be the submitter email address for a submitted form.
function get_submitter_email_address($submitted_form_id)
{
    $submitter_email_address = '';
    // Check if there is a connect-to-contact email field,
    // and use that as the submitter email address if we find one.
    $submitter_email_address = db_value("SELECT form_data.data

        FROM form_data

        LEFT JOIN form_fields ON form_data.form_field_id = form_fields.id

        WHERE

            (form_data.form_id = '" . e($submitted_form_id) . "')

            AND (form_fields.contact_field = 'email_address')

        LIMIT 1");
    // If a submitter email address was not found from a
    // contact-to-contact email field, then check if there was a user that
    // submitted form.
    if (!$submitter_email_address) {
        $submitter_email_address = db_value("SELECT user.user_email

            FROM forms

            LEFT JOIN user ON forms.user_id = user.user_id

            WHERE forms.id = '" . e($submitted_form_id) . "'");
    }
    // If a submitter email address has still not been found,
    // then check for just a field with an email type.
    if (!$submitter_email_address) {
        $email_addresses = db_values("SELECT form_data.data

            FROM form_data

            LEFT JOIN form_fields ON form_data.form_field_id = form_fields.id

            WHERE

                (form_data.form_id = '" . e($submitted_form_id) . "')

                AND (form_fields.type = 'email address')");
        // If only one email address was found,
        // then it is safe to assume that is the submitter
        // email address, so we can use it.
        if (count($email_addresses) == 1) {
            $submitter_email_address = $email_addresses[0];
        }
    }
    return $submitter_email_address;
}
// Sends the notification e-mails (submitter e-mail and administrator e-mail)
// for a submitted form, and creates any auto e-mail campaigns that are
// triggered by a custom form submission.
// This logic used to live inline in edit_submitted_form.php.  It was extracted
// so that add_submitted_form.php can reuse it instead of duplicating it.
// $require_save_for_later preserves the original behavior of
// edit_submitted_form.php, which only sent notifications for custom forms that
// have save-for-later enabled.
function pg_send_custom_form_notifications($custom_form_page_id, $form_id, $contact_id = 0, $require_save_for_later = false)
{
    $custom_form = db_item(
        "SELECT
            page.page_id,
            custom_form_pages.enabled,
            custom_form_pages.save,
            custom_form_pages.submitter_email,
            custom_form_pages.submitter_email_from_email_address,
            custom_form_pages.submitter_email_subject,
            custom_form_pages.submitter_email_format,
            custom_form_pages.submitter_email_body,
            custom_form_pages.submitter_email_page_id,
            custom_form_pages.administrator_email,
            custom_form_pages.administrator_email_to_email_address,
            custom_form_pages.administrator_email_bcc_email_address,
            custom_form_pages.administrator_email_subject,
            custom_form_pages.administrator_email_format,
            custom_form_pages.administrator_email_body,
            custom_form_pages.administrator_email_page_id
        FROM page
        LEFT JOIN custom_form_pages ON page.page_id = custom_form_pages.page_id
        WHERE
            (page.page_id = '" . e($custom_form_page_id) . "')
            AND (page.page_type = 'custom form')");

    // If the custom form could not be found, or it is not enabled, then there
    // is nothing to send.
    if (!$custom_form['enabled']) {
        return false;
    }

    // If the caller requires save-for-later to be enabled (edit screen), and it
    // is not enabled, then do not send anything.
    if (($require_save_for_later == true) && (!$custom_form['save'])) {
        return false;
    }

    $submitter_email_address = '';

    // If the submitter or admin email is enabled, then get
    // submitter email address for later.
    if ($custom_form['submitter_email'] or $custom_form['administrator_email']) {
        $submitter_email_address = get_submitter_email_address($form_id);
    }

    // If submitter email is enabled, and a submitter email address
    // was found, then determine if there is a recipient to send email to.
    if ($custom_form['submitter_email'] and $submitter_email_address) {

        if ($custom_form['submitter_email_from_email_address']) {
            $from_email_address = $custom_form['submitter_email_from_email_address'];
        } else {
            $from_email_address = EMAIL_ADDRESS;
        }

        $subject = get_variable_submitted_form_data_for_content($custom_form['page_id'], $form_id, $custom_form['submitter_email_subject'], $prepare_for_html = false);

        // If the format of the e-mail should be plain text,
        // then prepare that.
        if ($custom_form['submitter_email_format'] == 'plain_text') {

            // Check the body for variable data and replace
            // any variables with content from the submitted form.
            $body = get_variable_submitted_form_data_for_content($custom_form['page_id'], $form_id, $custom_form['submitter_email_body'], $prepare_for_html = false);

        // Otherwise the format of the e-mail should be HTML, so prepare that.
        } else {

            require_once(dirname(__FILE__) . '/get_page_content.php');

            $body = get_page_content($custom_form['submitter_email_page_id'], $system_content = '', $extra_system_content = '', $mode = 'preview', $email = true, array('form_id' => $form_id));

        }

        email(array(
            'to' => $submitter_email_address,
            'from_name' => ORGANIZATION_NAME,
            'from_email_address' => $from_email_address,
            'subject' => $subject,
            'format' => $custom_form['submitter_email_format'],
            'body' => $body
        ));

    }

    // If admin email is enabled, then determine if we should send it.
    if ($custom_form['administrator_email']) {

        $administrator_email_addresses = array();

        if ($custom_form['administrator_email_to_email_address']) {
            $administrator_email_addresses[] = $custom_form['administrator_email_to_email_address'];
        }

        // Get conditional administrators.
        $conditional_administrators = db_values(
            "SELECT form_field_options.email_address
            FROM form_field_options
            LEFT JOIN form_data ON form_field_options.form_field_id = form_data.form_field_id
            WHERE
                (form_field_options.page_id = '" . $custom_form['page_id'] . "')
                AND (form_data.form_id = '" . e($form_id) . "')
                AND (form_field_options.email_address != '')
                AND (form_data.data = form_field_options.value)");

        // Loop through the conditional administrators in order to add them.
        foreach ($conditional_administrators as $conditional_administrator) {
            // We support multiple conditional admin email addresses, separated by comma,
            // (e.g. ^^example1@example.com,example2@example.com^^), so deal with that.
            $conditional_email_addresses = explode(',', $conditional_administrator);

            foreach ($conditional_email_addresses as $conditional_email_address) {
                $conditional_email_address = trim($conditional_email_address);

                // If this e-mail address has not already been added, then add it.
                if (in_array($conditional_email_address, $administrator_email_addresses) == false) {
                    $administrator_email_addresses[] = $conditional_email_address;
                }
            }
        }

        // If there is an admin to email, then continue to send email.
        if (
            $administrator_email_addresses
            or $custom_form['administrator_email_bcc_email_address']
        ) {

            $subject = get_variable_submitted_form_data_for_content($custom_form['page_id'], $form_id, $custom_form['administrator_email_subject'], $prepare_for_html = false);

            // If the format of the e-mail should be plain text,
            // then prepare that.
            if ($custom_form['administrator_email_format'] == 'plain_text') {

                // Check the body for variable data and replace
                // any variables with content from the submitted form.
                $body = get_variable_submitted_form_data_for_content($custom_form['page_id'], $form_id, $custom_form['administrator_email_body'], $prepare_for_html = false);

            // Otherwise the format of the e-mail should be HTML, so prepare that.
            } else {

                require_once(dirname(__FILE__) . '/get_page_content.php');

                $body = get_page_content($custom_form['administrator_email_page_id'], $system_content = '', $extra_system_content = '', $mode = 'preview', $email = true, array('form_id' => $form_id));

            }

            email(array(
                'to' => $administrator_email_addresses,
                'bcc' => $custom_form['administrator_email_bcc_email_address'],
                'from_name' => ORGANIZATION_NAME,
                'from_email_address' => EMAIL_ADDRESS,
                'reply_to' => $submitter_email_address,
                'subject' => $subject,
                'format' => $custom_form['administrator_email_format'],
                'body' => $body
            ));

        }

    }

    // Check if there are auto e-mail campaigns that should be
    // created based on this custom form being submitted.
    create_auto_email_campaigns(array(
        'action' => 'custom_form_submitted',
        'action_item_id' => $custom_form['page_id'],
        'contact_id' => $contact_id));

    return true;
}
function get_layout_type($page_id)
{
    // If the style that is being used for the current page,
    // has an override layout type, then use it.
    if (pg_render_layout_type()) {
        return pg_render_layout_type();
        // Otherwise use the page's layout type.
    } else {
        return db_value("SELECT layout_type FROM page WHERE page_id = '" . e($page_id) . "'");
    }
}
// Returns an SQL filter to only get non-protected shipping methods for visitors that should not
// have access to protected shipping methods.
function get_protected_shipping_method_filter()
{
    // If this visitor is not a manager or above, then don't get protected methods.
    if (!USER_LOGGED_IN or ((USER_ROLE == 3) and !$_SESSION['software']['logged_in_as_different_user'])) {
        return "AND (shipping_methods.protected = '0')";
        // Otherwise this is a manager or above, so don't return any filter, so that all shipping
        // methods, including protected ones, will be retrieved.
    } else {
        return "";
    }
}
// If the site is not private labeled then return generator meta tag that shows that the site was
// generated by pinegrap.  This is used for both frontend and backend HTML.
function get_generator_meta_tag()
{
    if (!defined('PRIVATE_LABEL') or !PRIVATE_LABEL) {
        return '';
    } else {
        return '';
    }
}
// Looks through a multi-dimensional array and returns the first item with a matching property and
// value.
function array_finder($items, $property, $value)
{
    foreach ($items as $item) {
        if ($item[$property] == $value) {
            return $item;
        }
    }
    return false;
}
function error_response($message = '')
{
    return array(
        'status' => 'error',
        'message' => $message
    );
}
function success_response($message = '')
{
    return array(
        'status' => 'success',
        'message' => $message
    );
}
function set_response_code($response_code)
{
    if (!$response_code) {
        return false;
    }
    // If this is PHP 5.4+ which has a function to do response codes, then use that.
    if (function_exists('http_response_code')) {
        http_response_code($response_code);
        // Otherwise create our own code.
    } else {
        switch ($response_code) {
            case 403:
                header('HTTP/1.1 403 Forbidden');
                break;
            case 404:
                header('HTTP/1.1 404 Not Found');
                break;
            case 410:
                header('HTTP/1.1 410 Gone');
                break;
        }
    }
    return true;
}

// Used to bust cache for uploaded files.  Pass the file name and it will return the file name
// with a unique query string containing the last modified timestamp (e.g. example.css?v=123).
// This will force browsers to ignore cache and download a new file.  Only works for files
// that users have uploaded.  Does not work with Pinegrap system files. Example below, but remove
// last backslash, which is just required in these comments.
// <link rel="stylesheet" href="/<?=smart_cache('example.css')?\>">
function smart_cache($file_name)
{
    $last_modified_timestamp = @filemtime(FILE_DIRECTORY_PATH . '/' . $file_name);
    // If a timestamp was found, then return file name along with query string with timestamp.
    if ($last_modified_timestamp) {
        return $file_name . '?v=' . $last_modified_timestamp;
        // Otherwise a timestamp was not found (file might have been deleted), so just return the file
        // name so we don't break any code.
    } else {
        return $file_name;
    }
}

// This function checks who is online in this site with last-seen status.
// If you don't store user_id in the session it will fall back to sessionusername.
function who_is_online($check_time = 50)
{
    // normalize check time (default 50 seconds)
    $ct = (int) $check_time;
    if ($ct <= 0) {
        $ct = 50;
    }

    if ((USER_LOGGED_IN) && (defined('DB_CONNECTED'))) {
        // Prefer session user id if available
        if (isset($_SESSION['sessionuserid']) && $_SESSION['sessionuserid'] !== '') {
            $user_id = (int) $_SESSION['sessionuserid'];
            $query = "UPDATE user
                      SET user_online_timestamp = UNIX_TIMESTAMP()
                      WHERE user_id = '" . $user_id . "'
                        AND (UNIX_TIMESTAMP() - user_online_timestamp) > " . $ct;
            @mysqli_query(db::$con, $query);
            return;
        }

        // Fallback to username if user_id not stored in session
        if (isset($_SESSION['sessionusername']) && $_SESSION['sessionusername'] !== '') {
            $username = escape($_SESSION['sessionusername']);
            $query = "SELECT user_id, user_online_timestamp
                      FROM user
                      WHERE user_username = '" . $username . "'
                      LIMIT 1";
            $result = mysqli_query(db::$con, $query);
            if ($result && mysqli_num_rows($result) > 0) {
                $row = mysqli_fetch_assoc($result);
                $user_id = (int) $row['user_id'];
                $user_online_timestamp = (int) $row['user_online_timestamp'];
                if ((time() - $user_online_timestamp) > $ct) {
                    $update = "UPDATE user
                               SET user_online_timestamp = UNIX_TIMESTAMP()
                               WHERE user_id = '" . $user_id . "'";
                    @mysqli_query(db::$con, $update);
                }
            }
        }
    }
}

// ── Puzzle captcha (general purpose) ─────────────────────────────────────
// Slide-the-piece verification. Its first consumer is the live chat's
// anonymous visitor flow; thanks to the scope parameter other screens (e.g.
// login) can reuse the same family later. The existing math-based form
// captcha (CAPTCHA constant) is untouched.
//
// Honest security note: the target is drawn client-side as a visual cutout;
// an advanced JS-running bot can read it from the DOM. The family's real
// value is in its layers: (1) the challenge must be fetched and solved via
// JS — bots that POST the form directly are eliminated outright, (2) solve
// time limit: a "solution" faster than 1 second is not human and is
// rejected, (3) 5 failed attempts lock for 60 seconds; the target is
// regenerated on every attempt, so brute-force odds stay independent of the
// attempt count. This is not a Turnstile-like service; its goal is to stop
// form-spam bots.

function pg_puzzle_captcha_state($scope)
{
    $scope = preg_replace('/[^a-z0-9_]/', '', (string) $scope);

    if (!isset($_SESSION['puzzle_captcha'][$scope]) || !is_array($_SESSION['puzzle_captcha'][$scope])) {
        $_SESSION['puzzle_captcha'][$scope] = array();
    }

    return $scope;
}

function pg_puzzle_captcha_challenge($scope)
{
    $scope = pg_puzzle_captcha_state($scope);
    $state = $_SESSION['puzzle_captcha'][$scope];

    if (isset($state['locked_until']) && time() < $state['locked_until']) {
        return array('locked' => true, 'retry_after' => (int) ($state['locked_until'] - time()));
    }

    // 14%-86%: keeps the piece on the rail and away from the edges, where
    // sticking to an end would be a free guess.
    $target = mt_rand(14, 86);

    $_SESSION['puzzle_captcha'][$scope]['target'] = $target;
    $_SESSION['puzzle_captcha'][$scope]['issued_at'] = microtime(true);
    $_SESSION['puzzle_captcha'][$scope]['solved'] = false;

    return array('locked' => false, 'target' => $target);
}

function pg_puzzle_captcha_verify($scope, $position)
{
    $scope = pg_puzzle_captcha_state($scope);
    $state = $_SESSION['puzzle_captcha'][$scope];

    if (isset($state['locked_until']) && time() < $state['locked_until']) {
        return array('ok' => false, 'locked' => true, 'retry_after' => (int) ($state['locked_until'] - time()));
    }

    if (!empty($state['solved'])) {
        return array('ok' => true);
    }

    if (!isset($state['target']) || !isset($state['issued_at'])) {
        return array('ok' => false, 'locked' => false);
    }

    $elapsed = microtime(true) - (float) $state['issued_at'];

    // A drag faster than 1 second is not human; a challenge older than 3
    // minutes is stale. In both cases this target is burned and a new one
    // must be requested.
    $position_ok = (abs((float) $position - (int) $state['target']) <= 4);

    if ($position_ok && $elapsed >= 1.0 && $elapsed <= 180.0) {
        $_SESSION['puzzle_captcha'][$scope]['solved'] = true;
        $_SESSION['puzzle_captcha'][$scope]['fails'] = 0;
        unset($_SESSION['puzzle_captcha'][$scope]['target']);

        return array('ok' => true);
    }

    unset($_SESSION['puzzle_captcha'][$scope]['target']);

    $fails = isset($state['fails']) ? (int) $state['fails'] : 0;
    $fails++;

    if ($fails >= 5) {
        $_SESSION['puzzle_captcha'][$scope]['locked_until'] = time() + 60;
        $_SESSION['puzzle_captcha'][$scope]['fails'] = 0;

        return array('ok' => false, 'locked' => true, 'retry_after' => 60);
    }

    $_SESSION['puzzle_captcha'][$scope]['fails'] = $fails;

    return array('ok' => false, 'locked' => false);
}

function pg_puzzle_captcha_solved($scope)
{
    $scope = pg_puzzle_captcha_state($scope);

    return !empty($_SESSION['puzzle_captcha'][$scope]['solved']);
}

function pg_puzzle_captcha_reset($scope)
{
    $scope = pg_puzzle_captcha_state($scope);

    $_SESSION['puzzle_captcha'][$scope] = array();
}


/**
 * Create and store a notification record.
 *
 * This helper inserts a notification row into the "notifications" table using the
 * provided properties. The function expects a single associative array argument
 * ($properties) that declares the notification attributes. At minimum, the
 * 'action' and 'title' keys are required; other keys are optional.
 *
 * Behavior and side-effects:
 * - If 'user' is not provided and $_SESSION['sessionusername'] exists, that value
 *   will be used as the user.
 * - Numeric identifier values (product_id, order_id, form_id, comment_id) are
 *   normalized to integers when provided; empty strings are left as empty.
 * - The function uses an escape() helper to sanitize values and inserts via
 *   mysqli_query against db::$con. The notification row sets 'readed' = 0 and
 *   'timestamp' = UNIX_TIMESTAMP().
 * - Returns the inserted row ID on success or boolean false on failure.
 *
 * Expected keys in $properties (all keys optional except action and title):
 * - action (string)    : REQUIRED. Short action identifier (e.g. "new_order",
 *                        "software_update", "custom", etc.).
 * - title (string)     : REQUIRED. The notification title/content (may contain
 *                        HTML if appropriate).
 * - type (string)      : Optional. Notification type/level (default: "info").
 *                        Typical values: "info", "success", "warning", "error".
 * - product_id (int|string) : Optional. Product identifier (will be cast to int).
 * - form_id (int|string)    : Optional. Form identifier (will be cast to int).
 * - order_id (int|string)   : Optional. Order identifier (will be cast to int).
 * - order_total (string)    : Optional. Order total or amount (kept as string).
 * - comment_id (int|string) : Optional. Comment identifier (will be cast to int).
 * - user (string)           : Optional. Username or label for who triggered the notification.
 * - send_to (string)        : Optional. Optional recipient identifier or routing info.
 *
 * Return values:
 * - int  : The mysqli_insert_id for the newly created notification on success.
 * - false: If input validation fails (not an array, missing action/title) or
 *          if the database insert fails.
 *
 * Notes / Preconditions:
 * - The function relies on an available mysqli connection in db::$con and a
 *   global escape() helper for value escaping/quoting. Ensure these are loaded.
 * - The function does not throw exceptions; it returns false on error.
 *
 * Examples:
 *
 * create_notification(array(
 *     'action' => 'software_update',
 *     'type'   => 'success',
 *     'title'  => 'Update available',
 *     'user'   => 'Software'
 * ));
 *
 * create_notification(array(
 *     'action'      => 'new_order',
 *     'order_id'    => 1234,
 *     'order_total' => '$12.33',
 *     'type'        => 'success',
 *     'title'       => '#1123'
 * ));
 *
 * create_notification(array(
 *     'action'     => 'out_stock',
 *     'type'       => 'warning',
 *     'product_id' => 1234,
 *     'title'      => 'C1123 - Short Description'
 * ));
 *
 * create_notification(array(
 *     'action' => 'custom',
 *     'type'   => 'error',
 *     'title'  => 'Something went wrong'
 * ));
 *
 * @param array $properties Associative array of notification properties (see above).
 * @return int|false Inserted notification ID on success, or false on failure.
 */
function create_notification($properties)
{
    // Expected properties (all optional except action and title):
    // action, type, title, product_id, form_id, order_id, order_total, comment_id, user, send_to
    if (!is_array($properties)) {
        return false;
    }

    $action = isset($properties['action']) ? trim($properties['action']) : '';
    $type = isset($properties['type']) ? trim($properties['type']) : 'info';
    $title = isset($properties['title']) ? $properties['title'] : '';
    $product_id = isset($properties['product_id']) ? $properties['product_id'] : '';
    $order_id = isset($properties['order_id']) ? $properties['order_id'] : '';
    $form_id = isset($properties['form_id']) ? $properties['form_id'] : '';
    $order_total = isset($properties['order_total']) ? $properties['order_total'] : '';
    $comment_id = isset($properties['comment_id']) ? $properties['comment_id'] : '';
    $user = isset($properties['user']) ? $properties['user'] : '';
    $send_to = isset($properties['send_to']) ? $properties['send_to'] : '';

    // Use session username when user not provided
    if (empty($user) && isset($_SESSION['sessionusername'])) {
        $user = $_SESSION['sessionusername'];
    }

    // Require at least action and title
    if ($action === '' || $title === '') {
        return false;
    }

    // Normalize numeric IDs to integers when provided
    $product_id = ($product_id === '' ? '' : (int) $product_id);
    $order_id = ($order_id === '' ? '' : (int) $order_id);
    $form_id = ($form_id === '' ? '' : (int) $form_id);
    $comment_id = ($comment_id === '' ? '' : (int) $comment_id);

    // Prepare query (use existing escape() helper)
    $query = "INSERT INTO notifications (
                action,
                type,
                title,
                product_id,
                form_id,
                order_id,
                comment_id,
                order_total,
                user,
                send_to,
                readed,
                timestamp
            ) VALUES (
                '" . escape($action) . "',
                '" . escape($type) . "',
                '" . escape($title) . "',
                '" . escape($product_id) . "',
                '" . escape($form_id) . "',
                '" . escape($order_id) . "',
                '" . escape($comment_id) . "',
                '" . escape($order_total) . "',
                '" . escape($user) . "',
                '" . escape($send_to) . "',
                '0',
                UNIX_TIMESTAMP()
            )";

    $result = mysqli_query(db::$con, $query);

    if ($result === false) {
        return false;
    }

    return mysqli_insert_id(db::$con);
}

/**
 * Record that a scheduled job finished.
 *
 * The cron entries themselves live outside the software — a crontab, Windows
 * Task Scheduler, a hosting control panel — so nothing here can ask whether a
 * job is scheduled. Recording that one finished is the only evidence the panel
 * will ever have, and it is enough: a job that used to finish and no longer
 * does is a job whose schedule has stopped.
 *
 * Written on COMPLETION, not at the start. One timestamp can carry one fact,
 * and "the work got done" is the more useful of the two: a job that is
 * scheduled correctly but fatals halfway through would report green forever if
 * the write happened first, which is the worst thing a health indicator can do.
 *
 * Not conditional on the request being CLI. Cron reaches these scripts as a
 * shell command on some hosts and as an HTTP request on others, and a manual
 * run from the panel still means the work happened — which is the question
 * this answers. Attributing the run to a scheduler rather than a person would
 * be a distinction without a difference here.
 *
 * Silent when the table is absent: these calls sit at the end of scripts that
 * have to keep working on an installation where the 2026.4.9 upgrade has not
 * been run yet.
 *
 * @param string $job_name Script base name, e.g. "email_campaign_job".
 * @return bool True when the run was recorded.
 */
function pg_cron_ran($job_name)
{
    static $table_exists = null;

    if ($table_exists === null) {
        $table_exists = (bool) db_item("SHOW TABLES LIKE 'cron_runs'");
    }

    if (!$table_exists) {
        return false;
    }

    db(
        "INSERT INTO cron_runs (job_name, last_run_at)
         VALUES ('" . e($job_name) . "', UNIX_TIMESTAMP())
         ON DUPLICATE KEY UPDATE last_run_at = UNIX_TIMESTAMP()");

    return true;
}

/**
 * Last completion time per job, keyed by job name.
 *
 * Returns null — not an empty array — when the table does not exist yet, so a
 * caller can tell "nothing recorded" apart from "cannot know" and stay quiet
 * rather than reporting every job as broken on an installation that simply has
 * not been upgraded.
 *
 * @return array<string,int>|null
 */
function pg_cron_last_runs()
{
    if (!db_item("SHOW TABLES LIKE 'cron_runs'")) {
        return null;
    }

    $runs = array();

    foreach (db_items("SELECT job_name, last_run_at FROM cron_runs") as $row) {
        $runs[$row['job_name']] = (int) $row['last_run_at'];
    }

    return $runs;
}

/**
 * Catalogue of the scheduled jobs this software ships with.
 *
 * One table, three readers: the settings screen builds its switches from it,
 * the maintenance panel builds its health list from it, and the general job
 * dispatches from it. A job present in one of those places and missing from
 * another is the failure this exists to prevent.
 *
 * Keys are the names each script writes through pg_cron_ran(), which is what
 * ties a row in cron_runs back to an entry here.
 *
 * - label       Shown to the operator.
 * - script      File to run, relative to this directory.
 * - interval    How long the dispatcher waits before running it again, in
 *               seconds. Follows the recommended schedule printed next to the
 *               job's command on the settings screen.
 * - stale_after How long the maintenance panel waits before calling a job
 *               that used to finish stalled. Deliberately generous: an alert
 *               that cries wolf teaches the operator to scroll past it.
 * - dispatch    False for the general job, which is the host rather than a
 *               candidate.
 *
 * Order is the display order, and it is also the tie-break used when several
 * jobs are equally overdue - which is why the SEO score job is listed before
 * the structure job, whose input it produces.
 *
 * @return array<string,array>
 */
function pg_cron_jobs()
{
    return array(
        'job' => array(
            'label'       => lang('General job'),
            'script'      => 'job.php',
            'interval'    => 300,
