/**
 * Human wording for a dispatch interval, for the settings screen.
 *
 * Only the three cadences the shipped jobs actually use get a sentence of
 * their own; anything else an operator configures falls back to hours, which
 * is accurate without needing a phrase per value.
 *
 * @param int $seconds
 * @return string
 */
function pg_cron_interval_label($seconds)
{
    $seconds = (int) $seconds;

    if ($seconds == 300) {
        return lang('every 5 minutes');
    }

    if ($seconds == 86400) {
        return lang('once a day');
    }

    if ($seconds == 604800) {
        return lang('once a week');
    }

    $hours = (int) round($seconds / 3600);

    if ($hours < 1) {
        $hours = 1;
    }

    return lang(array(
        'string' => 'every {var:1} hour{suffix:1}',
        'vars'   => $hours,
        'suffix' => (($hours == 1) ? '' : 's'),
    ));
}

/**
 * Job names the operator has allowed the general job to dispatch.
 *
 * Empty whenever the master switch is off, so a caller never has to check
 * both. The constants come from the config row like every other feature flag,
 * and default to off when the columns are not there yet.
 *
 * @return array<int,string>
 */
function pg_cron_dispatch_list()
{
    if (!defined('JOB_DISPATCH_ENABLED') || !JOB_DISPATCH_ENABLED) {
        return array();
    }

    if (!defined('JOB_DISPATCH') || (JOB_DISPATCH === '')) {
        return array();
    }

    $names = array();

    foreach (explode(',', JOB_DISPATCH) as $name) {

        $name = trim($name);

        if ($name !== '') {
            $names[] = $name;
        }
    }

    return $names;
}

/**
 * Choose the job the general job should run in this tick, and take the lock.
 *
 * Returns a path rather than running anything itself, because the caller has
 * to include it at global scope: included from inside a function, a job's
 * top-level code would execute in that function's local scope and every
 * variable it sets would be invisible to the functions it calls.
 *
 * @return string Absolute path of the script to include, or '' for nothing.
 */
function pg_cron_dispatch_next()
{
    $allowed = pg_cron_dispatch_list();

    if (!$allowed) {
        return '';
    }

    // null means the cron_runs table does not exist, and that table is the
    // whole basis of the decision below. Without it every job would look
    // overdue on every tick.
    $runs = pg_cron_last_runs();

    if ($runs === null) {
        return '';
    }

    $jobs = pg_cron_jobs();
    $now = time();
    $due = array();

    foreach ($jobs as $name => $job) {

        if (!$job['dispatch']) {
            continue;
        }

        if (!in_array($name, $allowed, true)) {
            continue;
        }

        if (!file_exists(dirname(__FILE__) . '/' . $job['script'])) {
            continue;
        }

        $last_run = isset($runs[$name]) ? (int) $runs[$name] : 0;

        // A job that also has its own crontab entry writes this timestamp
        // itself, whoever started it, so it never looks overdue here and is
        // never run twice. That is the entire double-run guard - the measure
        // corrects itself and there is no second bookkeeping to keep in step.
        if (($now - $last_run) < (int) $job['interval']) {
            continue;
        }

        $due[$name] = $last_run;
    }

    if (!$due) {
        return '';
    }

    // Longest waiting first, so a rotation forms by itself and nothing
    // starves. Strict comparison keeps the catalogue order on a tie, which is
    // what puts the SEO score job ahead of the structure job on a site where
    // both were just switched on.
    $selected = '';
    $selected_run = 0;

    foreach ($due as $name => $last_run) {

        if (($selected === '') || ($last_run < $selected_run)) {
            $selected = $name;
            $selected_run = $last_run;
        }
    }

    // One dispatched job at a time for the whole site. The general job runs
    // every five minutes and several of these take longer than that, so
    // without a lock a slow campaign send or a large backup would be started
    // again while the first one is still running.
    //
    // The lock expires on its own. pg_cron_dispatch_finished() releases it at
    // the end of a normal run and after a fatal error, but a process killed
    // outright runs no shutdown handler, and a lock that nothing can clear
    // would stop every tick from then on.
    $lock_seconds = defined('JOB_DISPATCH_LOCK_SECONDS') ? (int) JOB_DISPATCH_LOCK_SECONDS : 3600;

    if ($lock_seconds < 60) {
        $lock_seconds = 60;
    }

    db(
        "UPDATE config
        SET job_dispatch_lock_until = UNIX_TIMESTAMP() + " . (int) $lock_seconds . "
        WHERE job_dispatch_lock_until < UNIX_TIMESTAMP()");

    // Nothing updated means another tick holds the lock. Two ticks landing in
    // the same second also report nothing updated, because the value would be
    // identical - which errs towards running nothing, the safe direction.
    if (mysqli_affected_rows(db::$con) < 1) {
        return '';
    }

    pg_cron_dispatch_current($selected);

    return dirname(__FILE__) . '/' . $jobs[$selected]['script'];
}

/**
 * Name of the job the general job is running in this tick.
 *
 * Set once by pg_cron_dispatch_next(); read by the output handler, which has
 * no other way to know whose message it is holding.
 *
 * @param string|null $name
 * @return string
 */
function pg_cron_dispatch_current($name = null)
{
    static $value = '';

    if ($name !== null) {
        $value = (string) $name;
    }

    return $value;
}

/**
 * Output buffer handler for a dispatched job.
 *
 * These scripts are each written to be a whole request, and some of them print
 * an error page and stop when their own settings are missing - the campaign job
 * does exactly that without SMTP settings. Printed from inside the general job
 * that lands in its output: mailed by cron every five minutes on a
 * misconfigured site, or rendered into the page when someone opens job.php in a
 * browser to trigger it by hand.
 *
 * Returning an empty string discards it. A buffer handler is used rather than a
 * shutdown handler because it runs however the buffer ends - a normal return,
 * exit() from the middle of the job's own flow, or a fatal error - and does not
 * depend on the order shutdown handlers were registered in.
 *
 * The message is not lost: it goes to the site log, once a day per job. The
 * job's health signal is unaffected either way, because a script that stops
 * early never reaches its own pg_cron_ran() call and the maintenance panel
 * goes on reporting it as never having finished.
 *
 * @param string $buffer
 * @return string
 */
function pg_cron_dispatch_output($buffer)
{
    $message = trim(preg_replace('/\s+/', ' ', strip_tags((string) $buffer)));

    if ($message === '') {
        return '';
    }

    // A fatal error can end the run with the connection already gone, and
    // there is no reporting anything from here without it.
    if (!isset(db::$con) || !db::$con) {
        return '';
    }

    $name = pg_cron_dispatch_current();

    if ($name === '') {
        return '';
    }

    // Once a day per job, the same throttle the structure job uses for its
    // missing-DOM warning. A job that prints because its own settings are
    // missing prints on every turn, which is 288 identical log lines a day.
    $marker = $name . '_output';
    $last_logged = (int) db_value("SELECT last_run_at FROM cron_runs WHERE job_name = '" . e($marker) . "'");

    if ($last_logged < (time() - 86400)) {

        $jobs = pg_cron_jobs();
        $label = isset($jobs[$name]) ? $jobs[$name]['label'] : $name;

        log_activity(
            lang(array(
                'string' => '{var:1} printed a message while running with the general job: {var:2}',
                'vars'   => array($label, truncate($message, 500)),
            )),
            '');

        pg_cron_ran($marker);
    }

    return '';
}

/**
 * Release the dispatch lock.
 *
 * Registered as a shutdown handler by the general job so that it also runs
 * when the dispatched script calls exit(), which several of them do from
 * inside their own control flow, and when the run ends in a fatal error.
 *
 * @return void
 */
function pg_cron_dispatch_finished()
{
    db("UPDATE config SET job_dispatch_lock_until = 0");
}

/**
 * Truncate a string to a specified length and optionally append a suffix (default "...").
 *
 * Safety and multibyte support:
 * - Casts inputs to expected types for safety.
 * - Uses mbstring functions when available (UTF-8).
 * - Falls back to single-byte functions when mbstring is not available (compatible with PHP 7.0+ and PHP 8+).
 *
 * Behavior:
 * - If $length <= 0 returns an empty string.
 * - If the original string length is <= $length returns the original string.
 * - If $dots length does not fit into $length, returns the first $length characters of $dots.
 *
 * Examples:
 *   truncate('A long text', 8) => 'A lo...'
 *   truncate('Short', 10)      => 'Short'
 *
 * @param string $string Text to truncate
 * @param int    $length Maximum length (including the dots)
 * @param string $dots   Suffix to append when truncated (default "...")
 * @return string Truncated or original text
 */
function truncate($string, $length, $dots = "...")
{
    // Type coercion for safety
    $string = (string) $string;
    $length = (int) $length;
    $dots = (string) $dots;

    if ($length <= 0) {
        return '';
    }

    // Use mbstring when available for multibyte-safe operations
    if (function_exists('mb_strlen') && function_exists('mb_substr')) {
        $encoding = 'UTF-8';
        $strLen = mb_strlen($string, $encoding);
        $dotsLen = mb_strlen($dots, $encoding);

        if ($strLen <= $length) {
            return $string;
        }

        $keep = $length - $dotsLen;

        if ($keep <= 0) {
            // If the dots themselves exceed the target length, return the first $length chars of dots
            return mb_substr($dots, 0, $length, $encoding);
        }

        return mb_substr($string, 0, $keep, $encoding) . $dots;
    }

    // Fallback when mbstring is not available (assumes single-byte encoding)
    $strLen = strlen($string);
    $dotsLen = strlen($dots);

    if ($strLen <= $length) {
        return $string;
    }

    $keep = $length - $dotsLen;

    if ($keep <= 0) {
        return substr($dots, 0, $length);
    }

    return substr($string, 0, $keep) . $dots;
}


// Fixes an issue that broke access to the settings page that occurred in some php versions.(php version < 7.3)
if (!function_exists("array_key_last")) {
    function array_key_last($array)
    {
        if (!is_array($array) || empty($array)) {
            return NULL;
        }
        return array_keys($array)[count($array) - 1];
    }
}

/**
 * Get size of a directory (bytes). Uses SPL iterators, skips unreadable files.
 * Compatible with PHP 7.0+ and PHP 8.x (no type hints / return types).
 *
 * @param string $dir
 * @param bool   $follow_symlinks
 * @return int Bytes (cast to int; on 32-bit platforms very large dirs may overflow)
 */
function folderSize($dir, $follow_symlinks = false)
{
    $dir = rtrim((string) $dir, "/\\");
    if ($dir === '' || !is_dir($dir)) {
        return 0;
    }

    $size = 0.0; // use float to reduce risk of intermediate overflow on 32-bit

    // Base flags: skip dot entries
    $flags = FilesystemIterator::SKIP_DOTS;

    // Try to add FOLLOW_SYMLINKS if requested and the constant exists.
    // Use constant() with error suppression to remain compatible across PHP versions.
    if ($follow_symlinks) {
        $followConst = @constant('FilesystemIterator::FOLLOW_SYMLINKS');
        if ($followConst !== null && $followConst !== false) {
            $flags |= $followConst;
        }
    }

    try {
        $rdi = new RecursiveDirectoryIterator($dir, $flags);
        $it = new RecursiveIteratorIterator($rdi, RecursiveIteratorIterator::SELF_FIRST);

        foreach ($it as $file) {
            // Ensure we have an SplFileInfo-like object
            if (!($file instanceof SplFileInfo)) {
                continue;
            }

            // Only count regular files (skip directories, links themselves, etc.)
            if ($file->isFile()) {
                // Determine readability in a safe way (method may not exist on some custom objects)
                $readable = false;
                if (is_callable(array($file, 'isReadable'))) {
                    $readable = $file->isReadable();
                } else {
                    $pathname = $file->getPathname();
                    $readable = is_readable($pathname);
                }

                // Use getSize() when possible; suppress warnings and ensure integer cast
                $fileSize = 0;
                if ($readable) {
                    $tmp = @$file->getSize();
                    $fileSize = ($tmp === false || $tmp === null) ? 0 : (int) $tmp;
                }

                $size += (float) $fileSize;
            }
        }
    } catch (UnexpectedValueException $e) {
        // Directory not accessible (permissions, broken symlink, etc.)
        return 0;
    } catch (Exception $e) {
        return 0;
    }

    // Return as int. On 32-bit this may overflow for very large totals.
    return (int) $size;
}

/**
 * Determine that URL exists or not.
 *
 * Compatible with PHP 7.0 - 8.5 Uses cURL when available, falls back to get_headers().
 *
 * @param string $url Absolute URL to check.
 * @return bool True if the resource exists (HTTP status 2xx or 3xx), false otherwise.
 */
function url_exists($url)
{
    if (empty($url)) {
        return false;
    }

    // Validate URL
    $url = filter_var($url, FILTER_VALIDATE_URL);
    if ($url === false) {
        return false;
    }

    // Prefer cURL if available
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        // Identify this installation on outgoing requests. Sent with no
        // User-Agent, a request looks like an anonymous client to the receiving
        // server's firewall and gets rejected — which is how Pinegrap ended up
        // blocking its own licence and update checks.
        curl_setopt($ch, CURLOPT_USERAGENT, function_exists('pinegrap_user_agent') ? pinegrap_user_agent() : 'Pinegrap');

        // Basic options: don't fetch body, return transfer, small timeouts
        $options = array(
            CURLOPT_NOBODY => true,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HEADER => false,
            CURLOPT_CONNECTTIMEOUT => 5,
            CURLOPT_TIMEOUT => 10,
            // Keep verification off to preserve prior behavior across environments.
            // If you want stricter TLS checks, set these to true/2.
            CURLOPT_SSL_VERIFYPEER => false,
            CURLOPT_SSL_VERIFYHOST => 0,
        );

        // CURLOPT_FOLLOWLOCATION cannot be used when open_basedir is set.
        // Only set it when safe to do so.
        $openBaseDir = ini_get('open_basedir');
        if (empty($openBaseDir)) {
            $options[CURLOPT_FOLLOWLOCATION] = true;
            // Limit number of redirects to avoid infinite loops
            $options[CURLOPT_MAXREDIRS] = 5;
        }

        curl_setopt_array($ch, $options);

        // Execute
        $exec = @curl_exec($ch);

        // Get HTTP status code
        $httpCode = 0;
        if ($ch) {
            $httpCode = (int) @curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
        }

        // Consider resource existing if status is 2xx or 3xx
        return ($httpCode >= 200 && $httpCode < 400);
    }

    // Fallback: get_headers (works without cURL)
    $headers = @get_headers($url);
    if ($headers === false || count($headers) === 0) {
        return false;
    }

    // First header contains the HTTP status line, e.g. "HTTP/1.1 200 OK"
    $statusLine = $headers[0];
    if (preg_match('#HTTP/\d+\.\d+\s+(\d+)#i', $statusLine, $m)) {
        $code = (int) $m[1];
        return ($code >= 200 && $code < 400);
    }

    return false;
}

// Software localization / translation helper.
// Usage scenarios:
//   echo lang('Hello World');
//   echo lang(array('string' => 'Hello {var:1}', 'vars' => array('World')));
//   echo lang(array('string' => 'Welcome {var:1|c}', 'vars' => array('john doe'))); // capitalize variable
//   echo lang(array('string' => 'Count: {var:1}', 'vars' => 5));
//   $lang = lang(array('info' => true)); // returns enforced or configured SOFTWARE_LANGUAGE (e.g. 'en' or 'tr')
//
// Notes:
// - Works on PHP 7.0 up to PHP 8.5.
// - Looks for JSON translation files in assets/local/{lang}.json relative to this file or cwd.
// - If mbstring is not available, falls back to single-byte string helpers.
// - in english language file you can overwrite strings.
function lang($properties = false)
{
    static $translations = array(); // cache translations per language

    // Helper: safe multibyte case conversion with fallbacks
    $safe_case = function ($text, $mode) {
        if (!is_string($text)) {
            $text = (string) $text;
        }
        if (function_exists('mb_convert_case')) {
            switch ($mode) {
                case 'title':
                    return mb_convert_case($text, MB_CASE_TITLE, "UTF-8");
                case 'upper':
                    return mb_convert_case($text, MB_CASE_UPPER, "UTF-8");
                case 'lower':
                    return mb_convert_case($text, MB_CASE_LOWER, "UTF-8");
                default:
                    return $text;
            }
        }
        // Fallbacks when mbstring not available
        switch ($mode) {
            case 'title':
                return ucwords(strtolower($text));
            case 'upper':
                return strtoupper($text);
            case 'lower':
                return strtolower($text);
            default:
                return $text;
        }
    };

    // If explicit info request (get current software language)
    if (is_array($properties) && isset($properties['info'])) {
        if (defined('ENFORCEMENT_SOFTWARE_LANGUAGE') && ENFORCEMENT_SOFTWARE_LANGUAGE) {
            return ENFORCEMENT_SOFTWARE_LANGUAGE;
        }
        if (defined('SOFTWARE_LANGUAGE') && SOFTWARE_LANGUAGE) {
            return SOFTWARE_LANGUAGE;
        }
        return 'en';
    }

    // Normalize input: allow lang('text') or lang(array(...))
    $string = '';
    $vars = null;
    $suffixes = null;
    if (is_array($properties)) {
        if (isset($properties['string'])) {
            $string = (string) $properties['string'];
        }
        if (isset($properties['vars'])) {
            $vars = $properties['vars'];
        }
        if (isset($properties['suffix'])) {
            $suffixes = $properties['suffix'];
        }
    } else {
        // properties may be scalar string or null/false
        $string = ($properties === null || $properties === false) ? '' : (string) $properties;
    }

    // quick return for empty string
    if ($string === '') {
        return '';
    }

    // Determine selected language (en default)
    $selected_software_language = 'en';
    if (defined('ENFORCEMENT_SOFTWARE_LANGUAGE') && ENFORCEMENT_SOFTWARE_LANGUAGE) {
        $selected_software_language = ENFORCEMENT_SOFTWARE_LANGUAGE;
    } elseif (defined('SOFTWARE_LANGUAGE') && SOFTWARE_LANGUAGE) {
        $selected_software_language = SOFTWARE_LANGUAGE;
    }

    // Load translations for language (cache)
    if (!isset($translations[$selected_software_language])) {
        $translations[$selected_software_language] = array();
        $json = false;

        // Prefer absolute path relative to this file
        $pathsToTry = array(
            __DIR__ . '/assets/local/' . $selected_software_language . '.json',
            'assets/local/' . $selected_software_language . '.json',
            dirname(__FILE__) . '/assets/local/' . $selected_software_language . '.json'
        );

        foreach ($pathsToTry as $path) {
            if (file_exists($path) && is_readable($path)) {
                $json = @file_get_contents($path);
                if ($json !== false) {
                    break;
                }
            }
        }

        if ($json !== false) {
            $decoded = @json_decode($json, true);
            if (is_array($decoded)) {
                $translations[$selected_software_language] = $decoded;
            } else {
                // keep empty array on decode failure
                $translations[$selected_software_language] = array();
            }
        }
    }

    // If translation exists, replace string
    if (isset($translations[$selected_software_language][$string])) {
        $string = $translations[$selected_software_language][$string];
    }


    // Replace variables {var}, {var:1}, with optional modifiers |c |u |l
    if ($vars !== null) {
        // Normalize single scalar to first var
        if (!is_array($vars)) {
            $vars = array($vars);
        }

        foreach ($vars as $index => $value) {
            $pos = $index + 1;
            $replacement = $value;

            // Look for modifier patterns {var:N|c} {var:N|u} {var:N|l}
            if (strpos($string, '{var:' . $pos . '|c}') !== false || strpos($string, '{var|' . ($pos) . '|c}') !== false) {
                $replacement = $safe_case($replacement, 'title');
                $string = str_replace('{var:' . $pos . '|c}', '{var:' . $pos . '}', $string);
                $string = str_replace('{var|' . ($pos) . '|c}', '{var:' . $pos . '}', $string);
            } elseif (strpos($string, '{var:' . $pos . '|u}') !== false || strpos($string, '{var|' . ($pos) . '|u}') !== false) {
                $replacement = $safe_case($replacement, 'upper');
                $string = str_replace('{var:' . $pos . '|u}', '{var:' . $pos . '}', $string);
                $string = str_replace('{var|' . ($pos) . '|u}', '{var:' . $pos . '}', $string);
            } elseif (strpos($string, '{var:' . $pos . '|l}') !== false || strpos($string, '{var|' . ($pos) . '|l}') !== false) {
                $replacement = $safe_case($replacement, 'lower');
                $string = str_replace('{var:' . $pos . '|l}', '{var:' . $pos . '}', $string);
                $string = str_replace('{var|' . ($pos) . '|l}', '{var:' . $pos . '}', $string);
            }

            // Also support shorthand {var|c} or {var} when only one var placeholder exists
            if ($pos === 1) {
                if (strpos($string, '{var|c}') !== false) {
                    $replacement = $safe_case($replacement, 'title');
                    $string = str_replace('{var|c}', '{var:1}', $string);
                } elseif (strpos($string, '{var|u}') !== false) {
                    $replacement = $safe_case($replacement, 'upper');
                    $string = str_replace('{var|u}', '{var:1}', $string);
                } elseif (strpos($string, '{var|l}') !== false) {
                    $replacement = $safe_case($replacement, 'lower');
                    $string = str_replace('{var|l}', '{var:1}', $string);
                }
            }

            // Final replacements
            $string = str_replace('{var:' . $pos . '}', $replacement, $string);
        }
    }

    // Replace suffix placeholders {suffix} and {suffix:N}
    if ($suffixes !== null) {
        if (!is_array($suffixes)) {
            $suffixes = array($suffixes);
        }
        foreach ($suffixes as $index => $sval) {
            $pos = $index + 1;
            $string = str_replace('{suffix:' . $pos . '}', $sval, $string);
        }
        // generic {suffix} => first suffix if exists
        if (strpos($string, '{suffix}') !== false) {
            $first = isset($suffixes[0]) ? $suffixes[0] : '';
            $string = str_replace('{suffix}', $first, $string);
        }
    }

    return $string;
}

// This function get mime type name from file extention
// example: get_mime_type('gif') returns that : image/gif
function get_mime_type($file_extention)
{
    switch ($file_extention) {
        case 'jpeg':
        case 'jpg':
        case 'jpe':
            $output = 'image/jpeg';
            break;
        case 'gif':
            $output = 'image/gif';
            break;
        case 'tif':
        case 'tiff':
            $output = 'image/tiff';
            break;
        case 'psd':
            $output = 'image/vnd.adobe.photoshop';
            break;
        case 'webp':
            $output = 'image/webp';
            break;
        case 'svg':
        case 'svgz':
            $output = 'image/svg+xml';
            break;
        case 'bmp':
            $output = 'image/bmp';
            break;
        case 'ico':
            $output = 'image/x-icon';
            break;
        case 'ico':
            $output = 'image/x-icon';
            break;
        case 'png':
            $output = 'image/png';
            break;
        case 'pdf':
            $output = 'application/pdf';
            break;
        case 'mpeg':
        case 'mp2':
        case 'mp2a':
        case 'mp3':
        case 'mpga':
            $output = 'audio/mpeg';
            break;
        case 'midi':
        case 'mid':
            $output = 'audio/midi';
            break;
        case 'avi':
            $output = 'video/x-msvideo';
            break;
        case 'mov':
            $output = 'video/quicktime';
            break;
        case 'mp4':
        case 'mp4v':
        case 'mpg4':
            $output = 'video/mp4';
            break;
    }
    return $output;
}

// Detect mime type from file path using mime_content_type, finfo, or fallback
function detect_mime_type($file_path)
{
    if (function_exists('mime_content_type')) {
        return mime_content_type($file_path);
    }

    if (function_exists('finfo_open')) {
        $const = defined('FILEINFO_MIME_TYPE') ? FILEINFO_MIME_TYPE : FILEINFO_NONE;
        $finfo = @finfo_open($const);
        if ($finfo) {
            $mime = finfo_file($finfo, $file_path);
            finfo_close($finfo);
            if ($mime !== false) {
                return $mime;
            }
        }
    }

    // Fallback: guess by extension
    $ext = strtolower(pathinfo($file_path, PATHINFO_EXTENSION));
    $map = [
        'jpg' => 'image/jpeg',
        'jpeg' => 'image/jpeg',
        'png' => 'image/png',
        'gif' => 'image/gif',
        'webp' => 'image/webp'
    ];
    return $map[$ext] ?? 'application/octet-stream';
}

/**
 * Get a short version string derived from VERSION constant.
 *
 * Improvements for PHP 7.0 - 8.5 compatibility:
 * - Accepts VERSION values like "1.2.3", "v1.2", "12", "SETUP" and preserves fallback behavior.
 * - Safely handles non-numeric versions (falls back to last 2 chars of the major segment).
 * - Uses mb_substr when available to be multibyte-safe.
 * - Defensive casts and sanitization to avoid warnings on older PHP builds.
 *
 * Returns either "XX.Y" (major last 2 digits + dot + minor) or "XX" (major last 2 digits or full major).
 */
function get_short_version()
{
    if (!defined('VERSION')) {
        define('VERSION', 'SETUP');
    }

    // Ensure we are working with a string
    $version = (string) VERSION;

    // Helper: multibyte-safe substr wrapper
    $sub = function ($str, $start, $length = null) {
        if (function_exists('mb_substr')) {
            if ($length === null) {
                return mb_substr($str, $start);
            }
            return mb_substr($str, $start, $length);
        }
        if ($length === null) {
            return substr($str, $start);
        }
        return substr($str, $start, $length);
    };

    // Trim and remove any leading non-digit characters (e.g. leading "v")
    $version_trimmed = trim($version);
    $version_trimmed = preg_replace('/^[^\d]*/', '', $version_trimmed);

    // If trimming removed everything (e.g. "SETUP"), fall back to original
    if ($version_trimmed === '') {
        $version_trimmed = $version;
    }

    $parts = explode('.', $version_trimmed);
    $major_raw = isset($parts[0]) ? (string) $parts[0] : '';
    $minor_raw = isset($parts[1]) ? (string) $parts[1] : null;

    // Try to extract digits from major; if none, we'll use the raw major string later
    $major_digits = preg_replace('/\D+/', '', $major_raw);

    if ($major_digits === '') {
        // no numeric digits found, use last 2 chars of raw major (mimics original behavior)
        $major_short = $sub($major_raw, max(0, strlen($major_raw) - 2));
    } else {
        // use last two digits if available
        $major_short = (strlen($major_digits) > 2) ? $sub($major_digits, -2) : $major_digits;
    }

    if ($minor_raw !== null && $minor_raw !== '') {
        // sanitize minor to remove non-digits but keep a fallback to raw minor
        $minor_digits = preg_replace('/\D+/', '', $minor_raw);
        $minor_output = ($minor_digits === '') ? $minor_raw : $minor_digits;
        return $major_short . '.' . $minor_output;
    }

    return $major_short;
}


// this function outputs the includes for the files needed for the control panel
function output_control_panel_header_includes()
{
    $help_url = '';
    // If the site is not private labeled, then get help URL.  We hide the help button if site
    // is private labeled, so no reason to get help url.
    if (!defined('PRIVATE_LABEL') or PRIVATE_LABEL != true) {
        require(dirname(__FILE__) . '/get_help_url.php');
        $languageinfo = lang(array('info' => ''));
        $help_url = get_help_url(array('languageinfo' => $languageinfo));
    }

    if (defined('DB_CONNECTED')) {
        $query = "SELECT custom_css FROM config";
        $result = mysqli_query(db::$con, $query) or exit(mysqli_error(db::$con));
        $row = mysqli_fetch_assoc($result);
        define('CUSTOM_CSS', $row['custom_css']);
    }

    if (!defined('CONTROL_PANEL_STYLESHEET_URL')) {
        define(
            'CONTROL_PANEL_STYLESHEET_URL',
            PATH . SOFTWARE_DIRECTORY . '/assets/backend.src.css?v=' .
            @filemtime(dirname(__FILE__) . '/assets/backend.src.css')
        );
    }
    if (!defined('CUSTOM_CSS')) {
        define('CUSTOM_CSS', '');
    }



    return '
