        } else {
            //else generate icon
            $output_menu_item_icon = '<svg style="font-size:10px" width="16px" height="16px" class="me-2 ' . $options['color_class'] . '" data-name="empty icon" fill="currentcolor" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16"><text transform="translate(5 12)"><tspan x="0" y="0">' . substr(lang($options['title']), 0, 1) . '</tspan></text><path d="M8,.55C3.89.55.55,3.89.55,8s3.34,7.45,7.45,7.45,7.45-3.34,7.45-7.45S12.11.55,8,.55ZM8,14.86c-3.79,0-6.86-3.07-6.86-6.86S4.21,1.14,8,1.14s6.86,3.07,6.86,6.86-3.07,6.86-6.86,6.86Z"/></svg>';

        }

        $output_all_menu_items .= '<a id="menu_item_' . $options['id'] . '" ' . $context_enabled . $context_content . ' class="list-group-item list-group-item-action border-0' . $active_menu_class . '" title="' . lang($options['title']) . '" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/' . $options['href'] . '" ' . $output_parent_target . '>' . $output_menu_item_icon . '<span class="list-group-text">' . lang($options['title']) . '</span></a>';


    }
    // output full menu.
    return $output_all_menu_items;
}

// license_check()
// PHP 7.0 - 8.5 compatible helper to validate and display subscription/license status.
// Improvements:
//  - Robust input checks and fallbacks (cURL or file_get_contents).
//  - Safer JSON handling and session updates.
//  - Clear docblock and conservative use of language/features compatible with PHP 7.0+.
//  - Keeps original behavior: returns different outputs depending on $properties['output']
//    ('bar' returns HTML fragment for header bar, 'text' returns 'licensed'/'not_licensed',
//     otherwise it will block access and display a promotional/licensing page).
function license_check($properties = false)
{
    // Simple doc / usage:
    // license_check(); // default behavior - may exit() if not licensed
    // license_check(array('output'=>'bar')); // returns header bar HTML or '' if no key
    // license_check(array('output'=>'text')); // returns 'licensed' or 'not_licensed'
    global $user;

    // normalize properties
    $output_information = '';
    if (is_array($properties) && isset($properties['output'])) {
        $output_information = $properties['output'];
    }

    $output_notice_title_classes = '';
    $output_counter = '';
    $output_license_status_color_class = '';
    $output_extend_license_button = '';
    $output_check_license_button = '';
    $license_valid = false;

    // Use DateTime for date arithmetic, use today without time
    try {
        $today = new DateTime('today');
    } catch (Exception $e) {
        // fallback: create from formatted string
        $today = new DateTime(date('Y-m-d'));
    }

    // Ensure SUBSCRIPTION_KEY constant exists and is not empty
    if (defined('SUBSCRIPTION_KEY') && trim(SUBSCRIPTION_KEY) !== '') {

        // initialize session array path
        if (!isset($_SESSION['software'])) {
            $_SESSION['software'] = array();
        }
        if (!isset($_SESSION['software']['settings'])) {
            $_SESSION['software']['settings'] = array();
        }
        if (!isset($_SESSION['software']['settings']['license'])) {
            $_SESSION['software']['settings']['license'] = array();
        }

        // Determine whether we should force-check the license (GET param) or re-check after 12 hours
        // Only manager-level and above (role <= 2) may trigger an immediate re-check;
        // this prevents lower-privilege users from hammering the license server on every request.
        $force_check = false;
        if (isset($_GET['check_license_again']) && $_GET['check_license_again']) {
            if (isset($user['role']) && (int) $user['role'] <= 2) {
                $force_check = true;

            }
        }

        $last_check = isset($_SESSION['software']['settings']['license']['last_check']) ? (int) ($_SESSION['software']['settings']['license']['last_check'] ?? '') : 0;
        $need_check = $force_check || (empty($_SESSION['software']['settings']['license']['status'])) || ((time() - $last_check) > 43200);

        if ($need_check) {
            // Clear previous license indicators (we'll set again below)
            $_SESSION['software']['settings']['license']['status'] = '';
            $_SESSION['software']['settings']['license']['error_code'] = '';
            $_SESSION['software']['settings']['license']['countdown'] = '';
            $_SESSION['software']['settings']['license']['expiration_date_formatted'] = '';

            // Prepare request payload
            $request = array(
                'hostname' => (defined('HOSTNAME_SETTING') ? HOSTNAME_SETTING : (isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '')),
                'url' => (defined('URL_SCHEME') && defined('HOSTNAME_SETTING') && defined('PATH') ? (URL_SCHEME . HOSTNAME_SETTING . PATH) : ''),
                'version' => (defined('VERSION') ? VERSION : ''),
                'edition' => (defined('EDITION') ? EDITION : ''),
                'uname' => function_exists('php_uname') ? php_uname() : '',
                'os' => defined('PHP_OS') ? PHP_OS : (function_exists('php_uname') ? php_uname('s') : ''),
                'web_server' => isset($_SERVER['SERVER_SOFTWARE']) ? $_SERVER['SERVER_SOFTWARE'] : '',
                'php_version' => function_exists('phpversion') ? phpversion() : '',
                // mysql_version - try safe call; db() helper used elsewhere in file, keep same approach
                'mysql_version' => function_exists('db') ? db("SELECT VERSION()") : '',
                'installer' => (defined('INSTALLER') ? INSTALLER : ''),
                'private_label' => (defined('PRIVATE_LABEL') ? PRIVATE_LABEL : false),
            );

            $data = encode_json($request);
            $subscription_key_clean = str_replace('-', '', SUBSCRIPTION_KEY);
            $api_url = 'https://www.kodpen.com/api2?API=59593DS72233483322T669223344&REQUEST=license&LICENSE=' . h($subscription_key_clean);

            $response = false;
            $curl_errno = 0;
            $curl_error = '';

            // Prefer cURL if available
            if (function_exists('curl_init')) {
                $ch = curl_init();
                // Identify this installation on outgoing requests. Sent with no
                // User-Agent, a request looks like an anonymous client to the receiving
                // server's firewall and gets rejected — which is how Pinegrap ended up
                // blocking its own licence and update checks.
                curl_setopt($ch, CURLOPT_USERAGENT, function_exists('pinegrap_user_agent') ? pinegrap_user_agent() : 'Pinegrap');
                curl_setopt($ch, CURLOPT_URL, $api_url);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
                curl_setopt($ch, CURLOPT_TIMEOUT, 10);
                curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 10);
                curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
                curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0);
                curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
                // send JSON POST
                curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
                curl_setopt($ch, CURLOPT_FORBID_REUSE, true);
                curl_setopt($ch, CURLOPT_POST, 1);
                curl_setopt($ch, CURLOPT_HTTPHEADER, array(
                    'Content-Type: application/json',
                    'Content-Length: ' . strlen($data)
                ));
                // optional proxy
                if (defined('PROXY_ADDRESS') && PROXY_ADDRESS !== '') {
                    curl_setopt($ch, CURLOPT_HTTPPROXYTUNNEL, true);
                    curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_HTTP);
                    curl_setopt($ch, CURLOPT_PROXY, PROXY_ADDRESS);
                }

                $response = @curl_exec($ch);
                $curl_errno = curl_errno($ch);
                $curl_error = curl_error($ch);
                curl_close($ch);
            } else {
                // Fallback: file_get_contents with stream context if allow_url_fopen is enabled
                $context = stream_context_create(array(
                    'http' => array(
                        'method' => 'POST',
                        'header' => "Content-Type: application/json\r\n" .
                            "Content-Length: " . strlen($data) . "\r\n",
                        'content' => $data,
                        'timeout' => 10
                    ),
                    'ssl' => array(
                        'verify_peer' => false,
                        'verify_peer_name' => false
                    )
                ));
                $response = @file_get_contents($api_url, false, $context);
            }

            // decode result safely
            $decoded = false;
            if ($response !== false && $response !== null && $response !== '') {
                $decoded = decode_json($response);
                if (!is_array($decoded)) {
                    $decoded = false;
                }
            }

            if ($decoded && isset($decoded['status'])) {
                $_SESSION['software']['settings']['license']['status'] = $decoded['status'];
            } else {
                // If no structured response, set a technical error message for display
                $_SESSION['software']['settings']['license']['status'] = '';
            }

            if ($decoded && isset($decoded['error_code'])) {
                $_SESSION['software']['settings']['license']['error_code'] = $decoded['error_code'];
            }

            // successful license verification path
            if (isset($_SESSION['software']['settings']['license']['status']) && ($_SESSION['software']['settings']['license']['status'] ?? '') === 'success') {
                // server returns end date in 'P_end_d' per original code - guard it
                if (isset($decoded['P_end_d']) && $decoded['P_end_d'] !== '') {
                    try {
                        $expiration_date = new DateTime($decoded['P_end_d']);
                    } catch (Exception $e) {
                        // try alternate formats
                        $expiration_date = DateTime::createFromFormat('d-m-Y', $decoded['P_end_d']);
                        if ($expiration_date === false) {
                            // last fallback: try to parse using strtotime
                            $ts = strtotime($decoded['P_end_d']);
                            $expiration_date = $ts ? new DateTime(date('Y-m-d', $ts)) : null;
                        }
                    }
                    if ($expiration_date instanceof DateTime) {
                        $_SESSION['software']['settings']['license']['expiration_date_formatted'] = $expiration_date;
                        // compute days difference
                        $diff = $today->diff($expiration_date);
                        // %a gives total days; ensure format method exists (it does)
                        $countdown = (int) $diff->format('%a');
                        $_SESSION['software']['settings']['license']['countdown'] = $countdown;
                        $_SESSION['software']['settings']['license']['last_check'] = time();
                    }
                } else {
                    // If P_end_d not provided, set last_check to avoid continuous retries
                    $_SESSION['software']['settings']['license']['last_check'] = time();
                }
            } else {
                // mark last_check to avoid hammering remote if it failed repeatedly
                $_SESSION['software']['settings']['license']['last_check'] = time();
                // store diagnostic info for admin display
                $_SESSION['software']['settings']['license']['diag_errno'] = $curl_errno;
                $_SESSION['software']['settings']['license']['diag_error'] = $curl_error;
                $_SESSION['software']['settings']['license']['diag_response'] = is_string($response) ? substr($response, 0, 300) : '';
            }
        } // end need_check

        // Interpret the session license values and set output variables
        $status = isset($_SESSION['software']['settings']['license']['status']) ? ($_SESSION['software']['settings']['license']['status'] ?? '') : '';
        $error_code = isset($_SESSION['software']['settings']['license']['error_code']) ? ($_SESSION['software']['settings']['license']['error_code'] ?? '') : '';
        $countdown = isset($_SESSION['software']['settings']['license']['countdown']) ? (int) ($_SESSION['software']['settings']['license']['countdown'] ?? '') : 0;
        $expiration_dt = isset($_SESSION['software']['settings']['license']['expiration_date_formatted']) ? ($_SESSION['software']['settings']['license']['expiration_date_formatted'] ?? '') : null;
        $diag = array(
            'errno' => isset($_SESSION['software']['settings']['license']['diag_errno']) ? ($_SESSION['software']['settings']['license']['diag_errno'] ?? '') : '',
            'error' => isset($_SESSION['software']['settings']['license']['diag_error']) ? ($_SESSION['software']['settings']['license']['diag_error'] ?? '') : '',
            'response' => isset($_SESSION['software']['settings']['license']['diag_response']) ? ($_SESSION['software']['settings']['license']['diag_response'] ?? '') : '',
        );

        if ($status === 'success' && $expiration_dt instanceof DateTime && ($countdown >= 0) && ($today <= $expiration_dt)) {
            $output_notice_title = lang('Congratulations! Your license is valid.');
            $output_notice_title_classes .= ' rounded text-success';
            $output_counter = '<h6 class="text-center">' . lang(array('string' => '{var:1} days left', 'vars' => array($countdown))) . '</h6>';
            $progress_width = ($countdown / 365 * 100);
            if ($progress_width < 0) {
                $progress_width = 0;
            }
            if ($progress_width > 100) {
                $progress_width = 100;
            }
            $output_counter .=
                '<div class="m-2 row">
                    <div class="col p-0" style="padding-right:2px !important">
                        <div class="progress rounded-0 w-100" style="--bs-progress-height: .2rem;">
                            <div class="progress-bar" style="width: ' . h($progress_width) . '%;" aria-valuenow="' . h($countdown) . '" aria-valuemin="0" aria-valuemax="365"></div>
                        </div>
                    </div>
                </div>';

            $output_license_status_color_class = '';
            if ($countdown <= 60) {
                $output_license_status_color_class = ' text-warning';
                $output_extend_license_button = '<a href="https://www.kodpen.com/iletisim" class="dropdown-item text-truncate" target="_blank">' . lang('Extend License') . '</a>';
                if ($countdown <= 10) {
                    $output_notice_title_classes .= ' rounded text-danger';
                    $output_notice_title = lang('Your software license is about to expire, and if it is not renewed, you will be deprived of some features.');
                }
            }

            $license_valid = true;
        } else {
            // Not successful or expired
            if ($status === 'success' && $expiration_dt instanceof DateTime) {
                // expired
                $output_notice_title = lang('Your license has expired. You cannot benefit from some features.');
                $output_notice_title_classes .= ' rounded text-danger';
                $output_license_status_color_class = ' text-danger';
                $output_check_license_button = '<form method="get" action="" class="text-center disable_shortcut"><input type="hidden" name="check_license_again" value="1"/><button type="submit" value="refresh" class="dropdown-item text-truncate">' . lang('Check License') . '</button></form>';
                $output_extend_license_button = '<a href="https://www.kodpen.com/iletisim" class="dropdown-item text-truncate" target="_blank">' . lang('Buy License') . '</a>';
            } else {
                // invalid or technical error
                if ($error_code === 'no_match' || $error_code === 'no_key') {
                    $output_notice_title = lang('Your license is not valid. You cannot benefit from some features.');
                    $output_notice_title_classes .= ' rounded text-danger';
                    $output_license_status_color_class = ' text-danger';
                    $output_check_license_button = '<form method="get" action="" class="text-center disable_shortcut"><input type="hidden" name="check_license_again" value="1"/><button type="submit" value="refresh" class="dropdown-item text-truncate">' . lang('Check License') . '</button></form>';
                    $output_extend_license_button = '<a href="https://www.kodpen.com/iletisim" class="dropdown-item text-truncate" target="_blank">' . lang('Buy License') . '</a>';
                } else {
                    $output_notice_title = lang('License verification failed due to technical reason. You cannot benefit from some features.');
                    $output_notice_title_classes .= ' rounded text-danger';
                    $output_license_status_color_class = ' text-danger';
                    $output_check_license_button = '<form method="get" action="" class="text-center disable_shortcut"><input type="hidden" name="check_license_again" value="1"/><button type="submit" value="refresh" class="dropdown-item text-truncate">' . lang('Check License') . '</button></form>';
                }
            }
        }
    } else {
        // No subscription key provided
        $output_notice_title = lang('No license key provided in Site Settings. You cannot benefit from some features.');
        $output_notice_title_classes .= ' rounded text-danger';
    }

    // Output according to request
    if ($output_information === 'bar') {
        if (defined('SUBSCRIPTION_KEY') && SUBSCRIPTION_KEY != '') {

            // ── Derive display state ─────────────────────────────────────────
            if ($license_valid) {
                if ($countdown <= 10) {
                    $bar_color = 'danger';
                } elseif ($countdown <= 60) {
                    $bar_color = 'warning';
                } else {
                    $bar_color = 'success';
                }
                $bar_status_text = lang('Active');
            } elseif ($status === 'success') {
                $bar_color = 'danger';
                $bar_status_text = lang('Expired');
            } else {
                $bar_color = 'secondary';
                $bar_status_text = ($error_code === 'no_match' || $error_code === 'no_key')
                    ? lang('Invalid')
                    : lang('Unavailable');
            }

            $bar_icon_cls = 'text-' . $bar_color;
            $bar_badge_cls = 'bg-' . $bar_color . ($bar_color === 'warning' ? ' text-dark' : '');

            // ── Countdown / expiration block ─────────────────────────────────
            $bar_body = '';
            if ($license_valid && $expiration_dt instanceof DateTime) {
                $bar_progress = min(100, max(0, round($countdown / 365 * 100)));
                $bar_body = '
                <div class="px-3 pt-2 pb-1 text-center">
                    <span class="fw-bold lh-1 text-' . h($bar_color) . '" style="font-size:2.25rem">' . (int) $countdown . '</span>
                    <div class="text-muted small">' . lang('days remaining') . '</div>
                    <div class="text-muted mt-1" style="font-size:.7rem;letter-spacing:.02em">' . h($expiration_dt->format('d M Y')) . '</div>
                </div>
                <div class="px-3 pt-1 pb-2">
                    <div class="progress rounded-pill overflow-hidden" style="height:3px">
                        <div class="progress-bar bg-' . h($bar_color) . '" role="progressbar"
                             style="width:' . h($bar_progress) . '%"
                             aria-valuenow="' . (int) $countdown . '" aria-valuemin="0" aria-valuemax="365"></div>
                    </div>
                </div>';
            } elseif ($status === 'success' && $expiration_dt instanceof DateTime) {
                // expired — show the date it expired
                $bar_body = '
                <div class="px-3 py-2 text-center">
                    <div class="text-danger small">' . lang('Expired') . ': ' . h($expiration_dt->format('d M Y')) . '</div>
                </div>';
            } else {
                // technical error — show diagnostic for managers+
                $bar_diag_html = '';
                if (isset($user['role']) && (int) $user['role'] <= 2 && ($diag['errno'] || $diag['response'] || $diag['error'])) {
                    $diag_lines = array();
                    if ($diag['errno'])
                        $diag_lines[] = 'cURL errno: ' . (int) $diag['errno'];
                    if ($diag['error'])
                        $diag_lines[] = 'cURL error: ' . h($diag['error']);
                    if ($diag['response'])
                        $diag_lines[] = 'Response: ' . h($diag['response']);
                    $bar_diag_html = '
                    <details class="px-2 pb-1" style="font-size:.65rem">
                        <summary class="text-muted" style="cursor:pointer">Diagnostic</summary>
                        <pre class="text-start text-danger bg-body-secondary rounded p-1 mt-1 mb-0" style="white-space:pre-wrap;word-break:break-all;font-size:.65rem">' . implode("\n", $diag_lines) . '</pre>
                    </details>';
                }
                $bar_body = '
                <div class="px-3 pt-2 pb-1 text-center">
                    <small class="text-muted">' . h($output_notice_title) . '</small>
                </div>' . $bar_diag_html;
            }

            // ── Action buttons ───────────────────────────────────────────────
            $bar_actions_html = '';
            $bar_btn_check = '';
            $bar_btn_extend = '';

            if ($output_check_license_button) {
                $bar_btn_check = '
                <form method="get" action="" class="disable_shortcut">
                    <input type="hidden" name="check_license_again" value="1">
                    <button type="submit" class="btn btn-sm btn-outline-secondary w-100">
                        <i class="bi bi-arrow-clockwise me-1"></i>' . lang('Check License') . '
                    </button>
                </form>';
            }
            if ($output_extend_license_button) {
                $btn_label = ($status === 'success') ? lang('Extend License') : lang('Buy License');
                $bar_btn_extend = '
                <a href="https://www.kodpen.com/iletisim" target="_blank"
                   class="btn btn-sm btn-outline-primary w-100">
                    <i class="bi bi-gem me-1"></i>' . $btn_label . '
                </a>';
            }
            if ($bar_btn_check || $bar_btn_extend) {
                $bar_actions_html = '
                <div class="p-2 border-top d-grid gap-1">' . $bar_btn_check . $bar_btn_extend . '</div>';
            }

            return '
            <li class="nav-item dropdown no-arrow no-popover " title="' . lang('Premium features access status') . '">
                <button type="button"
                        class="nav-link nav-link-sm align-self-center position-relative dropdown-toggle"
                        data-bs-auto-close="outside" data-bs-toggle="dropdown">
                    <span class="bi bi-gem ' . h($bar_icon_cls) . '"></span>
                    <span class="position-absolute border border-2 border-body rounded-circle bg-' . h($bar_color) . '"
                          style="width:7px;height:7px;top:4px;right:4px"></span>
                </button>
                <div class="dropdown-menu dropdown-menu-end p-0 shadow-lg bg-body backdrop  border-dropdown-menu overflow-hidden"
                     style="width:210px;border-radius:.85rem;margin-top:.4rem;">
                    <div class="px-3 pt-3 pb-2 text-center bg-body bg-gradient bg-opacity-25">
                        <span class="bi bi-gem ' . h($bar_icon_cls) . '" style="font-size:1.6rem;opacity:.9"></span>
                        <div class="fw-semibold mt-1" style="font-size:.78rem;letter-spacing:.05em">Pinegrap Premium™</div>
                        <span class="badge rounded-pill mt-1 px-3 ' . h($bar_badge_cls) . '"
                              style="font-size:.62rem">' . h($bar_status_text) . '</span>
                    </div>
                    ' . $bar_body . $bar_actions_html . '
                </div>
            </li>';
        }
        return '';
    } else if ($output_information === 'text') {
        return ($license_valid === true) ? 'licensed' : 'not_licensed';
    } else {
        // Default: block access if NOT licensed
        if ($license_valid !== true) {
            // show promotional/licensing page and exit
            print

                $output = output_header([
                    'title' => lang('Pinegrap Premium™'),
                    'extra classes' => 'setting',
                    'icon' => 'setting',
                    'heading' => lang('Pinegrap Premium™'),
                    'cancel' => true
                ]) . '
            <main class="container mb-5" style="min-height:calc(100vh - 175px)" id="content">
                <div class="col-12 col-md-8 offset-md-2">
                    <div class="card my-5 border-4">
                        <div class="card-body mb-0 p-4">
                        <div class=" text-center"><span class="material-icons text-light" style="font-size:5em;line-height:1em;">diamond</span></div>
                        <h6 class="text-success text-center">Pinegrap Premium™</h6>
                        <h5>' . lang('Advantages') . ':</h5>
                        <ul>
                            <li>' . lang('Simplify your remote server operations with API support.') . '</li>
                            <li>' . lang('Enrich website functions with custom coding support.') . '</li>
                            <li>' . lang('Keep stocks under control easily with barcode transactions without requiring additional software.') . '</li>
                            <li>' . lang('Sell locally with your barcode device.') . '</li>
                            <li>' . lang('Get website design and editing support, your website design will not fall behind the times.') . '</li>
                            <li>' . lang('Get the latest updates and security patches.') . '</li>
                            <li>' . lang('Take advantage of our 24/7 customer support service.') . '</li>
                        </ul>
                        <p class="alert alert-danger ">' . lang('The page you are trying to access requires a premium license. If you already have a premium license key, report the problem to us on our contact page.') . '</p>
                        <a href="https://www.kodpen.com/iletisim" target="_blank" class="btn-link link-secondary"><i class="material-icons me-2">support_agent</i>' . lang('Contact Us') . '</a>
                        </div>
                    </div>
                </div>
            </main>
            ' . output_footer();
            exit();
        }
    }
}



/**
 * Fetches the toolbar page row (page + folder_archived) with a per-request
 * static cache so toolbar.php and output_toolbar() don't both execute the
 * same query on the same request.
 */
function get_toolbar_page_row($page_id)
{
    static $cache = array();
    $key = (string) $page_id;
    if (isset($cache[$key])) {
        return $cache[$key];
    }
    $query =
        "SELECT
            page.page_id,
            page.page_name,
            page.page_folder,
            page.page_home,
            page.page_search,
            page.page_search_keywords,
            page.page_style,
            page.mobile_style_id,
            page.page_type,
            page.comments,
            page.comments_automatic_publish,
            page.comments_administrator_email_to_email_address,
            page.seo_score,
            page.sitemap,
            folder.folder_archived
        FROM page
        LEFT JOIN folder ON page.page_folder = folder.folder_id
        WHERE page.page_id = '" . escape($page_id) . "'";
    $result = mysqli_query(db::$con, $query) or output_error('Query failed.');
    $cache[$key] = mysqli_fetch_assoc($result);
    return $cache[$key];
}

function output_toolbar($toolbar)
{
    // Reuse the user that output_header() already validated. validate_user()
    // performs a SELECT * FROM user query — calling it again here duplicated
    // that work on every toolbar render.
    global $user;
    if (!is_array($user) || empty($user)) {
        $user = validate_user();
    }
    if ($toolbar == false) {
        return '';
    } else {
        // get page info (cached per-request — toolbar.php has already run this)
        $row = get_toolbar_page_row($_GET['page_id']);

        $page_id = $row['page_id'];
        $page_name = $row['page_name'];
        $page_folder = $row['page_folder'];
        $page_home = $row['page_home'];
        $page_search = $row['page_search'];
        $page_search_keywords = $row['page_search_keywords'];
        $page_style = $row['page_style'];
        $mobile_style_id = $row['mobile_style_id'];
        $page_type = $row['page_type'];
        $comments = $row['comments'];
        $comments_automatic_publish = $row['comments_automatic_publish'];
        $comments_administrator_email_to_email_address = $row['comments_administrator_email_to_email_address'];
        $seo_score = $row['seo_score'];
        $sitemap = $row['sitemap'];
        $folder_archived = $row['folder_archived'];

        $access_control_type = get_access_control_type($page_folder);

        $style_id = $_GET['style_id'];

        $output_preview_style_pick_list = '';
        $output_preview_style_set_button = '';

        // get style information
        $query =
            "SELECT
                style_name,
                style_type
            FROM style
            WHERE style_id = '" . escape($style_id) . "'";
        $result = mysqli_query(db::$con, $query) or output_error('Query failed.');
        $row = mysqli_fetch_assoc($result);

        $style_name = $row['style_name'];
        $style_type = $row['style_type'];

        // if this pages folder is archived, then output a notice next to the page name
        if ($folder_archived == '1') {
            $page_name .= ' [' . lang('ARCHIVED') . ']';
        }

        $output_subnav_page_properties = '';

        // if user is higher than a user role OR if user has edit rights to at least one folder
        if ($user['role'] < 3 || no_acl_check($user['id'])) {

            // If the user is a basic user than get the folder user has access to.
            if ($user['role'] == 3) {
                $folders_that_user_has_access_to = get_folders_that_user_has_access_to($user['id']);
            }

            // if user has access to folder that page is in, then output body
            if (($user['role'] < 3) || (check_folder_access_in_array($page_folder, $folders_that_user_has_access_to) == true)) {
                // Output page access type.
                $output_subnav_page_properties .= '
                    <li>
                        <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0 ' . $access_control_type . '">
                            ' . h(get_access_control_type_name($access_control_type)) . '
                        </p>
                    </li>';

                // Get and output page type
                if ($page_type != '') {
                    $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                                ' . h(get_page_type_name($page_type)) . '
                            </p>
                        </li>';
                }

                // Get most recent short link for this page if one exists.
                $query =
                    "SELECT name
                    FROM short_links
                    WHERE
                        (destination_type = 'page')
                        AND (page_id = '" . escape($_GET['page_id']) . "')
                    ORDER BY last_modified_timestamp DESC
                    LIMIT 1";
                $result = mysqli_query(db::$con, $query) or output_error('Query failed.');

                $short_link = mysqli_fetch_assoc($result);

                // if there is a short link, then prepare to output description in sub-navigation area
                if (isset($short_link['name']) && $short_link['name'] != '') {
                    $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            ' . lang('Short Link') . ': ' . h($short_link['name']) . '
                            </p>
                        </li>';
                }

                // Check to see if the page has page type properties
                $check_for_page_type_properties = check_for_page_type_properties($page_type);

                // If the page has page type properties.
                if ($check_for_page_type_properties == true) {
                    // Get the page type properties.
                    $page_type_properties = get_page_type_properties($page_id, $page_type);

                    // if there is a next page,
                    // and the page type is not catalog detail,
                    // or ordering is enabled,
                    // then prepare to output next page
                    if (
                        (isset($page_type_properties['next_page_id']) == true)
                        &&
                        (
                            ($page_type != 'catalog detail')
                            || ($page_type_properties['allow_customer_to_add_product_to_order'] == 1)
                        )
                    ) {
                        // Get the next page name and output the next page.
                        $next_page_name = get_page_name($page_type_properties['next_page_id']);

                        // Next page is blank then output none.
                        if ($next_page_name == '') {
                            $output_subnav_page_properties .= '
                            <li>
                                <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                                    ' . lang('Next Page') . ': [' . lang('Not Set') . ']
                                </p>
                            </li>';

                            // else output name
                        } else {
                            $output_subnav_page_properties .= '
                            <li>
                                <a class="dropdown-item" href="' . OUTPUT_PATH . $next_page_name . '" target="_parent">' . lang('Next Page') . ': ' . $next_page_name . '</a>
                            </li>';
                        }
                    } else if ((isset($page_type_properties['add_button_next_page_id']) && ($page_type_properties['add_button_next_page_id'] != 0))) {
                        // Get the next page name and output the next page. 
                        $next_page_name = get_page_name($page_type_properties['add_button_next_page_id']);

                        // Next page is blank then output none.
                        if ($next_page_name == '') {
                            $output_subnav_page_properties .= '
                            <li>
                                <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                                ' . lang('Next Page') . ': [' . lang('Not Set') . ']
                                </p>
                            </li>';
                            // else output name
                        } else {
                            $output_subnav_page_properties .= '
                            <li>
                                <a class="dropdown-item" href="' . OUTPUT_PATH . $next_page_name . '" target="_parent">' . lang('Next Page') . ': ' . $next_page_name . '</a>
                            </li>';
                        }
                    }

                    if ((isset($page_type_properties['skip_button_next_page_id']) && ($page_type_properties['skip_button_next_page_id'] != 0))) {
                        // Get the next page name and output the next page.
                        $skip_page_name = get_page_name($page_type_properties['skip_button_next_page_id']);

                        $output_subnav_page_properties .= '
                        <li>
                            <a class="dropdown-item" href="' . OUTPUT_PATH . $skip_page_name . '" target="_parent">' . lang('Skip Page') . ': ' . $skip_page_name . '</a>
                        </li>';
                    }
                }
                $output_subnav_home = '';
                // if this is a home page, then prepare to output description in sub-navigation area
                if ($page_home == 'yes') {
                    $output_subnav_home = '<span class="bi bi-house me-2"></span>';
                }

                // if search is enabled, then prepare to output description in sub-navigation area
                if ($page_search == 1) {
                    $output_subnav_page_properties .= '
                    <li>
                        <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                        ' . lang('Searchable') . '
                        </p>
                    </li>';

                    // if there are search keywords, then prepare to output description in sub-navigation area
                    if ($page_search_keywords != '') {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            ' . lang('Keyword') . ': ' . h($page_search_keywords) . '
                            </p>
                        </li>';
                    }
                }

                $output_comments_properties = '';
                // if comments are enabled, then output information to toolbar
                if ($comments == '1') {

                    // if auto publish is enabled, then output enabled message
                    if ($comments_automatic_publish == '1') {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            ' . lang('Comments automatically published') . '
                            </p>
                        </li>';

                        // else output disabled message
                    } else {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            ' . lang('Comments require approval') . '
                            </p>
                        </li>';
                    }

                    // if moderator email address is not blank, then output it
                    if ($comments_administrator_email_to_email_address != '') {

                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            ' . lang('Moderator') . ': ' . h($comments_administrator_email_to_email_address) . '
                            </p>
                        </li>';
                    }
                }

                // if this is a form list view page, then verify that RSS is enabled and then output information to toolbar
                if ($page_type == 'form list view') {
                    // get the count of rss fields from the custom form
                    $query =
                        "SELECT 
                            COUNT(form_fields.rss_field) as number_of_rss_fields
                        FROM form_list_view_pages
                        LEFT JOIN form_fields ON form_fields.page_id = form_list_view_pages.custom_form_page_id
                        WHERE
                            (form_list_view_pages.page_id = '" . escape($page_id) . "')
                            AND (form_list_view_pages.collection = 'a')
                            AND (rss_field != '')";
                    $result = mysqli_query(db::$con, $query) or output_error('Query failed');
                    $row = mysqli_fetch_assoc($result);
                    // if there are RSS fields in the custom form, then check to see if this is a public page, and then output information to toolbar
                    if ($row['number_of_rss_fields'] > 0) {
                        if ($access_control_type == 'public') {
                            $output_subnav_page_properties .= '
                            <li>
                                <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                                RSS: ' . lang('Enabled') . '
                                </p>
                            </li>';
                        } else {
                            $output_subnav_page_properties .= '
                            <li>
                                <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                                RSS: ' . lang('Disabled because Page is not in a Public Folder.') . '
                                </p>
                            </li>';
                        }
                    }
                }

                // if this is a calendar view page, and if it is public then output information to toolbar
                if ($page_type == 'calendar view') {

                    if ($access_control_type == 'public') {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            RSS: ' . lang('Enabled') . '
                            </p>
                        </li>';
                    } else {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            RSS: ' . lang('Disabled because Page is not in a Public Folder.') . '
                            </p>
                        </li>';
                    }
                }

                // if the user has design access, then output style name with link to edit style
                if ($user['role'] <= 1) {
                    $output_subnav_page_properties .= '
                    <li>
                        <a class="dropdown-item" href="edit_' . $style_type . '_style.php?id=' . h($style_id) . '&send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . '" target="_parent">' . h($style_name) . '</a>
                    </li>';

                    // else the user does not have design access, so just output style name without a link
                } else {
                    $output_subnav_page_properties .= h($style_name);
                }

                // if sitemap is enabled, then prepare to output description in sub-navigation area
                if ($sitemap == 1) {

                    // if this page is public and is not archived then output that page is included in sitemap
                    if (($access_control_type == 'public') && ($folder_archived == 0)) {
                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            sitemap.xml: ' . lang('Included') . '
                            </p>
                        </li>';

                        // else this page is not public or is achived, so explain why page is not included in sitemap
                    } else {
                        // if page is not public, then prepare message for that
                        if ($access_control_type != 'public') {
                            $message = lang('not in a Public Folder.');

                            // else page is archived, so prepare message for that
                        } else {
                            $message = lang('is archived');
                        }

                        $output_subnav_page_properties .= '
                        <li>
                            <p style="padding: var(--bs-dropdown-item-padding-y) var(--bs-dropdown-item-padding-x);" class="mb-0">
                            sitemap.xml: ' . lang(array('string' => 'Excluded because Page {var:1}', 'vars' => array($message))) . '
                            </p>
                        </li>';
                    }
                }

                $output_page_designer_button = '';

                // If the user is an admin or designer, then output page designer button.
                // For system styles, open Visual Pinegrap Editor instead of the page designer.
                if (USER_ROLE < 2) {
                    if ($style_type == 'system') {
                        $designer_href  = 'edit_system_style.php?id=' . h($style_id) . '&send_to=' . h(urlencode(($_GET['send_to'] ?? '')));
                        $designer_title = lang('Open Style Designer') . ' (Ctrl+G | &#8984;+G)';
                    } else {
                        $designer_href  = 'page_designer.php?url=' . h(urlencode(($_GET['send_to'] ?? '')));
                        $designer_title = lang('Open Page Designer') . ' (Ctrl+G | &#8984;+G)';
                    }
                    $output_page_designer_button = '
                    <li class="nav-item">
                        <a class="nav-link nav-link-sm no-popover design-color page_designer_button closed" href="' . $designer_href . '" target="_parent" title="' . $designer_title . '">
                            <span class="bi bi-layout-text-window-reverse"></span>
                        </a>
                    </li>';
                }

                $output_mobile_button = '';

                // If mobile is enabled in the site settings, then output mobile button.
                if (MOBILE == true) {
                    $output_mobile_button_class = '';
                    $output_mobile_button_device_type = '';
                    $output_mobile_button_title = '';

                    // prepare parts of the mobile button differently based on the device type
                    switch ($_SESSION['software']['device_type']) {
                        case 'desktop':
                        default:
                            $output_mobile_button_class = 'desktop';
                            $output_mobile_button_device_type = 'mobile';
                            $output_mobile_button_title = lang('Enable Mobile Mode');
                            $output_mobile_button_icon_class = 'bi-phone';
                            break;

                        case 'mobile':
                            $output_mobile_button_class = 'mobile';
                            $output_mobile_button_device_type = 'desktop';
                            $output_mobile_button_title = lang('Enable Desktop Mode');
                            $output_mobile_button_icon_class = 'bi-laptop';

                            break;
                    }

                    $output_mobile_button = '
                    <li class="nav-item">
                        <a id="mobile_button" class="nav-link nav-link-sm no-popover settings-color ' . $output_mobile_button_class . ' " href="update_device_type.php?device_type=' . $output_mobile_button_device_type . '&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '" target="_parent" title="' . $output_mobile_button_title . '">
                            <span class="bi ' . $output_mobile_button_icon_class . '"></span>
                        </a>
                    </li>';
                }

                $output_edit_page_style_button = '';

                // if the user has design access, then output style name with link to edit style
                if ($user['role'] <= 1) {
                    $output_edit_page_style_button .= '
                    <li class="nav-item">
                        <a class="nav-link nav-link-sm no-popover design-color" href="edit_' . $style_type . '_style.php?id=' . h($style_id) . '&send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . '" target="_parent" title="' . lang('Edit Page Style') . '">
                            <span class="bi bi-file-earmark-richtext"></span>
                        </a>
                    </li>';
                }

                $output_duplicate_page_button = '';

                // if the user is at least a manager or has create pages turned on, then output the duplicate page button
                if (($user['role'] < '3') || ($user['create_pages'] == TRUE)) {
                    $output_duplicate_page_button = '
                    <li class="nav-item">
                        <a class="nav-link nav-link-sm no-popover pages-color" class="page_duplicate_button" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/duplicate_page.php?id=' . h($_GET['page_id']) . get_token_query_string_field() . '" target="_parent" title="' . lang('Duplicate Page') . '">
                            <span class="bi bi-files"></span>
                        </a>
                    </li>';
                }

                $output_theme_pick_list = '';
                $output_preview_theme_link = '';
                $output_theme_dropdown_close_button = '';
                // If user is manager or above
                if ($user['role'] < 3) {
                    // if the user is previewing a theme and user role is administrator or designer, then prepare to include theme preview pick list
                    if (isset($_SESSION['software']['preview_theme_id']) == TRUE) {
                        $activated_theme_id = db_value("SELECT id FROM files WHERE activated_" . $_SESSION['software']['device_type'] . "_theme = '1'");

                        if ($_SESSION['software']['device_type'] == 'desktop') {
                            $activated_style_id_for_device_type = $page_style;

                        } else {
                            $activated_style_id_for_device_type = $mobile_style_id;
                        }

                        $output_preview_style_options = '';

                        // If the user is previewing the activated theme or the "none" theme,
                        // then prepare style options in a certain way.
                        if (
                            ($_SESSION['software']['preview_theme_id'] == $activated_theme_id)
                            || ($_SESSION['software']['preview_theme_id'] == '')
                        ) {
                            $output_default_label = '';

                            // If the activated style for this page is default, then show that in label.
                            if (!$activated_style_id_for_device_type) {
                                $output_default_label .= '[A] ';
                            }

                            $output_default_label .= '<span class="translateable">Default</span>';

                            // Get default style id.
                            $default_style_id = get_style($page_folder, $_SESSION['software']['device_type']);

                            // If the device type is set to mobile and a default mobile style id could not be found, then get desktop style id
                            // because we fallback to a desktop style when a mobile style cannot be found for a page
                            if (
                                ($_SESSION['software']['device_type'] == 'mobile')
                                && ($default_style_id == 0)
                            ) {
                                $default_style_id = get_style($page_folder, 'desktop');
                            }

                            // If a default style was found, then output default label with style name.
                            if ($default_style_id) {
                                $default_style_name = db_value("SELECT style_name FROM style WHERE style_id = '" . $default_style_id . "'");

                                if ($default_style_name != '') {
                                    $output_default_label .= ': ' . h($default_style_name);
                                }
                            }

                            $output_preview_style_options .= '<option value="">' . $output_default_label . '</option>';

                            $sql_where = "";

                            // If device type is desktop then only get desktop styles.
                            if ($_SESSION['software']['device_type'] == 'desktop') {
                                $sql_where = "WHERE style_layout != 'one_column_mobile'";

                                // Otherwise the device type if mobile, so if mobile is enabled in the site settings,
                                // then only get styles that can be mobile styles.
                            } else if (MOBILE == true) {
                                $sql_where = "WHERE (style_type = 'custom') OR (style_layout = 'one_column_mobile')";
                            }

                            $styles = db_items(
                                "SELECT
                                    style_id AS id,
                                    style_name AS name
                                FROM style
                                $sql_where
                                ORDER BY style_name ASC"
                            );

                            foreach ($styles as $style) {
                                $output_selected = '';

                                // If the user has recently selected a style, and this is that style,
                                // then select it by default, or if the user has not recently selected
                                // a style, and this is the activated style, then select it by default.
                                if (
                                    (
                                        (isset($_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']]) == true)
                                        && ($style['id'] == $_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']])
                                    )
                                    ||
                                    (
                                        (isset($_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']]) == false)
                                        && ($style['id'] == $activated_style_id_for_device_type)
                                    )
                                ) {
                                    $output_selected = ' selected="selected"';
                                }

                                $output_label = '';

                                // If this style is the activated style, then output [ACTIVATED] prefix.
                                if ($style['id'] == $activated_style_id_for_device_type) {
                                    $output_label .= '[A] ';
                                }

                                $output_label .= h($style['name']);

                                $output_preview_style_options .= '<option value="' . $style['id'] . '"' . $output_selected . '>' . $output_label . '</option>';
                            }


                            // Otherwise the user is not previewing the activated theme,
                            // so prepare style options in a different way.
                        } else {
                            $output_activated_label = '[A] ';

                            // If this page has an activated style set, then output style name.
                            if ($activated_style_id_for_device_type) {
                                $activated_style_name = db_value("SELECT style_name FROM style WHERE style_id = '" . $activated_style_id_for_device_type . "'");

                                $output_activated_label .= h($activated_style_name);

                                // Otherwise this page's activated style is set to default, so output default,
                                // along with default style name.
                            } else {
                                $output_activated_label .= '<span class="translateable">Default</span>';

                                // Get default style id.
                                $default_style_id = get_style($page_folder, $_SESSION['software']['device_type']);

                                // If the device type is set to mobile and a default mobile style id could not be found, then get desktop style id
                                // because we fallback to a desktop style when a mobile style cannot be found for a page
                                if (
                                    ($_SESSION['software']['device_type'] == 'mobile')
                                    && ($default_style_id == 0)
                                ) {
                                    $default_style_id = get_style($page_folder, 'desktop');
                                }

                                // If a default style was found, then output default label with style name.
                                if ($default_style_id) {
                                    $default_style_name = db_value("SELECT style_name FROM style WHERE style_id = '" . $default_style_id . "'");

                                    if ($default_style_name != '') {
                                        $output_activated_label .= ': ' . h($default_style_name);
                                    }
                                }
                            }

                            $output_preview_style_options .= '<option value="">' . $output_activated_label . '</option>';

                            $preview_style_id = '';

                            // If a theme is selected, then get the style that is currently
                            // set as the preview style for this page, theme, and device type,
                            // so that we can indicate that below with a [PREVIEW] prefix for
                            // the option in the pick list.
                            if ($_SESSION['software']['preview_theme_id']) {
                                $preview_style_id = db_value(
                                    "SELECT style_id
                                    FROM preview_styles
                                    WHERE
                                        (page_id = '" . escape($page_id) . "')
                                        AND (theme_id = '" . escape($_SESSION['software']['preview_theme_id']) . "')
                                        AND (device_type = '" . escape($_SESSION['software']['device_type']) . "')"
                                );
                            }

                            $sql_where = "";

                            // If device type is desktop then only get desktop styles.
                            if ($_SESSION['software']['device_type'] == 'desktop') {
                                $sql_where = "WHERE style_layout != 'one_column_mobile'";

                                // Otherwise the device type if mobile, so if mobile is enabled in the site settings,
                                // then only get styles that can be mobile styles.
                            } else if (MOBILE == true) {
                                $sql_where = "WHERE (style_type = 'custom') OR (style_layout = 'one_column_mobile')";
                            }

                            $styles = db_items(
                                "SELECT
                                    style_id AS id,
                                    style_name AS name
                                FROM style
                                $sql_where
                                ORDER BY style_name ASC"
                            );

                            foreach ($styles as $style) {
                                $output_selected = '';

                                // If the user has recently selected a style, and this is that style,
                                // then select it by default, or if the user has not recently selected
                                // a style, and this is the preview style, then select it by default.
                                if (
                                    (
                                        (isset($_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']]) == true)
                                        && ($style['id'] == $_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']])
                                    )
                                    ||
                                    (
                                        (isset($_SESSION['software']['preview_style']['theme_' . $_SESSION['software']['preview_theme_id'] . '_page_' . $page_id . '_' . $_SESSION['software']['device_type']]) == false)
                                        && ($style['id'] == $preview_style_id)
                                    )
                                ) {
                                    $output_selected = ' selected="selected"';
                                }

                                $output_label = '';

                                // If this style is the preview style, then output [PREVIEW] prefix.
                                if ($style['id'] == $preview_style_id) {
                                    $output_label .= '[P] ';
                                }

                                $output_label .= h($style['name']);

                                $output_preview_style_options .= '<option value="' . $style['id'] . '"' . $output_selected . '>' . $output_label . '</option>';
                            }
                        }

                        $output_preview_style_pick_list =
                            '<select style="min-width:100px;" class="form-select me-2" name="style_id" id="style_id" onchange="parent.location.href = \'' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/preview_style.php?mode=preview&amp;style_id=\' + document.getElementById(\'style_id\').value + \'&amp;page_id=' . $page_id . '&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '\';">
                                ' . $output_preview_style_options . '
                            </select>';

                        // If the user is previewing the activated theme or the "none" theme,
                        // then prepare specific title for set button.
                        if (
                            ($_SESSION['software']['preview_theme_id'] == $activated_theme_id)
                            || ($_SESSION['software']['preview_theme_id'] == '')
                        ) {
                            $output_preview_style_set_button_title = lang('Set Activated Page Style');

                            // Otherwise prepare different title for set button.
                        } else {
                            $output_preview_style_set_button_title = lang('Set Preview Page Style');
                        }

                        $output_preview_style_set_button = '
                                <a class="btn btn-sm no-popover text-success" href="preview_style.php?mode=set&amp;page_id=' . $page_id . '&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '" target="_parent" title="' . $output_preview_style_set_button_title . '">
                                    <span class="bi bi-check-circle"></span>
                                </a>';

                        $is_system_theme = FALSE;
                        $selected_file_id = 0;

                        // get all themes for preview theme pick list
                        $query =
                            "SELECT
                                id,
                                name,
                                activated_" . $_SESSION['software']['device_type'] . "_theme
                            FROM files
                            WHERE
                                (type = 'css')
                                AND (design = '1')
                                AND (theme = '1')
                            ORDER BY name ASC";
                        $result = mysqli_query(db::$con, $query) or output_error('Query failed.');
                        $themes = mysqli_fetch_items($result);

                        $output_theme_preview_options = '';

                        // We only need to know whether the *currently previewed* theme is a
                        // system theme. The original loop ran a COUNT() per theme inside the
                        // foreach (an N+1) — replace it with a single targeted lookup.
                        $preview_theme_id = $_SESSION['software']['preview_theme_id'];
                        $preview_is_system_theme = false;
                        if ($preview_theme_id) {
                            $preview_is_system_theme = (
                                (int) db_value(
                                    "SELECT COUNT(id) FROM system_theme_css_rules WHERE file_id = '"
                                    . escape($preview_theme_id) . "' LIMIT 1"
                                ) > 0
                            );
                        }

                        // loop through the themes in order to prepare pick list options
                        foreach ($themes as $theme) {
                            $selected_or_not = '';

                            // if this theme is the theme currently being previewed, then select it
                            if ($theme['id'] == $preview_theme_id) {
                                $selected_or_not = ' selected="selected"';

                                // if this is a system theme then output the edit theme button
                                if ($preview_is_system_theme) {
                                    $is_system_theme = TRUE;
                                }

                                // set the selected file id
                                $selected_file_id = $theme['id'];
                            }

                            $output_activated_prefix = '';

                            // If this is the activated theme for current device type,
                            // then add [ACTIVATED] prefix.
                            if ($theme['activated_' . $_SESSION['software']['device_type'] . '_theme'] == 1) {
                                $output_activated_prefix = '[A] ';
                            }

                            $output_theme_preview_options .= '<option value="' . h($theme['id']) . '"' . $selected_or_not . '>' . $output_activated_prefix . h($theme['name']) . '</option>';
                        }

                        $output_edit_theme_link = '';

                        // If a real theme is selected (not the "none" theme) and the user is at least a designer,
                        // then output the edit theme link.
                        if (
                            ($_SESSION['software']['preview_theme_id'])
                            && ($user['role'] < 2)
                        ) {
                            // if the selected theme is a system theme, then output the edit theme button
                            if ($is_system_theme == TRUE) {
                                $output_edit_theme_link = '
                                    <a class="btn btn-sm no-popover position-relative design-color" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/theme_designer.php?id=' . h($selected_file_id) . '&send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . '&clear_theme_designer_session=true&page_to_preview_id=' . $page_id . '" target="_parent" title="' . lang('Edit Theme') . '">
                                        <span class="bi bi-pencil"></span>
                                    </a>';

                                // else output the edit css link
                            } else {
                                $output_edit_theme_link = '
                                    <a class="btn btn-sm no-popover position-relative design-color" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/edit_theme_css.php?id=' . h($selected_file_id) . '&send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . '" target="_parent" title="' . lang('Edit Theme') . '">
                                        <span class="bi bi-pencil"></span>
                                    </a>';
                            }
                        }

                        $output_theme_pick_list =
                            '<li class="d-flex justify-content-between p-1" id="theme_pick_list">
                                <select style="min-width:100px;"  class="form-select me-2" name="theme_id" id="theme_id" onchange="parent.location.href = \'' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/preview_theme.php?mode=preview&amp;id=\' + document.getElementById(\'theme_id\').value + \'&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '\';">
                                    <option value="">-' . lang('None') . '-</option>'
                            . $output_theme_preview_options . '
                                </select>
                                ' . $output_edit_theme_link . '
                            </li>';
                        $output_theme_dropdown_close_button = '
                            <a class="nav-link nav-link-sm no-popover position-relative text-danger" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/preview_theme.php?mode=cancel&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '" target="_parent" title="' . lang('Close Preview') . '">
                                <span class="bi bi-x-lg"></span>
                            </a>';
                        // else the user is not previewing a stylesheet, so output preview themes link
                    } else {
                        $output_preview_theme_link = '
                        <li class="nav-item">
                            <a class="nav-link nav-link-sm no-popover position-relative design-color" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/preview_theme.php?mode=preview&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . get_token_query_string_field() . '" target="_parent" title="' . lang('Preview Page Styles & Themes') . '">
                                <span class="bi bi-flower2"></span>
                            </a>
                        </li>';
                    }
                }
                $output_theme_dropdown = '';
                if ($output_preview_style_pick_list != '' || $output_preview_style_set_button != '' || $output_theme_pick_list != '') {
                    $output_theme_dropdown = '
                    <li class="nav-item dropdown no-arrow no-popover">
                        ' . $output_theme_dropdown_close_button . '
                        <ul style="right:0;z-index:-1" class="show dropdown-menu shadow backdrop dropdown-menu-end pb-1 bg-body mt-nav-link-sm d-block d-md-flex border-dropdown-menu">
                        <li class="d-flex justify-content-between p-1">
                            ' . $output_preview_style_pick_list . $output_preview_style_set_button . '
                        </li>
                        ' . $output_theme_pick_list . '
                        </ul>
                    </li>';
                }

                $output_button_bar =
                    '
                            <li class="nav-item">
                                <a class="nav-link nav-link-sm no-popover position-relative pages-color" href="' . OUTPUT_PATH . OUTPUT_SOFTWARE_DIRECTORY . '/edit_page.php?id=' . h($_GET['page_id']) . '&amp;send_to=' . h(urlencode(($_GET['send_to'] ?? ''))) . '" target="_parent"  title="' . lang('Edit Page Properties') . '">
                                    <span class="bi bi-sliders"></span>
                                </a>
                            </li>
                            ' . $output_duplicate_page_button . '
                            ' . $output_mobile_button . '
                            <li class="vh nav-item pe-1 me-1 border-end my-auto"></li>
                            ' . $output_page_designer_button . '
                            ' . $output_edit_page_style_button . '
                            ' . $output_preview_theme_link . '
                            ' . $output_theme_dropdown;
            }
        }

        return '
        <ul class="navbar-nav d-none d-lg-flex"><li class="vh nav-item pe-1 me-1 border-end my-auto"></li></ul>
        <ul class="navbar-nav toolbar-nav">
            <li class="nav-item dropdown no-arrow">
                <button id="account_menu_toggle" type="button" class="nav-link nav-link-sm position-relative dropdown-toggle dropdown-menu-right pages-color" data-bs-auto-close="outside" data-bs-toggle="dropdown">
                    <span class="bi bi-info-circle"></span>
