                    ' . $output_subnav_page_properties . '

                </ul>
            </li>

            ' . $output_button_bar . '

        </ul>';
    }

}


/**
 * increase()
 *
 * Simple session-backed counter helper.
 *
 *
 * Behavior:
 *  - increase()                : increments internal counter and returns the new integer value.
 *  - increase(['reset' => true]): resets counter to 0 and returns 0.
 *
 * Notes:
 *  - Ensures a session is started if one is not already (silently).
 *  - Normalizes the stored value to integer to avoid issues across PHP versions.
 *
 * @param array|false $properties optional properties array (supported key: 'reset' => true)
 * @return int new counter value (or 0 when reset)
 */
function increase($properties = false)
{
    // Start session if not started; suppress warnings when headers already sent.
    if (function_exists('session_status')) {
        if (session_status() === PHP_SESSION_NONE) {
            @session_start();
        }
    } else {
        // fallback for very old PHP versions (rare)
        if (session_id() === '') {
            @session_start();
        }
    }

    // Normalize properties to array for safe access
    if (!is_array($properties)) {
        $properties = array();
    }

    // Reset path
    if (isset($properties['reset']) && $properties['reset'] === true) {
        $_SESSION['temp_increase'] = 0;
        return 0;
    }

    // Ensure the session key exists and is numeric; initialize to 0 otherwise.
    if (!isset($_SESSION['temp_increase']) || !is_numeric($_SESSION['temp_increase'])) {
        $_SESSION['temp_increase'] = 0;
    }

    // Cast to int, increment and persist.
    $_SESSION['temp_increase'] = (int) $_SESSION['temp_increase'] + 1;

    return (int) $_SESSION['temp_increase'];
}

/**
 * Verifies SHA-256 hashes of files in the current directory (excluding subdirectories)
 * against stored reference in data/temp/hash_reference.json to detect tampering or missing files.
 * Ignores server-generated files like error_log, .htaccess, etc.
 * Additionally, every 12 hours compares local hash list with remote hash list to detect removed entries.
 */
function check_directory_file_integrity()
{
    // Path to the local reference file
    $reference_file = 'data/temp/hash_reference.json';

    // Files that should be ignored during integrity check
    $ignored_files = ['error_log', '.htaccess', '.user.ini'];

    // Get current software version (must be defined as a constant)
    $current_version = defined('VERSION') ? VERSION : null;
    if ($current_version === null) {
        log_activity(lang('VERSION constant not defined.'), 'SYSTEM');
        return 'version_not_defined';
    }

    // If reference file does not exist, fetch it from remote server
    if (!file_exists($reference_file)) {
        $remote_url = 'https://kodpen.com/pinegrap_hash_referance[' . $current_version . '].json';
        $remote_context = stream_context_create(['http' => ['timeout' => 3]]);
        $remote_data = @file_get_contents($remote_url, false, $remote_context);

        if ($remote_data === false) {
            log_activity(lang("Unable to fetch remote hash reference."), 'SYSTEM');
            return 'unable_to_fetch_reference';
        }

        if (!is_dir(dirname($reference_file))) {
            mkdir(dirname($reference_file), 0755, true);
        }

        // Save the downloaded reference file locally with timestamp
        $decoded = json_decode($remote_data, true);
        if (is_array($decoded)) {
            $decoded['last_hash_check'] = time();
            file_put_contents($reference_file, json_encode($decoded, JSON_PRETTY_PRINT));
        } else {
            log_activity(lang("Remote hash reference is invalid JSON."), 'SYSTEM');
            return 'unable_to_fetch_reference';
        }
    }

    // Get the current working directory
    $base_path = getcwd();
    if ($base_path === false) {
        log_activity(lang('Unable to resolve current working directory.'), 'SYSTEM');
        return 'unable_to_resolve_directory';
    }

    // Read and decode the reference file
    $stored_hashes = json_decode(file_get_contents($reference_file), true);
    if (!is_array($stored_hashes) || empty($stored_hashes)) {
        log_activity(lang('Hash reference file is corrupted, unreadable, or empty.'), 'SYSTEM');
        return 'unable_to_resolve_directory';
    }

    // Extract and remove meta keys
    $last_check = isset($stored_hashes['last_hash_check']) ? (int) $stored_hashes['last_hash_check'] : 0;
    $last_local_check = isset($stored_hashes['last_local_check']) ? (int) $stored_hashes['last_local_check'] : 0;
    $last_local_result = $stored_hashes['last_local_result'] ?? null;
    unset($stored_hashes['last_hash_check'], $stored_hashes['last_local_check'], $stored_hashes['last_local_result']);

    // Short-circuit: return cached result if the local file hash run is less than 1 hour old.
    if ($last_local_result !== null && (time() - $last_local_check) < 3600) {
        return $last_local_result;
    }

    // Array to collect tampered or missing files
    $tampered_files = [];

    // Compare each stored hash with the current file hash
    foreach ($stored_hashes as $relative_path => $stored_hash) {
        if (
            strpos($relative_path, '/') !== false ||
            in_array($relative_path, $ignored_files)
        ) {
            continue;
        }

        $full_path = $base_path . DIRECTORY_SEPARATOR . $relative_path;

        if (file_exists($full_path)) {
            $current_hash = hash_file('sha256', $full_path);
            if ($current_hash !== $stored_hash) {
                $tampered_files[] = $relative_path;
            }
        } else {
            $tampered_files[] = $relative_path . ' (missing)';
        }
    }

    // --- Remote vs Local comparison every 12 hours ---
    $now = time();
    if ($now - $last_check >= 43200) { // 12 hours
        $remote_url = 'https://kodpen.com/pinegrap_hash_referance[' . $current_version . '].json';
        $remote_context = stream_context_create(['http' => ['timeout' => 3]]);
        $remote_data = @file_get_contents($remote_url, false, $remote_context);

        if ($remote_data !== false) {
            $remote_hashes = json_decode($remote_data, true);
            if (is_array($remote_hashes)) {
                // Remove meta key before comparison
                unset($remote_hashes['last_hash_check']);

                // Find differences
                $missing_in_local = array_diff_key($remote_hashes, $stored_hashes);
                $extra_in_local = array_diff_key($stored_hashes, $remote_hashes);

                foreach ($missing_in_local as $file => $hash) {
                    $tampered_files[] = $file . ' (missing in local reference)';
                }
                foreach ($extra_in_local as $file => $hash) {
                    $tampered_files[] = $file . ' (extra in local reference)';
                }
                foreach ($remote_hashes as $file => $hash) {
                    if (isset($stored_hashes[$file]) && $stored_hashes[$file] !== $hash) {
                        $tampered_files[] = $file . ' (hash mismatch with remote)';
                    }
                }

                // Update local file with new remote + timestamp
                $remote_hashes['last_hash_check'] = $now;
                file_put_contents($reference_file, json_encode($remote_hashes, JSON_PRETTY_PRINT));
                $stored_hashes = $remote_hashes;
            }
        } else {
            // If remote still not reachable, just update timestamp to avoid retry loop
            $stored_hashes['last_hash_check'] = $now;
            file_put_contents($reference_file, json_encode($stored_hashes, JSON_PRETTY_PRINT));
        }
    }
    // --- END Remote vs Local comparison ---

    $local_result = empty($tampered_files) ? 'success' : 'missing_or_tampered_files';

    // Persist the local result into the reference file so the next request within 1 hour
    // can skip the expensive per-file hashing entirely.
    $saved = json_decode(file_get_contents($reference_file), true);
    if (is_array($saved)) {
        $saved['last_local_check'] = time();
        $saved['last_local_result'] = $local_result;
        file_put_contents($reference_file, json_encode($saved, JSON_PRETTY_PRINT));
    }

    // If tampered or missing files are found, log them
    if ($local_result === 'missing_or_tampered_files') {
        $output_names = '';
        foreach ($tampered_files as $tampered_file) {
            $output_names .= " " . $tampered_file . ", ";
        }

        log_activity(
            lang([
                'string' => 'Tampered or missing files detected: {var:1}',
                'vars' => [$output_names]
            ])
            ,
            'SYSTEM'
        );
    }

    return $local_result;
}

/**
 * Checks whether the current request is securely served over HTTPS
 * and returns 'success' or 'warning' for UI feedback.
 */
function check_ssl_status()
{
    // Common server variables that indicate HTTPS usage
    $https_enabled = (
        (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||
        (!empty($_SERVER['SERVER_PORT']) && $_SERVER['SERVER_PORT'] == 443) ||
        (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https') ||
        (!empty($_SERVER['REQUEST_SCHEME']) && $_SERVER['REQUEST_SCHEME'] === 'https')
    );

    if ($https_enabled) {
        return 'success';
    } else {
        return 'warning';
    }
}


/**
 * Get the dominant color area of an image file.
 * Works for raster formats (jpg, png, gif, webp).
 * Returns the most frequent color in hex format (e.g. "#aabbcc").
 *
 * @param string $file_path Full path to the image file.
 * @return string Hex color code.
 */
function get_dominant_area_color($file_path)
{
    // Fallback color if image is unreadable
    $fallback = '#9696968e';

    // Load image from file
    $image_data = @file_get_contents($file_path);
    if ($image_data === false) {
        return $fallback;
    }

    $image = @imagecreatefromstring($image_data);
    if ($image === false) {
        return $fallback;
    }

    $width = imagesx($image);
    $height = imagesy($image);

    // Sampling resolution (lower = faster, less accurate)
    $sample_step = max(1, round(min($width, $height) / 50));
    $color_count = array();

    // Loop through pixels with sampling
    for ($x = 0; $x < $width; $x += $sample_step) {
        for ($y = 0; $y < $height; $y += $sample_step) {
            $rgb = imagecolorat($image, $x, $y);
            $r = ($rgb >> 16) & 0xFF;
            $g = ($rgb >> 8) & 0xFF;
            $b = $rgb & 0xFF;

            // Round color to reduce noise (group similar tones)
            $r = round($r / 32) * 32;
            $g = round($g / 32) * 32;
            $b = round($b / 32) * 32;

            $hex = sprintf("#%02x%02x%02x", $r, $g, $b);

            if (!isset($color_count[$hex])) {
                $color_count[$hex] = 0;
            }
            $color_count[$hex]++;
        }
    }

    // Sort by frequency
    arsort($color_count);
    reset($color_count);

    // Return most frequent color
    return key($color_count);
}


/**
 * Get the first public root folder ID.
 *
 * This function queries the `folders` table and returns the `folder_id`
 * of the first record that matches:
 *   - folder_parent = 0
 *   - folder_level = 0
 *   - folder_access_control_type = 'public'
 *
 * If no matching record is found, the function returns 0.
 *
 * @return int The folder_id if found, otherwise 0
 */
function getPublicRootFolderId()
{
    // Run the query to fetch one matching folder
    $folder_id = db("
        SELECT folder_id
        FROM folder
        WHERE folder_parent = 0
          AND folder_level = 0
          AND folder_access_control_type = 'public'
        LIMIT 1
    ");
    // Check if a result exists
    if ($folder_id) {
        return (int) $folder_id;
    }

    // Return 0 if no record found
    return 0;
}

/**
 * Function: get_system_status_checks
 * ------------------------------------------
 * This function evaluates the overall health and security status of the system.
 * It performs multiple checks including:
 *   - File integrity validation
 *   - SSL/TLS connection status
 *   - Application-level security settings (password hint, CAPTCHA, strong password enforcement)
 *   - IndexNow key configuration
 *   - PHP version compatibility
 *   - Database table health (with repair attempts)
 *   - Required PHP extensions availability
 *   - Critical php.ini directives
 *
 * Each check contributes to a cumulative health score (0–100).
 *
 * It returns the checks as data, not as markup. The bar this used to print was
 * the only thing that could be done with a string of <span>s; the dashboard now
 * draws a gauge and a card per check from the same results, and settings.php
 * draws the same widget. Rendering lives in api.php, the checks live here.
 *
 * Returned shape:
 *   array(
 *     'score'  => int 0-100,
 *     'checks' => array of array(
 *         'group'   => 'security' | 'seo' | 'server',
 *         'icon'    => Bootstrap Icons class,
 *         'color'   => the text-* class the bar used,
 *         'state'   => 'ok' | 'warn' | 'fail' | 'info',
 *         'title'   => full check name, translated,
 *         'label'   => short name for a card, translated,
 *         'message' => explanation for the popover, translated,
 *         'value'   => short state text for the card, translated,
 *         'href'    => optional screen that acts on this check,
 *     ),
 *   )
 *
 * Translations are baked in before caching, which is safe because
 * SOFTWARE_LANGUAGE comes from the site config row and is the same for every
 * user of an installation.
 *
 * Compatibility: PHP 7.0 - 8.5
 * Returns: array
 */

function get_system_status_checks()
{
    // Cache result for 10 minutes to avoid running all checks on every call
    $cache_file = dirname(__FILE__) . '/data/temp/system_status_cache.json';
    if (file_exists($cache_file)) {
        $cached = json_decode(file_get_contents($cache_file), true);
        // A cache written by the version that stored rendered HTML has no
        // 'checks' key, so it simply misses and the checks run once more. No
        // migration, and no risk of handing a string to a caller expecting an
        // array.
        if (is_array($cached) && isset($cached['ts']) && isset($cached['checks'])
            && ((time() - $cached['ts']) < 600)
        ) {
            return $cached;
        }
    }

    $output = '';
    $score = 100;

    // Filled by $makeIcon below. $group moves as the checks pass each divider
    // and the closure reads it by reference, so a check lands in whichever
    // group it is written under without having to name it.
    $checks = array();
    $group = 'security';

    // Maximum points per check
    $weights = array(
        'file_integrity' => 30,
        'ssl' => 15,
        'password' => 10,
        'captcha' => 10,
        'strong_password' => 10,
        'indexnow' => 5,
        'php_version' => 15,
        'database' => 20,
        'extensions' => 5,
        'directives' => 20,
        'waf' => 10,
        'bot_filter' => 10,
        // Maintenance checks, folded in from the widget that used to carry
        // them separately. Deliberately lighter than the security ones: a
        // backup two days late is worth noticing, but it should not be able
        // to outweigh a firewall that is switched off.
        'backup' => 12,
        'update' => 6,
        'cron' => 8
    );

    // Icon rule for this bar — keep it when adding a check.
    //
    // The glyph identifies WHICH check it is, the colour identifies its STATE.
    // One glyph family per check, never shared: the bar is a row of ~12 icons at
    // 1.25rem, and two checks drawn from the same family (a shield for CAPTCHA and
    // a shield for the firewall, a padlock for SSL and a padlock for the password
    // hint) are indistinguishable at that size — the operator has to hover every
    // one of them to find out what they are looking at.
    //
    //   file      → file integrity        person   → CAPTCHA
    //   padlock   → SSL / TLS             key      → strong password
    //   eye       → password hint         shield   → web application firewall
    //   robot     → unknown bot filter    broadcast→ IndexNow
    //   terminal  → PHP version           database → database health
    //   puzzle    → PHP extensions        sliders  → php.ini directives
    //
    // Where the family offers a natural negative form (unlock, shield-slash,
    // database-x) use it for the failing state: it reinforces the colour instead
    // of competing with it. Otherwise the same glyph in a different colour is fine.
    //
    // The icons are printed in three groups — security, SEO, server — divided by
    // this rule. Same markup as the divider in front of the score.

    // Short names for the cards. The popover carries the full title and the
    // explanation; a card in a quarter-width dashboard column carries about ten
    // characters. Keyed by title deliberately, and kept here rather than in
    // api.php, so renaming a check and forgetting its short name is one edit
    // away from being noticed instead of a screen away.
    $short_labels = array(
        'Directory File Integrity' => 'Files',
        'SSL Status'               => 'SSL',
        'Password Management'      => 'Password',
        'CAPTCHA Protection'       => 'CAPTCHA',
        'Web Application Firewall' => 'WAF',
        'Unknown Bot Filtering'    => 'Bots',
        'IndexNow'                 => 'IndexNow',
        'PHP Version'              => 'PHP',
        'Database Health'          => 'Database',
        'PHP Extensions'           => 'Extensions',
        'PHP Directives'           => 'php.ini',
        // 'Backup' and 'Update' are already translated elsewhere as the verbs
        // on buttons -- "Yedekle", "Güncelle". A tile wants the noun, so these
        // point at keys of their own rather than borrowing a label that reads
        // as an instruction.
        // "Son yedek" is one character too wide once the tile gives up room
        // for its arrow, and the value beside it is already a time.
        'Last Backup'              => 'Backup age',
        'Software Update'          => 'Update status',
        'Scheduled Tasks'          => 'Tasks',
        'Database Size'            => 'DB Size',
    );

    // The three checks that answer "can someone get in": files that have been
    // tampered with, a connection in the clear, a firewall filtering nothing.
    // They lead the grid instead of sitting in run order among the rest, so the
    // first thing read is the thing that matters first. Titles again, for the
    // same reason as $short_labels -- renaming a check and forgetting this list
    // is one edit away from being noticed.
    $priority_titles = array(
        'Directory File Integrity',
        'SSL Status',
        'Web Application Firewall',
    );

    // Records one check. Named $makeIcon still, and still called as
    // `$output .= $makeIcon(...)`, because every one of the thirty-odd call
    // sites below keeps its exact condition, weight, glyph and wording that
    // way -- the change is where the result goes, not what is checked.
    //
    // 'value' defaults to a word derived from the colour. Checks with something
    // more specific to say -- a backup age, a version -- pass their own.
    $makeIcon = function ($icon, $color, $title, $content, $value = '', $href = '', $detail = array()) use (&$checks, &$group, $short_labels, $priority_titles) {

        $state = 'info';
        if (strpos($color, 'success') !== false) {
            $state = 'ok';
        } elseif (strpos($color, 'warning') !== false) {
            $state = 'warn';
        } elseif (strpos($color, 'danger') !== false) {
            $state = 'fail';
        }

        if ($value === '') {
            $defaults = array(
                'ok'   => 'OK',
                'warn' => 'Warning',
                'fail' => 'Problem',
                'info' => 'Not applicable',
            );
            $value = lang($defaults[$state]);
        }

        $checks[] = array(
            'group'   => $group,
            'icon'    => $icon,
            'color'   => $color,
            'state'   => $state,
            'title'   => lang($title),
            'label'   => lang(isset($short_labels[$title]) ? $short_labels[$title] : $title),
            'message' => lang($content),
            'value'   => $value,
            'href'    => $href,
            'priority' => in_array($title, $priority_titles),
            // Rows the tile can expand to. Only the scheduled-task check fills
            // this: per-job run times exist nowhere else in the panel, so the
            // tile has to be able to show them rather than point at a screen
            // that does not have the answer.
            'detail'  => $detail,
        );

        return '';
    };

    // 🔍 File integrity check
    if (defined('ENVIRONMENT') && ENVIRONMENT === 'development') {
        $output .= $makeIcon(
            'bi-file-earmark-minus-fill',
            'text-secondary',
            'Directory File Integrity',
            'This feature cannot be used in development mode. For security, disable development mode if it is not required.'
        );
        $score -= $weights['file_integrity'] * 0.5;
    } else {
        $file_integrity = function_exists('check_directory_file_integrity') ? check_directory_file_integrity() : 'unable_to_resolve_directory';
        switch ($file_integrity) {
            case 'unable_to_resolve_directory':
                $output .= $makeIcon(
                    'bi-file-earmark-minus-fill',
                    'text-warning',
                    'Directory File Integrity',
                    'Unable to resolve directory for file integrity check.'
                );
                $score -= $weights['file_integrity'] * 0.5;
                break;
            case 'unable_to_fetch_reference':
            case 'missing_or_tampered_files':
                $output .= $makeIcon(
                    'bi-file-earmark-x-fill',
                    'text-danger',
                    'Directory File Integrity',
                    'Warning: Missing or tampered files detected!'
                );
                $score -= $weights['file_integrity'];
                break;
            case 'success':
                $output .= $makeIcon(
                    'bi-file-earmark-check-fill',
                    'text-success',
                    'Directory File Integrity',
                    'All files are intact.'
                );
                break;
        }
    }

    // 🔒 SSL status check
    $ssl_status = function_exists('check_ssl_status') ? check_ssl_status() : 'unknown';
    $url_scheme = defined('URL_SCHEME') ? URL_SCHEME : '';
    if ($ssl_status === 'success' && $url_scheme !== 'https://') {
        $output .= $makeIcon(
            'bi-lock-fill',
            'text-warning',
            'SSL Status',
            'SSL is active but URL scheme is not HTTPS. Please enable Security Mode from Site Settings.'
        );
        $score -= $weights['ssl'] * 0.3;
    } elseif ($ssl_status === 'success') {
        $output .= $makeIcon(
            'bi-lock-fill',
            'text-success',
            'SSL Status',
            'Secure connection: SSL is active.'
        );
    } else {
        $output .= $makeIcon(
            'bi-unlock-fill',
            'text-danger',
            'SSL Status',
            'SSL is not active. Your connection may not be secure.'
        );
        $score -= $weights['ssl'];
    }

    // 👁 Password hint — an eye, because the risk is that the hint reveals something.
    if (defined('PASSWORD_HINT') && PASSWORD_HINT) {
        $output .= $makeIcon(
            'bi-eye-fill',
            'text-danger',
            'Password Management',
            'Password hint is enabled. This may reduce security.'
        );
        $score -= $weights['password'];
    }

    // 🧍 CAPTCHA — a person, because the question it answers is "is this a human".
    if (defined('CAPTCHA')) {
        if (CAPTCHA) {
            $output .= $makeIcon(
                'bi-person-check-fill',
                'text-success',
                'CAPTCHA Protection',
                'CAPTCHA protection is enabled.'
            );
        } else {
            $output .= $makeIcon(
                'bi-person-x-fill',
                'text-danger',
                'CAPTCHA Protection',
                'CAPTCHA protection is disabled.'
            );
            $score -= $weights['captcha'];
        }
    }

    // 🔑 Strong password — the key family belongs to passwords, filled when enforced.
    if (defined('STRONG_PASSWORD')) {
        if (STRONG_PASSWORD) {
            $output .= $makeIcon(
                'bi-key-fill',
                'text-success',
                'Password Management',
                'Strong password enforcement is enabled.'
            );
        } else {
            $output .= $makeIcon(
                'bi-key',
                'text-danger',
                'Password Management',
                'Strong password enforcement is disabled.'
            );
            $score -= $weights['strong_password'];
        }
    }

    // 🛡️ Web application firewall
    // waf_mode() is the single source of truth: it already folds in the Enable
    // Firewall checkbox, the schema check and the monitor/block setting.
    $waf_current_mode = function_exists('waf_mode') ? waf_mode() : 'off';
    if ($waf_current_mode === 'block') {
        $output .= $makeIcon(
            'bi-shield-fill-check',
            'text-success',
            'Web Application Firewall',
            'The firewall is enabled and blocking malicious requests.'
        );
    } elseif ($waf_current_mode === 'monitor') {
        // Monitor mode records what would have been blocked but stops nothing,
        // so it must not be scored as full protection.
        $output .= $makeIcon(
            'bi-shield-fill-exclamation',
            'text-warning',
            'Web Application Firewall',
            'The firewall is in monitor mode: it records attacks but does not block them.'
        );
        $score -= $weights['waf'] * 0.5;
    } else {
        $output .= $makeIcon(
            'bi-shield-slash-fill',
            'text-danger',
            'Web Application Firewall',
            'The firewall is disabled. No requests are being filtered.'
        );
        $score -= $weights['waf'];
    }

    // 🤖 Unknown bot filtering
    // The Enable Firewall checkbox is an absolute off switch (waf_run()), so this
    // option does nothing while the firewall is off. Reporting it as enabled in
    // that state would be a false all clear.
    if ($waf_current_mode === 'off') {
        $output .= $makeIcon(
            'bi-robot',
            'text-danger',
            'Unknown Bot Filtering',
            'Unknown bots are not being blocked, because the firewall is disabled.'
        );
        $score -= $weights['bot_filter'];
    } elseif (defined('BLOCK_UNKNOWN_BOTS') && BLOCK_UNKNOWN_BOTS) {
        $output .= $makeIcon(
            'bi-robot',
            'text-success',
            'Unknown Bot Filtering',
            'Unknown bots are being blocked.'
        );
    } else {
        $output .= $makeIcon(
            'bi-robot',
            'text-warning',
            'Unknown Bot Filtering',
            'Unknown bots are not being blocked.'
        );
        $score -= $weights['bot_filter'];
    }

    // Security checks end here. The groups still exist -- they are what lets
    // the cards be read as "is my site secure" then "is my server healthy"
    // rather than as one undifferentiated grid.
    $group = 'seo';

    // 📡 IndexNow — a broadcast, because the feature announces changes to search
    // engines. It used to borrow the key glyph, which collided with the password
    // check next to it.
    if (defined('INDEXNOW_KEY') && INDEXNOW_KEY !== '') {
        $key_file_path = FILE_DIRECTORY_PATH . '/' . INDEXNOW_KEY . '.txt';
        if (file_exists($key_file_path)) {
            $output .= $makeIcon(
                'bi-broadcast-pin',
                'text-success',
                'IndexNow',
                'IndexNow configuration is successful.'
            );
        } else {
            $output .= $makeIcon(
                'bi-broadcast',
                'text-warning',
                'IndexNow',
                'Warning: IndexNow key is set but the verification file is missing.'
            );
            $score -= $weights['indexnow'] * 0.5;
        }
    } else {
        $output .= $makeIcon(
            'bi-broadcast',
            'text-warning',
            'IndexNow',
            'Warning: IndexNow has not been configured yet.'
        );
        $score -= $weights['indexnow'];
    }

    $group = 'server';

    // 🐘 PHP version
    $php_version = PHP_VERSION;
    if (version_compare($php_version, '7.0.0', '<')) {
        $output .= $makeIcon(
            'bi-terminal-x',
            'text-danger',
            'PHP Version',
            'Your PHP version is outdated and insecure. Upgrade to PHP 8.3 or higher immediately.'
        );
        $score -= $weights['php_version'];
    } elseif (version_compare($php_version, '8.3.0', '<')) {
        $output .= $makeIcon(
            'bi-terminal-dash',
            'text-warning',
            'PHP Version',
            'Your PHP version is supported but may lack full compatibility. Please upgrade to PHP 8.3 or higher.'
        );
        $score -= $weights['php_version'] * 0.3;
    } else {
        $output .= $makeIcon(
            'bi-terminal-fill',
            'text-success',
            'PHP Version',
            'Your PHP version is fully compatible.'
        );
    }

    // 🗄️ Database tables check
    $db_report = check_and_repair_database_tables();
    $issues = 0;
    $repairs = 0;
    foreach ($db_report as $table => $messages) {
        foreach ($messages as $msg) {
            if ($msg === "error")
                $issues++;
            if ($msg === "repaired")
                $repairs++;
        }
    }
    if ($issues > 0) {
        $output .= $makeIcon(
            'bi-database-x',
            'text-danger',
            'Database Health',
            lang(array('string' => 'Database issues detected in {var:1} table(s).', 'vars' => array($issues)))
        );
        $score -= $weights['database'];
    } elseif ($repairs > 0) {
        $output .= $makeIcon(
            'bi-database-exclamation',
            'text-warning',
            'Database Health',
            lang(array('string' => '{var:1} table(s) had issues but were repaired.', 'vars' => array($repairs)))
        );
        $score -= $weights['database'] * 0.5;
    } else {
        $output .= $makeIcon(
            'bi-database-check',
            'text-success',
            'Database Health',
            'All database tables are healthy.'
        );
    }
    // 📦 PHP extensions check with alias support for IIS and Apache
    // Some extensions report a different name depending on the build
    // (e.g. 'Zend OPcache' vs 'opcache'), hence the alias lists.
    //
    // Two tiers on purpose. Only extensions the software actually calls cost
    // score. 'memcache' used to sit in the scoring list although Pinegrap never
    // calls it anywhere — practically nobody has it installed, so it deducted the
    // full extension weight on every install forever, with nothing the operator
    // could do about it. A penalty that can never be cleared teaches the operator
    // to ignore the score.
    $required_extensions = array(
        'mysqli'   => array('mysqli'),                    // every database query
        'curl'     => array('curl'),                      // licence, updates, gateways, IndexNow
        'openssl'  => array('openssl'),                   // encrypt_string_with_iv(), API secret keys
        'mbstring' => array('mbstring'),                  // lang() case conversion, Turkish İ/ı
        'zip'      => array('zip'),                       // update packages, backups, import / export
        'fileinfo' => array('fileinfo'),                  // upload MIME detection
        'opcache'  => array('opcache', 'Zend OPcache')    // bytecode cache
    );

    // Reported but never deducted: nothing breaks without them. imagick falls back
    // to GD in optimize_image() and edit_file.php, and memcached is not used at all
    // — it is listed so the operator can see whether it is available.
    $optional_extensions = array(
        'imagick'   => array('imagick'),
        'memcached' => array('memcached', 'memcache')
    );

    $extension_is_loaded = function ($aliases) {
        foreach ($aliases as $ext_name) {
            if (extension_loaded($ext_name)) {
                return true;
            }
        }
        return false;
    };

    $missing_ext = array();
    foreach ($required_extensions as $label => $aliases) {
        if (!$extension_is_loaded($aliases)) {
            $missing_ext[] = $label;
        }
    }

    $missing_optional_ext = array();
    foreach ($optional_extensions as $label => $aliases) {
        if (!$extension_is_loaded($aliases)) {
            $missing_optional_ext[] = $label;
        }
    }

    // The prefix is translated on its own. Composing the sentence first and handing
    // the whole thing to lang() never matched a key, so the Turkish translation
    // already sitting in tr.json was never actually used.
    if (!empty($missing_ext)) {
        $output .= $makeIcon(
            'bi-puzzle-fill',
            'text-danger',
            'PHP Extensions',
            rtrim(lang('Missing extension(s): ')) . ' ' . implode(', ', $missing_ext)
        );
        $score -= $weights['extensions'];
    } elseif (!empty($missing_optional_ext)) {
        // Grey, not yellow: nothing is wrong here. memcached is almost never
        // installed, so a warning colour would sit on this icon permanently and
        // become background noise — the same trap as the old memcache penalty.
        $output .= $makeIcon(
            'bi-puzzle-fill',
            'text-secondary',
            'PHP Extensions',
            rtrim(lang('All required PHP extensions are loaded.')) . ' '
                . rtrim(lang('Optional extension(s) not installed:')) . ' '
                . implode(', ', $missing_optional_ext)
        );
    } else {
        $output .= $makeIcon(
            'bi-puzzle-fill',
            'text-success',
            'PHP Extensions',
            'All required PHP extensions are loaded.'
        );
    }


    // ⚙️ php.ini directives check
    $directives = array(
        'allow_url_fopen' => ini_get('allow_url_fopen'),
        'short_open_tag' => ini_get('short_open_tag')
    );
    $disabled = array();
    foreach ($directives as $dir => $val) {
        if (!$val || strtolower($val) === 'off' || $val == 0) {
            $disabled[] = $dir;
        }
    }
    if (empty($disabled)) {
        $output .= $makeIcon(
            'bi-sliders',
            'text-success',
            'PHP Directives',
            'All critical php.ini directives are enabled.'
        );
    } else {
        $output .= $makeIcon(
            'bi-sliders',
            'text-danger',
            'PHP Directives',
            'Disabled directive(s): ' . implode(', ', $disabled)
        );
        $score -= $weights['directives'];
    }

    $group = 'maintenance';

    // 💾 Last backup
    //
    // Read from the directory, NOT from config.last_software_auto_backup. That
    // column is the scheduler's cursor, not a record of what happened: opening
    // backups.php sets it to 0 to force the next run, so a check trusting it
    // would announce "never backed up" to anyone who had just visited the
    // backup screen. The folders are the only thing that knows.
    $backup_path = dirname(__FILE__) . '/data/backups';
    $backup_count = 0;
    $backup_newest = 0;

    // Shipped with the product as install fixtures, not produced by any backup
    // run. Counting them would let a site that has never been backed up show
    // two backups dated the day it was installed.
    $backup_seed = array('english_default', 'turkish_default');

    if (is_dir($backup_path)) {
        $backup_entries = @scandir($backup_path);
        if ($backup_entries !== false) {
            foreach ($backup_entries as $backup_entry) {
                if (($backup_entry == '.') || ($backup_entry == '..')) {
                    continue;
                }
                if (in_array($backup_entry, $backup_seed)) {
                    continue;
                }
                if (!is_dir($backup_path . '/' . $backup_entry)) {
                    continue;
                }
                $backup_count++;
                // stat per folder, never a recursive walk. folderSize() on this
                // directory would read every file of every backup — gigabytes —
                // for one number on a card.
                $backup_stamp = @filemtime($backup_path . '/' . $backup_entry);
                if ($backup_stamp && ($backup_stamp > $backup_newest)) {
                    $backup_newest = (int) $backup_stamp;
                }
            }
        }
    }

    $auto_backup_off = (defined('SOFTWARE_AUTO_BACKUP') && (SOFTWARE_AUTO_BACKUP == false));

    if ($backup_newest < 1) {
        $backup_icon = 'bi-hdd-network-fill';
        $backup_color = 'text-danger';
        $backup_value = lang('Never');
        $backup_message = 'No backup has ever been taken of this site.';
        $score -= $weights['backup'];
    } else {
        $backup_age = time() - $backup_newest;
        $backup_value = get_relative_time(array('timestamp' => $backup_newest, 'format' => 'plain_text'));
        $backup_icon = 'bi-hdd-network-fill';

        // Two days covers a daily schedule that missed one run; a week means
        // the schedule itself has stopped.
        if ($backup_age > 604800) {
            $backup_color = 'text-danger';
            $backup_message = 'The most recent backup is more than a week old.';
            $score -= $weights['backup'];
        } elseif ($backup_age > 172800) {
            $backup_color = 'text-warning';
            $backup_message = 'The most recent backup is more than two days old.';
            $score -= $weights['backup'] * 0.5;
        } else {
            $backup_color = 'text-success';
            $backup_message = 'A recent backup exists.';
        }
    }

    // A switched-off schedule is not a stale backup. Scoring it as one would
    // train the operator who turned it off deliberately to ignore the number,
    // so it costs half and reads grey rather than red.
    if ($auto_backup_off && ($backup_color == 'text-danger')) {
        $score += $weights['backup'] * 0.5;
        $backup_color = 'text-secondary';
        $backup_message = 'Automatic backup is turned off.';
    }

    $output .= $makeIcon(
        $backup_icon,
        $backup_color,
        'Last Backup',
        $backup_message,
        $backup_value,
        'backups.php'
    );

    // ⬆️ Software update
    //
    // SOFTWARE_UPDATE_AVAILABLE is set in init.php from the periodic check; the
    // timestamp says how much that answer is worth. A check from two months ago
    // saying "up to date" is not information.
    $update_available = (defined('SOFTWARE_UPDATE_AVAILABLE') && SOFTWARE_UPDATE_AVAILABLE);
    $update_checked = defined('LAST_SOFTWARE_UPDATE_CHECK_TIMESTAMP')
        ? (int) LAST_SOFTWARE_UPDATE_CHECK_TIMESTAMP
        : 0;

    if ($update_available) {
        $output .= $makeIcon(
            'bi-arrow-up-circle-fill',
            'text-warning',
            'Software Update',
            'A software update is available.',
            lang('New version'),
            'software_update.php'
        );
        $score -= $weights['update'];
    } elseif ($update_checked < 1) {
        $output .= $makeIcon(
            'bi-arrow-up-circle',
            'text-warning',
            'Software Update',
            'The software has never been checked for updates, so it is not known whether one is waiting.',
            lang('Not checked'),
            'software_update.php'
        );
        $score -= $weights['update'] * 0.5;
    } else {
        $output .= $makeIcon(
            'bi-check-circle-fill',
            'text-success',
            'Software Update',
            'The software is up to date.',
            defined('VERSION') ? VERSION : lang('OK'),
            'software_update.php'
        );
    }

    // ⏱ Scheduled tasks
    //
    // The cron entries live outside the software, so nothing here can ask
    // whether a job is scheduled. What the panel has is the run each job
    // records when it finishes; the useful signal is a job that used to finish
    // and no longer does.
    //
    // Never run is therefore NOT a failure and costs nothing — it is a site
    // that does not use that job, or one whose cron was never set up. The
    // penalty is reserved for a job with a recorded run that has since gone
    // quiet, which is unambiguous: it worked, now it doesn't.
    $cron_runs = function_exists('pg_cron_last_runs') ? pg_cron_last_runs() : null;

    // null means the table is not there yet. Silence beats reporting every job
    // as broken on an installation that has simply not been upgraded.
    if ($cron_runs !== null) {

        $cron_jobs = pg_cron_jobs();
        $cron_ok = 0;
        $cron_never = 0;
        $cron_stalled = array();
        $cron_detail = array();

        foreach ($cron_jobs as $cron_key => $cron_job) {

            $cron_seen = isset($cron_runs[$cron_key]) ? (int) $cron_runs[$cron_key] : 0;

            if ($cron_seen < 1) {
                $cron_never++;
                $cron_state = 'info';
                $cron_when = lang('Never');
            } elseif ((time() - $cron_seen) > (int) $cron_job['stale_after']) {
                $cron_stalled[] = $cron_job['label'];
                $cron_state = 'fail';
                // plain_text: a <time> element would be baked into the cache
                // and carry a tooltip built from a timestamp up to ten minutes
                // out of date. The text is relative either way.
                $cron_when = get_relative_time(array('timestamp' => $cron_seen, 'format' => 'plain_text'));
            } else {
                $cron_ok++;
                $cron_state = 'ok';
                $cron_when = get_relative_time(array('timestamp' => $cron_seen, 'format' => 'plain_text'));
            }

            $cron_detail[] = array(
                'label' => $cron_job['label'],
                'state' => $cron_state,
                'when'  => $cron_when,
            );
        }

        if ($cron_stalled) {
            $output .= $makeIcon(
                'bi-clock-fill',
                'text-danger',
                'Scheduled Tasks',
                rtrim(lang('Scheduled task(s) that have stopped running:')) . ' ' . implode(', ', $cron_stalled),
                lang(array(
                    'string' => '{var:1} stopped',
                    'vars' => number_format(count($cron_stalled)),
                )),
                '',
                $cron_detail
            );
            $score -= $weights['cron'];
        } elseif ($cron_ok > 0) {
            $output .= $makeIcon(
                'bi-clock-fill',
                'text-success',
                'Scheduled Tasks',
                'Scheduled tasks are running on time.',
                lang(array(
                    'string' => '{var:1} running',
                    'vars' => number_format($cron_ok),
                )),
                '',
                $cron_detail
            );
        } else {
            $output .= $makeIcon(
                'bi-clock',
                'text-secondary',
                'Scheduled Tasks',
                'No scheduled task has run yet. Set up cron jobs if you want them.',
                // Shorter than 'Never' on purpose: this tile carries a chevron
                // as well, and "Hiçbir zaman" does not fit beside it. The
                // per-job panel underneath spells it out anyway.
                lang('None yet'),
                '',
                $cron_detail
            );
        }
    }

    // 🗄 Database size
    //
    // Reported, never scored. There is no size at which a database is wrong:
    // a busy shop's is large because the shop works. Any threshold here would
    // be a number invented in this file and charged to sites that grew.
    //
    // information_schema is readable for one's own schema on ordinary hosting
    // but not everywhere, and the figure is the storage engine's estimate. Both
    // argue for reporting nothing rather than guessing, so a null simply leaves
    // the card out.
    $db_bytes = db_value(
        "SELECT SUM(data_length + index_length)
         FROM information_schema.TABLES
         WHERE table_schema = DATABASE()");

    if ($db_bytes !== null && $db_bytes !== '') {
        $output .= $makeIcon(
            'bi-hdd-fill',
            'text-secondary',
            'Database Size',
            'Total size of the data and indexes in this site\'s database.',
            convert_bytes_to_string((float) $db_bytes, 1)
        );
    }

    // Clamp score
    if ($score < 0)
        $score = 0;
    if ($score > 100)
        $score = 100;

    $result = array(
        'ts' => time(),
        'score' => (int) round($score),
        'checks' => $checks,
    );

    // Write cache
    $cache_dir = dirname(__FILE__) . '/data/temp';
    if (!is_dir($cache_dir)) {
        mkdir($cache_dir, 0755, true);
    }
    file_put_contents($cache_file, json_encode($result));

    return $result;
}



/**
 * Function: check_database_tables
 * ------------------------------------------
 * This function checks the health of database tables without repairing them.
 * It uses the db() function to execute SQL queries (CHECK TABLE).
 * Results are collected in a report array and log entries are created for each
 * detected issue (corrupt or error).
 *
 * Compatibility: PHP 7.0 - 8.5
 * Returns: array containing check messages for each table
 */

function check_and_repair_database_tables()
{
    // Return cached result if available and less than 1 hour old, to avoid running
    // ~130 CHECK TABLE queries on every welcome.php page load.
    $cache_file = dirname(__FILE__) . '/data/temp/db_health_cache.json';
    if (file_exists($cache_file)) {
        $cache = json_decode(file_get_contents($cache_file), true);
        if (is_array($cache) && isset($cache['last_check']) && (time() - (int) $cache['last_check']) < 3600) {
            return $cache['report'] ?? [];
        }
    }

    // List of tables to check
    $tables = array(
        'aclfolder',
        'ad_regions',
        'address_book',
        'ads',
        'affiliate_sign_up_form_pages',
        'allow_new_comments_for_items',
        'applied_gift_cards',
        'arrival_dates',
        'auto_dialogs',
        'banned_ip_addresses',
        'billing_information_pages',
        'calendar_event_exceptions',
        'calendar_event_locations',
        'calendar_event_view_pages',
        'calendar_event_views_calendars_xref',
        'calendar_events',
        'calendar_events_calendar_event_locations_xref',
        'calendar_events_calendars_xref',
        'calendar_view_pages',
        'calendar_views_calendars_xref',
        'calendars',
        'catalog_detail_pages',
        'catalog_pages',
        'comments',
        'commissions',
        'config',
        'contact_groups',
        'contact_groups_email_campaigns_xref',
        'contacts',
        'contacts_contact_groups_xref',
        'containers',
        'cookies',
        'countries',
        'cregion',
        'currencies',
        'custom_form_confirmation_pages',
        'custom_form_pages',
        'dregion',
        'email_a_friend_pages',
        'email_campaign_profiles',
        'email_campaigns',
        'email_recipients',
        'excluded_transit_dates',
        'express_order_pages',
        'files',
        'folder',
        'folder_view_pages',
        'form_data',
        'form_field_options',
        'form_fields',
        'form_item_view_pages',
        'form_list_view_browse_fields',
        'form_list_view_filters',
        'form_list_view_pages',
        'form_view_directories_form_list_views_xref',
        'form_view_directory_pages',
        'forms',
        'gift_cards',
        'key_codes',
        'log',
        'login_regions',
        'menu_items',
        'menus',
        'messages',
        'next_order_number',
        'offer_actions',
        'offer_actions_shipping_methods_xref',
        'offer_rules',
        'offer_rules_products_xref',
        'offers',
        'offers_offer_actions_xref',
        'opt_in',
        'order_form_pages',
        'order_item_gift_cards',
        'order_items',
        'order_preview_pages',
        'order_receipt_pages',
        'order_report_filters',
        'order_reports',
        'orders',
        'page',
        'photo_gallery_pages',
        'pregion',
        'preview_styles',
        'product_attribute_options',
        'product_attributes',
        'product_groups',
        'product_groups_attributes_xref',
        'products_images_xref',
        'product_groups_images_xref',
        'product_submit_form_fields',
        'products',
        'products_attributes_xref',
        'products_groups_xref',
        'products_zones_xref',
        'recurring_commission_profiles',
        'referral_sources',
        'remaining_reservation_spots',
        'search_items',
        'search_results_pages',
        'ship_date_adjustments',
        'ship_tos',
        'shipping_address_and_arrival_pages',
        'shipping_cutoffs',
        'shipping_delivery_dates',
        'shipping_method_pages',
        'shipping_methods',
        'shipping_methods_zones_xref',
        'shipping_rates',
        'shipping_tracking_numbers',
        'shopping_cart_pages',
        'short_links',
        'states',
        'style',
        'submitted_form_info',
        'submitted_form_view_stats',
        'submitted_form_views',
        'system_style_cells',
        'system_theme_css_rules',
        'tag_cloud_keywords',
        'tag_cloud_keywords_xref',
        'target_options',
        'tax_zones',
        'tax_zones_countries_xref',
        'tax_zones_states_xref',
        'talks',
        'update_address_book_pages',
        'user',
        'users_ad_regions_xref',
        'users_calendars_xref',
        'users_common_regions_xref',
        'users_contact_groups_xref',
        'users_menus_xref',
        'users_messages_xref',
        'verified_shipping_addresses',
        'visitor_report_filters',
        'visitor_reports',
        'visitors',
        'watchers',
        'zones',
        'zones_countries_xref',
        'zones_states_xref',
        'dashboard',
        'custom_apps',
        'notifications',
        'local_sale_history',
        'local_sale_history_items',
        'iyzipay_3ds_state',
        'chat_conversations',
        'chat_messages',
        'seo_issue',
        'seo_link'
    );

    $report = [];

    foreach ($tables as $table) {
        $check = db("CHECK TABLE `$table`");
        if ($check && is_array($check)) {
            foreach ($check as $row) {

                $status = isset($row['Msg_text']) ? $row['Msg_text'] : '';


                if (stripos($status, 'error') !== false || stripos($status, 'corrupt') !== false) {
                    // log issue
                    log_activity(lang([
                        'string' => 'Database table issue detected: {var:1} ({var:2})',
                        'vars' => [$table, $status]
                    ]), $_SESSION['sessionusername']);

                    // try repair
                    $repair = db("REPAIR TABLE `$table`");
                    $fixed = false;
                    if ($repair && is_array($repair)) {
                        foreach ($repair as $r) {
                            $repair_status = isset($r['Msg_text']) ? $r['Msg_text'] : '';
                            if (stripos($repair_status, 'OK') !== false) {
                                $fixed = true;
                            }
                            log_activity(lang([
                                'string' => 'Repair attempted on table {var:1}: {var:2}',
                                'vars' => [$table, $repair_status]
                            ]), $_SESSION['sessionusername']);
                        }
                    }
                    $report[$table][] = $fixed ? "repaired" : "error";
                } else {
                    $report[$table][] = "healthy";
                }
            }
        } else {
            $report[$table][] = "check_failed";
        }
    }

    // Cache the result so subsequent loads within 1 hour skip the 130 CHECK TABLE queries.
    if (!is_dir(dirname($cache_file))) {
        mkdir(dirname($cache_file), 0755, true);
    }
    file_put_contents($cache_file, json_encode(['last_check' => time(), 'report' => $report]));

    return $report;
}




//Developers define to config.php to page name and an unlock pin to lock pages.
//If page name define like below, users redirect to developer_lock.php.
//Software ask's pin code to unlock and access to page.
//If user enter pin  correct, software redirect user to page try to access and no redirect developer_lock.php until Pin code is change.
function initialize_developer_security()
{
    // Ensure database connection and session user are available
    if (defined('DB_CONNECTED') && isset($_SESSION['sessionusername'])) {

        $SUser = mysqli_real_escape_string(db::$con, $_SESSION['sessionusername']);

        // Fetch developer PIN hash from database
        $query = "SELECT user_devpasspin FROM user WHERE user_username = '" . $SUser . "'";
        $result = mysqli_query(db::$con, $query) or output_error(lang('Query failed.'));
        $row = mysqli_fetch_assoc($result);
        $devpasspin = $row['user_devpasspin'];

        // Get current script name
        $url_path_parts = explode('/', $_SERVER['SCRIPT_NAME']);
        $file_name = end($url_path_parts);

        // If page is locked and PIN is defined and not verified, redirect to lock screen
        if (
            defined('LOCKED_PAGES') &&
            in_array($file_name, LOCKED_PAGES) &&
            DEVELOPER_PIN !== '' &&
            $devpasspin !== md5(DEVELOPER_PIN)
        ) {
            $_SESSION["filename"] = $file_name;
            header('Location: ' . URL_SCHEME . $_SERVER['HTTP_HOST'] . PATH . SOFTWARE_DIRECTORY . '/developer_lock.php');
            exit;
        }

        // Return last attempted filename if available
        if (isset($_SESSION["filename"])) {
            return $_SESSION["filename"];
        }
    }
}

/**
 * Decrypt API/Secret keys stored in DB.
 */
function decode_ssl_keys($key_base64, $iv_base64)
{
    $crypto_method = 'aes-256-cbc';
    $crypto_key = substr(hash('sha256', ENCRYPTION_KEY, true), 0, 32);
    $key = base64_decode($key_base64);
    $iv = base64_decode($iv_base64);
    if ($key === false || $iv === false)
        return '';
    $decrypted = openssl_decrypt($key, $crypto_method, $crypto_key, OPENSSL_RAW_DATA, $iv);
    return ($decrypted !== false) ? $decrypted : '';
}

/**
 * Encrypt a string with AES-256-CBC and return [encrypted_base64, iv_base64].
 */
function encrypt_string_with_iv($plaintext)
{
    $crypto_method = 'aes-256-cbc';
    $crypto_key = substr(hash('sha256', ENCRYPTION_KEY, true), 0, 32);
    $ivlen = openssl_cipher_iv_length($crypto_method);
    $iv = function_exists('random_bytes') ? random_bytes($ivlen) : openssl_random_pseudo_bytes($ivlen);
    $encrypted_raw = openssl_encrypt($plaintext, $crypto_method, $crypto_key, OPENSSL_RAW_DATA, $iv);
    return array(base64_encode($encrypted_raw), base64_encode($iv));
}

/**
 * Calculate how much an image file can be optimizeable.
 *
 * This function estimates the potential optimization percentage
 * by comparing the original file size with the size after running
 * optimize_this_image() (without overwriting the original).
 * It returns a string like "10%" to show how much the file
 * could be reduced if optimized.
 *
 * @param string $file_path Full path to the image file
 * @return string Percentage string (e.g. "10%")
 */
function calculate_optimizable_percent($file_path)
{
    if (!file_exists($file_path))
        return "0%";

    $original_size = filesize($file_path);

    // Run optimize function but don't overwrite original file
    $optimized_data = optimize_this_image($file_path);
    if ($optimized_data === false)
        return "0%";

    $optimized_size = strlen($optimized_data);

    if ($original_size > 0) {
        $percent = round((($original_size - $optimized_size) / $original_size) * 100);
        return max(0, $percent) . "%";
    }
    return "0%";
}

/**
 * Optimize an image file by removing unnecessary metadata and applying compression.
 *
 * This function uses Imagick if available, otherwise falls back to GD.
 * - Preserves orientation information
 * - Strips metadata
 * - Adjusts colorspace
 * - Sets compression scheme and quality based on image dimensions
 *
 * Supported formats: JPEG, PNG, GIF, WebP, BMP (Imagick only for BMP)
 *
 * @param string $file_path Full path to the image file
 * @return string|false Optimized binary image data or false on failure
 */
function optimize_this_image($file_path)
{
    if (!file_exists($file_path))
        return false;

    $mime = detect_mime_type($file_path);
    $ext = strtolower(pathinfo($file_path, PATHINFO_EXTENSION));

    // Imagick preferred
    if (class_exists('Imagick')) {
        try {
            $image = new Imagick($file_path);

            // Preserve orientation
            $orientation = $image->getImageOrientation();

            // Strip metadata but keep orientation
            $image->stripImage();
            $image->setImageOrientation($orientation);

            $image->setColorspace(Imagick::COLORSPACE_RGB);

            $width = $image->getImageWidth();
            $height = $image->getImageHeight();
            $max_dim = max($width, $height);

            // Quality based on dimensions
            if ($max_dim <= 720) {
                $quality = 85;
            } elseif ($max_dim <= 1280) {
                $quality = 75;
            } elseif ($max_dim <= 1920) {
                $quality = 65;
            } else {
                $quality = 60;
            }

            // Compression settings
            if (in_array($mime, ['image/jpeg', 'image/jpg'])) {
                $image->setInterlaceScheme(Imagick::INTERLACE_PLANE);
                $image->setImageCompression(Imagick::COMPRESSION_JPEG);
            }
            if ($mime === 'image/png') {
                $image->setImageCompression(Imagick::COMPRESSION_ZIP);
            }
            if ($mime === 'image/webp') {
                $image->setImageCompression(Imagick::COMPRESSION_WEBP);
            }

            $image->setImageCompressionQuality($quality);

            $tmp = tempnam(sys_get_temp_dir(), 'optimg_');
            $image->writeImage($tmp);
            $image->destroy();

            return file_get_contents($tmp);
        } catch (Exception $e) {
            return false;
        }
    }

    // GD fallback (GD does not preserve EXIF orientation or metadata)
    try {
        switch ($mime) {
            case 'image/jpeg':
            case 'image/jpg':
                $img = imagecreatefromjpeg($file_path);
                break;
            case 'image/png':
                $img = imagecreatefrompng($file_path);
                break;
            case 'image/gif':
                $img = imagecreatefromgif($file_path);
                break;
            case 'image/webp':
                if (function_exists('imagecreatefromwebp')) {
                    $img = imagecreatefromwebp($file_path);
                } else {
                    return false;
                }
                break;
            default:
                return false;
        }

        $width = imagesx($img);
        $height = imagesy($img);
        $max_dim = max($width, $height);

        // Quality based on dimensions
        if ($max_dim <= 720) {
            $quality = 85;
        } elseif ($max_dim <= 1280) {
            $quality = 75;
        } elseif ($max_dim <= 1920) {
            $quality = 65;
        } else {
            $quality = 60;
        }

        ob_start();
        switch ($mime) {
            case 'image/jpeg':
            case 'image/jpg':
                imageinterlace($img, true);
                imagejpeg($img, null, $quality);
                break;
            case 'image/png':
                $png_quality = (int) ((100 - $quality) / 10); // 0–9
                imagepng($img, null, $png_quality);
                break;
            case 'image/gif':
                imagegif($img);
                break;
            case 'image/webp':
                if (function_exists('imagewebp')) {
                    imagewebp($img, null, $quality);
                } else {
                    return false;
                }
                break;
        }
        $data = ob_get_clean();
        imagedestroy($img);
        return $data;
    } catch (Exception $e) {
        return false;
    }
}

// NOTE (2026.1.29): the legacy cancel_order() helper was removed. It wrote the
// misspelled enum value 'canceled', which the 2026.1.26 schema change dropped
// from orders.status — every call silently stored an empty status. All
// cancellation now goes through process_order_cancellation() (see below),
// which owns the gateway void, the gift-card expiry and the cancellation
// bookkeeping columns in one place.

// ---------------------------------------------------------------------------
// Parasut API V4 helpers
// ---------------------------------------------------------------------------

/**
 * Make a cURL request to the Parasut API.
 *
 * @param string $method  GET | POST | PUT | PATCH | DELETE
 * @param string $url     Full URL
 * @param array  $body    Associative array (will be JSON-encoded) or null
 * @param string $token   Bearer token (omit for OAuth token endpoint)
 * @return array ['http_code' => int, 'body' => mixed]
 */
function _parasut_request($method, $url, $body = null, $token = null)
{
    $ch = curl_init($url);
    // Identify this installation on outgoing requests. Sent with no
    // User-Agent, a request looks like an anonymous client to the receiving
    // server's firewall and gets rejected — which is how Pinegrap ended up
    // blocking its own licence and update checks.
    curl_setopt($ch, CURLOPT_USERAGENT, function_exists('pinegrap_user_agent') ? pinegrap_user_agent() : 'Pinegrap');
    $headers = ['Accept: application/json'];

    if ($token) {
        $headers[] = 'Authorization: Bearer ' . $token;
    }

    if ($body !== null) {
        $json = json_encode($body);
        $headers[] = 'Content-Type: application/json';
        $headers[] = 'Content-Length: ' . strlen($json);
        curl_setopt($ch, CURLOPT_POSTFIELDS, $json);
    }

    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CUSTOMREQUEST => $method,
        CURLOPT_HTTPHEADER => $headers,
        CURLOPT_TIMEOUT => 30,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);

    $response = curl_exec($ch);
    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $curl_error = curl_error($ch);
    curl_close($ch);

    if ($curl_error) {
        return ['http_code' => 0, 'body' => null, 'curl_error' => $curl_error];
    }

    return ['http_code' => $http_code, 'body' => json_decode($response, true)];
}

/**
 * Return the Parasut API base URL (production or sandbox).
 */
function _parasut_base()
{
    if (defined('PARASUT_USE_SANDBOX') && PARASUT_USE_SANDBOX) {
        return 'https://api.heroku-staging.parasut.com';
    }
    return PARASUT_API_BASE;
}

/**
 * Return the company-scoped API prefix.
 */
function _parasut_prefix()
{
    return _parasut_base() . '/v4/' . PARASUT_COMPANY_ID;
}

/**
 * Extract a readable error message from a Parasut API response.
 */
function _parasut_extract_error($result)
{
    if (isset($result['curl_error'])) {
        return $result['curl_error'];
    }
    $body = $result['body'] ?? [];
    if (!empty($body['errors'])) {
        $msgs = [];
        foreach ((array) $body['errors'] as $err) {
            $msgs[] = ($err['title'] ?? '') . ': ' . ($err['detail'] ?? '');
        }
        return implode(' | ', $msgs);
    }
    if (!empty($body['error_description'])) {
        return $body['error_description'];
    }
    return 'HTTP ' . ($result['http_code'] ?? '?');
}

/**
 * Get a valid OAuth2 access token, using a file cache to avoid repeated logins.
 *
 * @return array ['success' => bool, 'token' => string|null, 'error' => string]
 */
function parasut_get_token()
{
    // Load cached token if it is still valid (keep 60-second buffer before expiry).
    if (file_exists(PARASUT_TOKEN_CACHE)) {
        $cache = json_decode(file_get_contents(PARASUT_TOKEN_CACHE), true);
        if (!empty($cache['access_token']) && !empty($cache['expires_at'])) {
            if (time() < ($cache['expires_at'] - 60)) {
                return ['success' => true, 'token' => $cache['access_token'], 'error' => ''];
            }
        }
    }

    // Request a new token.
    // Client credentials are sent via HTTP Basic Auth (RFC 6749 §2.3.1).
    // User credentials are sent in the form-encoded POST body.
    $body = [
        'grant_type' => 'password',
        'username' => PARASUT_USERNAME,
        'password' => PARASUT_PASSWORD,
        'redirect_uri' => 'urn:ietf:wg:oauth:2.0:oob',
    ];

    $url = _parasut_base() . '/oauth/token';
    $ch = curl_init($url);
    // Identify this installation on outgoing requests. Sent with no
    // User-Agent, a request looks like an anonymous client to the receiving
    // server's firewall and gets rejected — which is how Pinegrap ended up
    // blocking its own licence and update checks.
    curl_setopt($ch, CURLOPT_USERAGENT, function_exists('pinegrap_user_agent') ? pinegrap_user_agent() : 'Pinegrap');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => http_build_query($body),
        CURLOPT_USERPWD => PARASUT_CLIENT_ID . ':' . PARASUT_CLIENT_SECRET,
        CURLOPT_HTTPHEADER => ['Content-Type: application/x-www-form-urlencoded'],
        CURLOPT_TIMEOUT => 30,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $response = curl_exec($ch);
    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $curl_err = curl_error($ch);
    curl_close($ch);

    if ($curl_err) {
        return ['success' => false, 'token' => null, 'error' => 'cURL error: ' . $curl_err];
    }

    $data = json_decode($response, true);

    if ($http_code !== 200 || empty($data['access_token'])) {
        $msg = isset($data['error_description']) ? $data['error_description'] : 'HTTP ' . $http_code;
        return ['success' => false, 'token' => null, 'error' => 'Parasut token error: ' . $msg];
    }

    // Cache the token.
    $cache = [
        'access_token' => $data['access_token'],
        'refresh_token' => $data['refresh_token'] ?? '',
        'expires_at' => time() + (int) ($data['expires_in'] ?? 7200),
    ];
    file_put_contents(PARASUT_TOKEN_CACHE, json_encode($cache));

    return ['success' => true, 'token' => $data['access_token'], 'error' => ''];
}

/**
 * Find or create a Parasut contact for the given order row.
 * Stores the Parasut contact ID back to orders.parasut_contact_id.
 *
/**
 * Ensure a Pinegrap product exists in Parasut and return its Parasut ID.
 * Creates the product in Parasut on first call and persists the ID to the DB.
 *
 * @param int    $product_id  Pinegrap products.id
 * @param string $token       Valid Parasut OAuth token
 * @return array ['success' => bool, 'parasut_product_id' => string|null, 'error' => string]
 */
/**
 * Return the company's first Parasut stock location ID.
 * Fetches from the API once and caches it in config.parasut_default_warehouse_id.
 *
 * @param string $token  Valid Parasut OAuth token
 * @return array ['success' => bool, 'warehouse_id' => string|null, 'error' => string]
 */
function parasut_ensure_default_warehouse($token)
{
    if (defined('PARASUT_DEFAULT_WAREHOUSE_ID') && PARASUT_DEFAULT_WAREHOUSE_ID !== '') {
        return ['success' => true, 'warehouse_id' => PARASUT_DEFAULT_WAREHOUSE_ID, 'error' => ''];
    }

    $result = _parasut_request('GET', _parasut_prefix() . '/warehouses?page[size]=1', null, $token);

    if ($result['http_code'] !== 200 || empty($result['body']['data'])) {
        return ['success' => false, 'warehouse_id' => null, 'error' => 'Could not fetch stock locations: ' . _parasut_extract_error($result)];
    }

    $warehouse_id = (string) $result['body']['data'][0]['id'];
    db("UPDATE config SET parasut_default_warehouse_id = '" . escape($warehouse_id) . "'");

    return ['success' => true, 'warehouse_id' => $warehouse_id, 'error' => ''];
}

function parasut_sync_product($product_id, $token)
{
    // Fetch product details (needed for both new creation and track_stock flag).
    $result = mysqli_query(db::$con, "SELECT name, short_description, price, inventory, inventory_quantity, parasut_product_id FROM products WHERE id = '" . escape($product_id) . "' LIMIT 1");
    $product = mysqli_fetch_assoc($result);
    if (!$product) {
        return ['success' => false, 'parasut_product_id' => null, 'track_stock' => false, 'error' => 'Product not found: ' . $product_id];
    }

    $track_stock = !empty($product['inventory']);

    // Already synced — return cached ID.
    if ($product['parasut_product_id']) {
        return ['success' => true, 'parasut_product_id' => $product['parasut_product_id'], 'track_stock' => $track_stock, 'error' => ''];
    }

    $product_name = $product['short_description'] ?: ($product['name'] ?: lang('No Product Name'));
    $unit_price = round($product['price'] / 100, 2);

    $attributes = [
        'name' => $product_name,
        'unit_price' => $unit_price,
        'currency' => 'TRL',
        'vat_rate' => 0,
        'product_type' => $track_stock ? 'physical' : 'service',
        'inventory_tracking' => $track_stock,
    ];
    if ($track_stock) {
        // Set initial stock count so the product has an inventory level from the start.
        $attributes['initial_stock_count'] = max(0, (int) $product['inventory_quantity']);
    }

    $body = [
        'data' => [
            'type' => 'products',
            'attributes' => $attributes,
        ],
    ];

    $api_result = _parasut_request('POST', _parasut_prefix() . '/products', $body, $token);

    if (!in_array($api_result['http_code'], [200, 201]) || empty($api_result['body']['data']['id'])) {
        return ['success' => false, 'parasut_product_id' => null, 'track_stock' => $track_stock, 'error' => _parasut_extract_error($api_result)];
    }

    $parasut_product_id = (string) $api_result['body']['data']['id'];
    db("UPDATE products SET parasut_product_id = '" . escape($parasut_product_id) . "' WHERE id = '" . escape($product_id) . "'");

    // For stock-tracked products, create an inventory level in the default warehouse
    // so the product has a stock entry and can appear in shipment documents.
    if ($track_stock) {
        $wh = parasut_ensure_default_warehouse($token);
        if ($wh['success']) {
            $initial_qty = max(0, (int) $product['inventory_quantity']);
            $inv_body = [
                'data' => [
                    'type' => 'stock_updates',
                    'attributes' => [
                        'quantity' => $initial_qty > 0 ? $initial_qty : 1,
                    ],
                    'relationships' => [
                        'product' => ['data' => ['type' => 'products', 'id' => $parasut_product_id]],
                        'warehouse' => ['data' => ['type' => 'warehouses', 'id' => $wh['warehouse_id']]],
                    ],
                ],
            ];
            $inv_result = _parasut_request('POST', _parasut_prefix() . '/stock_updates', $inv_body, $token);
            error_log('PARASUT_INV_LEVEL http=' . $inv_result['http_code'] . ' body=' . json_encode($inv_result['body']));
        }
    }

    return ['success' => true, 'parasut_product_id' => $parasut_product_id, 'track_stock' => $track_stock, 'error' => ''];
}

/**
 * Ensure an existing Parasut product has inventory tracking enabled (physical + inventory_tracking=true)
 * AND has at least $needed_qty available stock at the given warehouse.
 *
 * Paraşüt's documented way to add stock to an existing product via API is to create an inflow
 * shipment_document (a "Yeni Gelen İrsaliye" / incoming stock entry). The `/stock_updates` endpoint
 * only works on products that already have stock movements — it cannot seed stock from zero, and
 * returns "Güncellenen stok miktarı bulunamadı" when there is nothing to update.
 *
 * @param string      $parasut_product_id
 * @param int         $needed_qty        Minimum stock that must be present for the upcoming outflow.
 * @param string|null $seed_contact_id   Paraşüt contact id to attribute the inflow document to.
 * @param string|null $warehouse_id      Warehouse to credit the stock to.
 * @param string      $token
 * @return array ['success' => bool, 'current_stock' => float, 'error' => string]
 */
function parasut_ensure_product_stock_tracking($parasut_product_id, $needed_qty, $seed_contact_id, $warehouse_id, $token)
{
    // 1) Fetch current product state.
    $get = _parasut_request('GET', _parasut_prefix() . '/products/' . urlencode($parasut_product_id), null, $token);
    if ($get['http_code'] !== 200 || empty($get['body']['data'])) {
        return ['success' => false, 'current_stock' => 0, 'error' => 'Product fetch failed: ' . _parasut_extract_error($get)];
    }
    $attrs = $get['body']['data']['attributes'] ?? [];
    $is_tracked = !empty($attrs['inventory_tracking']) && (($attrs['product_type'] ?? '') === 'physical');
    $current_stock = (float) ($attrs['stock_count'] ?? 0);

    // 2) Enable inventory tracking if it's off (was originally created as 'service').
    if (!$is_tracked) {
        $patch_body = [
            'data' => [
                'id' => (string) $parasut_product_id,
                'type' => 'products',
                'attributes' => [
                    'product_type' => 'physical',
                    'inventory_tracking' => true,
                ],
            ],
        ];
        $patch = _parasut_request('PUT', _parasut_prefix() . '/products/' . urlencode($parasut_product_id), $patch_body, $token);
        error_log('PARASUT_PROD_PATCH http=' . $patch['http_code'] . ' response=' . json_encode($patch['body']));
        if (!in_array($patch['http_code'], [200, 201])) {
            return ['success' => false, 'current_stock' => 0, 'error' => 'Product patch failed: ' . _parasut_extract_error($patch)];
        }
        $current_stock = 0; // freshly enabled — no stock yet.
    }

    // If the product already has stock movements (e.g. from sales_invoices), Paraşüt allows
    // negative stock outflow — no seeding needed. Skip the seed in that case so the main
    // shipment POST runs and its schema probes can fire.
    $has_movements = !empty($attrs['has_stock_movements']);
    if ($has_movements) {
        return ['success' => true, 'current_stock' => $current_stock, 'error' => ''];
    }

    // 3) If stock is insufficient for the outgoing shipment, seed it via an inflow shipment_document.
    if ($current_stock < $needed_qty && $seed_contact_id && $warehouse_id) {
        $seed_qty = max(1, (int) ceil($needed_qty - $current_stock));
        $seed_body = [
            'data' => [
                'type' => 'shipment_documents',
                'attributes' => [
                    'description' => 'Açılış stok girişi (Pinegrap sync)',
                    'issue_date' => date('Y-m-d'),
                    // inflow: true = incoming shipment / stock entry.
                    'inflow' => true,
                ],
                'relationships' => [
                    'contact' => [
                        'data' => ['type' => 'contacts', 'id' => (string) $seed_contact_id],
                    ],
                    'details' => [
                        'data' => [
                            [
                                'type' => 'shipment_document_details',
                                'attributes' => [
                                    'quantity' => $seed_qty,
                                    'unit' => 'Adet',
                                    'description' => 'Açılış stok',
                                ],
                                'relationships' => [
                                    'product' => ['data' => ['type' => 'products', 'id' => (string) $parasut_product_id]],
                                    'warehouse' => ['data' => ['type' => 'warehouses', 'id' => (string) $warehouse_id]],
                                ],
                            ]
                        ],
                    ],
                ],
            ],
        ];
        $seed = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $seed_body, $token);
        error_log('PARASUT_STOCK_SEED http=' . $seed['http_code'] . ' qty=' . $seed_qty . ' response=' . json_encode($seed['body']));
        if (!in_array($seed['http_code'], [200, 201])) {
            return [
                'success' => false,
                'current_stock' => $current_stock,
                'error' => 'Stock seeding (inflow) failed: ' . _parasut_extract_error($seed),
            ];
        }
        $current_stock += $seed_qty;
    }

    return ['success' => true, 'current_stock' => $current_stock, 'error' => ''];
}

/**
 * @param array $order Full order row from DB (billing_* fields, contact_id, id)
 * @return array ['success' => bool, 'parasut_contact_id' => string|null, 'error' => string]
 */
function parasut_sync_contact($order)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'parasut_contact_id' => null, 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    // If we already linked a Parasut contact to this order, reuse it.
    if (!empty($order['parasut_contact_id'])) {
        return ['success' => true, 'parasut_contact_id' => $order['parasut_contact_id'], 'error' => ''];
    }

    // Determine name and contact type.
    $billing_company = trim($order['billing_company'] ?? '');
    $billing_first = trim($order['billing_first_name'] ?? '');
    $billing_last = trim($order['billing_last_name'] ?? '');

    if ($billing_company !== '') {
        $contact_type = 'company';
        $name = $billing_company;
    } else {
        $contact_type = 'person';
        $name = trim($billing_first . ' ' . $billing_last);
    }

    // Identification number (TC / VKN).
    $id_number = '';
    if (defined('PARASUT_TC_IN_FIELD') && PARASUT_TC_IN_FIELD !== 'do not use') {
        $field = PARASUT_TC_IN_FIELD; // 'custom_field_1', 'custom_field_2', or 'tax_number'
        $id_number = trim($order[$field] ?? '');
    }

    $attributes = [
        'account_type' => 'customer',
        'contact_type' => $contact_type,
        'name' => $name,
        'email' => $order['billing_email_address'] ?? '',
        'phone' => $order['billing_phone_number'] ?? '',
    ];

    if ($id_number !== '') {
        // VKN for companies, TCKN for persons.
        if ($contact_type === 'company') {
            $attributes['tax_number'] = $id_number;
        } else {
            $attributes['tckn'] = $id_number;
        }
    }

    // Build address string.
    $addr_parts = array_filter([
        $order['billing_address_1'] ?? '',
        $order['billing_address_2'] ?? '',
        $order['billing_city'] ?? '',
        $order['billing_state'] ?? '',
        $order['billing_zip_code'] ?? '',
        $order['billing_country'] ?? '',
    ]);
    if ($addr_parts) {
        $attributes['address'] = implode(', ', $addr_parts);
    }

    $body = [
        'data' => [
            'type' => 'contacts',
            'attributes' => $attributes,
        ],
    ];

    $result = _parasut_request('POST', _parasut_prefix() . '/contacts', $body, $token);

    if (!in_array($result['http_code'], [200, 201]) || empty($result['body']['data']['id'])) {
        $msg = _parasut_extract_error($result);
        return ['success' => false, 'parasut_contact_id' => null, 'error' => 'Contact create failed: ' . $msg];
    }

    $parasut_contact_id = (string) $result['body']['data']['id'];

    // Persist the Parasut contact ID on the order.
    db("UPDATE orders SET parasut_contact_id = '" . escape($parasut_contact_id) . "' WHERE id = '" . escape($order['id']) . "'");

    return ['success' => true, 'parasut_contact_id' => $parasut_contact_id, 'error' => ''];
}

/**
 * Create a Parasut sales invoice for the given order and send it as
 * e-fatura (e_invoice) or e-arşiv (e_archive).
 *
 * @param int    $order_id  orders.id
 * @param string $type      'e_invoice' | 'e_archive'
 * @return array ['success' => bool, 'parasut_invoice_id' => string|null, 'error' => string]
 */
function parasut_create_invoice($order_id, $type = 'e_archive')
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'parasut_invoice_id' => null, 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    // Fetch full order.
    $query = "SELECT
                orders.*,
                contacts.company AS contact_company
              FROM orders
              LEFT JOIN contacts ON orders.contact_id = contacts.id
              WHERE orders.id = '" . escape($order_id) . "'
              LIMIT 1";
    $result = mysqli_query(db::$con, $query) or output_error('Query failed.');
    $order = mysqli_fetch_assoc($result);

    if (!$order) {
        return ['success' => false, 'parasut_invoice_id' => null, 'error' => 'Order not found.'];
    }

    // Sync (or retrieve) the Parasut contact.
    $contact_result = parasut_sync_contact($order);
    if (!$contact_result['success']) {
        return ['success' => false, 'parasut_invoice_id' => null, 'error' => $contact_result['error']];
    }
    $parasut_contact_id = $contact_result['parasut_contact_id'];

    // Fetch order items (join products to get display name and Parasut product ID).
    $items_query = "SELECT
                        order_items.product_id,
                        order_items.quantity,
                        order_items.price,
                        order_items.product_name,
                        products.short_description,
                        products.parasut_product_id
                    FROM order_items
                    LEFT JOIN products ON order_items.product_id = products.id
                    WHERE order_items.order_id = '" . escape($order_id) . "'";
    $items_result = mysqli_query(db::$con, $items_query) or output_error('Query failed.');

    $default_parasut_product_id = defined('PARASUT_DEFAULT_PRODUCT_ID') ? PARASUT_DEFAULT_PRODUCT_ID : '';

    $details = [];
    while ($item = mysqli_fetch_assoc($items_result)) {
        $item_name = $item['short_description'] ?: ($item['product_name'] ?: lang('No Product Name'));
        $unit_price = round($item['price'] / 100, 2); // Convert from cents.

        // Resolve Parasut product ID: use synced ID, auto-sync if missing, fall back to default.
        $item_parasut_product_id = $item['parasut_product_id'];
        if (!$item_parasut_product_id && $item['product_id']) {
            $sync = parasut_sync_product($item['product_id'], $token);
            $item_parasut_product_id = $sync['success'] ? $sync['parasut_product_id'] : '';
        }
        if (!$item_parasut_product_id) {
            $item_parasut_product_id = $default_parasut_product_id;
        }

        $detail = [
            'type' => 'sales_invoice_details',
            'attributes' => [
                'quantity' => max(1, (int) $item['quantity']),
                'unit_price' => $unit_price,
                'vat_rate' => 0,
                'description' => $item_name,
                'discount_type' => 'amount',
                'discount_value' => 0,
            ],
        ];
        if ($item_parasut_product_id) {
            $detail['relationships'] = [
                'product' => ['data' => ['type' => 'products', 'id' => $item_parasut_product_id]],
            ];
        }
        $details[] = $detail;
    }

    if (empty($details)) {
        // Fallback: single line with the order total.
        $detail = [
            'type' => 'sales_invoice_details',
            'attributes' => [
                'quantity' => 1,
                'unit_price' => round($order['total'] / 100, 2),
                'vat_rate' => 0,
                'description' => lang('Order') . ' #' . $order['order_number'],
                'discount_type' => 'amount',
                'discount_value' => 0,
            ],
        ];
        if ($default_parasut_product_id) {
            $detail['relationships'] = [
                'product' => ['data' => ['type' => 'products', 'id' => $default_parasut_product_id]],
            ];
        }
        $details[] = $detail;
    }

    // Guard against null/zero order_date — strtotime("0000-00-00") returns epoch.
    $ts = strtotime($order['order_date'] ?? '');
    $issue_date = ($ts && $ts > 0) ? date('Y-m-d', $ts) : date('Y-m-d');

    // Map currency code to Parasut-accepted values.
    // Parasut accepts: TRL, USD, EUR, GBP. TRY is the ISO code but Parasut uses TRL.
    $currency_map = ['TRY' => 'TRL', 'TL' => 'TRL', '' => 'TRL'];
    $raw_currency = strtoupper(trim($order['currency_code'] ?? ''));
    $currency = $currency_map[$raw_currency] ?? $raw_currency;

    $invoice_body = [
        'data' => [
            'type' => 'sales_invoices',
            'attributes' => [
                'item_type' => 'invoice',
                'description' => lang('Order') . ' #' . $order['order_number'],
                'issue_date' => $issue_date,
                'due_date' => $issue_date,
                'currency' => $currency,
            ],
            'relationships' => [
                'contact' => [
                    'data' => ['type' => 'contacts', 'id' => $parasut_contact_id],
                ],
                'details' => ['data' => $details],
            ],
        ],
    ];

    error_log('PARASUT_INV body=' . json_encode($invoice_body));
    $inv_result = _parasut_request('POST', _parasut_prefix() . '/sales_invoices', $invoice_body, $token);
    error_log('PARASUT_INV http=' . $inv_result['http_code'] . ' response=' . json_encode($inv_result['body']));

    if (!in_array($inv_result['http_code'], [200, 201]) || empty($inv_result['body']['data']['id'])) {
        $msg = _parasut_extract_error($inv_result);
        return ['success' => false, 'parasut_invoice_id' => null, 'error' => 'Invoice create failed: ' . $msg];
    }

    $sales_invoice_id = (string) $inv_result['body']['data']['id'];

    // Now issue the e-invoice or e-archive document.
    if ($type === 'e_invoice') {
        $doc_body = [
            'data' => [
                'type' => 'e_invoices',
                'attributes' => [
                    'scenario' => 'commercial',
                ],
                'relationships' => [
                    'invoice' => ['data' => ['type' => 'sales_invoices', 'id' => $sales_invoice_id]],
                ],
            ],
        ];
        $doc_result = _parasut_request('POST', _parasut_prefix() . '/e_invoices', $doc_body, $token);
    } else {
        // e_archive
        $doc_body = [
            'data' => [
                'type' => 'e_archives',
                'attributes' => [],
                'relationships' => [
                    'sales_invoice' => ['data' => ['type' => 'sales_invoices', 'id' => $sales_invoice_id]],
                ],
            ],
        ];
        $doc_result = _parasut_request('POST', _parasut_prefix() . '/e_archives', $doc_body, $token);
    }

    // Even if the e-invoice/e-archive step fails, we keep the sales invoice ID.
    if (!in_array($doc_result['http_code'], [200, 201])) {
        $msg = _parasut_extract_error($doc_result);
        // Store the sales invoice ID so user can retry the e-doc step manually.
        db("UPDATE orders SET parasut_invoice_id = '" . escape($sales_invoice_id) . "', parasut_exported = 1 WHERE id = '" . escape($order_id) . "'");
        return ['success' => false, 'parasut_invoice_id' => $sales_invoice_id, 'error' => 'Sales invoice created (ID: ' . $sales_invoice_id . ') but e-document failed: ' . $msg];
    }

    // Store the sales invoice ID on the order.
    db("UPDATE orders SET parasut_invoice_id = '" . escape($sales_invoice_id) . "', parasut_exported = 1 WHERE id = '" . escape($order_id) . "'");

    return ['success' => true, 'parasut_invoice_id' => $sales_invoice_id, 'error' => ''];
}

/**
 * Create a Parasut shipment document (e-irsaliye) for the given order.
 *
 * @param int $order_id  orders.id
 * @return array ['success' => bool, 'parasut_shipment_id' => string|null, 'error' => string]
 */
function parasut_create_shipment($order_id)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'parasut_shipment_id' => null, 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    // Fetch full order.
    $query = "SELECT orders.*
              FROM orders
              WHERE orders.id = '" . escape($order_id) . "'
              LIMIT 1";
    $result = mysqli_query(db::$con, $query) or output_error('Query failed.');
    $order = mysqli_fetch_assoc($result);

    if (!$order) {
        return ['success' => false, 'parasut_shipment_id' => null, 'error' => 'Order not found.'];
    }

    // Sync contact.
    $contact_result = parasut_sync_contact($order);
    if (!$contact_result['success']) {
        return ['success' => false, 'parasut_shipment_id' => null, 'error' => $contact_result['error']];
    }
    $parasut_contact_id = $contact_result['parasut_contact_id'];

    // Fetch order items (join products to get display name and Parasut product ID).
    $items_query = "SELECT
                        order_items.product_id,
                        order_items.quantity,
                        order_items.product_name,
                        products.short_description,
                        products.parasut_product_id,
                        products.inventory
                    FROM order_items
                    LEFT JOIN products ON order_items.product_id = products.id
                    WHERE order_items.order_id = '" . escape($order_id) . "'";
    $items_result = mysqli_query(db::$con, $items_query) or output_error('Query failed.');

    $default_parasut_product_id = defined('PARASUT_DEFAULT_PRODUCT_ID') ? PARASUT_DEFAULT_PRODUCT_ID : '';

    // Warehouse is required on every shipment_document_detail AND to seed stock for newly
    // tracked products — fetch it once up front.
    $warehouse_result = parasut_ensure_default_warehouse($token);
    $default_warehouse_id = $warehouse_result['success'] ? $warehouse_result['warehouse_id'] : '';
    if (!$default_warehouse_id) {
        return ['success' => false, 'parasut_shipment_id' => null, 'error' => 'No Parasut warehouse available: ' . ($warehouse_result['error'] ?? '')];
    }

    $details = [];
    $skipped_count = 0;
    while ($item = mysqli_fetch_assoc($items_result)) {
        // Skip non-shippable items — Paraşüt shipment_documents can only contain
        // stock-tracked (physical + inventory_tracking) products. Non-inventory items
        // (services, digital goods, etc.) are silently excluded from the e-irsaliye.
        if (empty($item['inventory'])) {
            $skipped_count++;
            continue;
        }

        $item_name = $item['short_description'] ?: ($item['product_name'] ?: lang('No Product Name'));
        $item_qty = max(1, (int) $item['quantity']);

        $item_parasut_product_id = $item['parasut_product_id'];
        if (!$item_parasut_product_id && $item['product_id']) {
            $sync = parasut_sync_product($item['product_id'], $token);
            $item_parasut_product_id = $sync['success'] ? $sync['parasut_product_id'] : '';
        }
        // Guarantee the Paraşüt product is physical + inventory_tracking=true AND has
        // enough stock. If stock is short, seed it via an inflow shipment_document
        // (the documented Paraşüt way to add stock to a product via API).
        if ($item_parasut_product_id) {
            $ensure = parasut_ensure_product_stock_tracking(
                $item_parasut_product_id,
                $item_qty,
                $parasut_contact_id,
                $default_warehouse_id,
                $token
            );
            if (!$ensure['success']) {
                return [
                    'success' => false,
                    'parasut_shipment_id' => null,
                    'error' => 'Stock preparation failed for ' . $item_name . ': ' . $ensure['error'],
                ];
            }
        }

        $detail = [
            'type' => 'shipment_document_details',
            'attributes' => [
                'quantity' => $item_qty,
                'unit' => 'Adet',
                'description' => $item_name,
            ],
            'relationships' => [
                'warehouse' => ['data' => ['type' => 'warehouses', 'id' => (string) $default_warehouse_id]],
            ],
        ];
        if ($item_parasut_product_id) {
            $detail['relationships']['product'] = ['data' => ['type' => 'products', 'id' => $item_parasut_product_id]];
        }
        $details[] = $detail;
    }

    if (empty($details)) {
        return [
            'success' => false,
            'parasut_shipment_id' => null,
            'error' => 'This order has no shippable (stock-tracked) items. E-irsaliye cannot be created.',
        ];
    }

    // Guard against null/zero order_date — strtotime("0000-00-00") returns epoch.
    $ts = strtotime($order['order_date'] ?? '');
    $issue_date = ($ts && $ts > 0) ? date('Y-m-d', $ts) : date('Y-m-d');

    $body = [
        'data' => [
            'type' => 'shipment_documents',
            'attributes' => [
                'description' => lang('Order') . ' #' . $order['order_number'],
                'issue_date' => $issue_date,
                // inflow: false = outgoing (giden irsaliye, sale/shipment to customer)
                //         true  = incoming (gelen irsaliye, purchase from supplier)
                'inflow' => false,
            ],
            'relationships' => [
                'contact' => [
                    'data' => ['type' => 'contacts', 'id' => $parasut_contact_id],
                ],
                'details' => ['data' => $details],
            ],
        ],
    ];

    error_log('PARASUT_SHIP body=' . json_encode($body));
    $result = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $body, $token);
    error_log('PARASUT_SHIP http=' . $result['http_code'] . ' response=' . json_encode($result['body']));

    if (!in_array($result['http_code'], [200, 201]) || empty($result['body']['data']['id'])) {
        // === SCHEMA PROBES =====================================================
        // Paraşüt's 422 error messages for shipment_documents are opaque. To learn
        // the acceptable schema we deliberately send invalid shapes and log what
        // Paraşüt lists as "Acceptable: ..." — this is the same trick that revealed
        // the purchase_bills supplier/contact issue earlier.
        //
        // Probe 1: invalid relationship on the document level (lists valid relationships).
        $probe1_body = $body;
        $probe1_body['data']['relationships']['xxx_probe_rel'] = ['data' => ['type' => 'xxxs', 'id' => '1']];
        $probe1 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe1_body, $token);
        error_log('PARASUT_SHIP_PROBE1 (doc-level invalid rel) http=' . $probe1['http_code'] . ' response=' . json_encode($probe1['body']));

        // Probe 2: invalid relationship inside a detail (lists valid detail relationships).
        $probe2_body = $body;
        if (!empty($probe2_body['data']['relationships']['details']['data'][0])) {
            $probe2_body['data']['relationships']['details']['data'][0]['relationships']['xxx_probe_detail_rel']
                = ['data' => ['type' => 'xxxs', 'id' => '1']];
        }
        $probe2 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe2_body, $token);
        error_log('PARASUT_SHIP_PROBE2 (detail-level invalid rel) http=' . $probe2['http_code'] . ' response=' . json_encode($probe2['body']));

        // Probe 3: invalid attribute on the document (lists valid attributes).
        $probe3_body = $body;
        $probe3_body['data']['attributes']['xxx_probe_attr'] = 'x';
        $probe3 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe3_body, $token);
        error_log('PARASUT_SHIP_PROBE3 (doc-level invalid attr) http=' . $probe3['http_code'] . ' response=' . json_encode($probe3['body']));

        // Probe 4: try the detail with `stock_location` instead of `warehouse`.
        $probe4_body = $body;
        if (!empty($probe4_body['data']['relationships']['details']['data'][0]['relationships']['warehouse'])) {
            $probe4_body['data']['relationships']['details']['data'][0]['relationships']['stock_location']
                = $probe4_body['data']['relationships']['details']['data'][0]['relationships']['warehouse'];
            unset($probe4_body['data']['relationships']['details']['data'][0]['relationships']['warehouse']);
        }
        $probe4 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe4_body, $token);
        error_log('PARASUT_SHIP_PROBE4 (stock_location instead of warehouse) http=' . $probe4['http_code'] . ' response=' . json_encode($probe4['body']));
        if (in_array($probe4['http_code'], [200, 201]) && !empty($probe4['body']['data']['id'])) {
            $shipment_id = (string) $probe4['body']['data']['id'];
            db("UPDATE orders SET parasut_shipment_id = '" . escape($shipment_id) . "' WHERE id = '" . escape($order_id) . "'");
            return ['success' => true, 'parasut_shipment_id' => $shipment_id, 'error' => ''];
        }

        // Probe 5: details as a plain array under attributes (non JSON:API, some Paraşüt endpoints do this).
        $probe5_body = $body;
        $flat_details = [];
        foreach ($probe5_body['data']['relationships']['details']['data'] as $d) {
            $flat = $d['attributes'] ?? [];
            if (!empty($d['relationships']['product']['data']['id'])) {
                $flat['product_id'] = $d['relationships']['product']['data']['id'];
            }
            if (!empty($d['relationships']['warehouse']['data']['id'])) {
                $flat['warehouse_id'] = $d['relationships']['warehouse']['data']['id'];
            }
            $flat_details[] = $flat;
        }
        $probe5_body['data']['attributes']['details'] = $flat_details;
        unset($probe5_body['data']['relationships']['details']);
        $probe5 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe5_body, $token);
        error_log('PARASUT_SHIP_PROBE5 (details as flat attr array) http=' . $probe5['http_code'] . ' response=' . json_encode($probe5['body']));
        if (in_array($probe5['http_code'], [200, 201]) && !empty($probe5['body']['data']['id'])) {
            $shipment_id = (string) $probe5['body']['data']['id'];
            db("UPDATE orders SET parasut_shipment_id = '" . escape($shipment_id) . "' WHERE id = '" . escape($order_id) . "'");
            return ['success' => true, 'parasut_shipment_id' => $shipment_id, 'error' => ''];
        }

        // Probe 6: JSON:API compound doc — details in top-level `included`, referenced by lid.
        $probe6_body = $body;
        $included = [];
        $refs = [];
        foreach ($probe6_body['data']['relationships']['details']['data'] as $i => $d) {
            $lid = 'detail-' . ($i + 1);
            $entry = $d;
            $entry['lid'] = $lid;
            $included[] = $entry;
            $refs[] = ['type' => 'shipment_document_details', 'lid' => $lid];
        }
        $probe6_body['data']['relationships']['details']['data'] = $refs;
        $probe6_body['included'] = $included;
        $probe6 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe6_body, $token);
        error_log('PARASUT_SHIP_PROBE6 (details in top-level included with lid) http=' . $probe6['http_code'] . ' response=' . json_encode($probe6['body']));
        if (in_array($probe6['http_code'], [200, 201]) && !empty($probe6['body']['data']['id'])) {
            $shipment_id = (string) $probe6['body']['data']['id'];
            db("UPDATE orders SET parasut_shipment_id = '" . escape($shipment_id) . "' WHERE id = '" . escape($order_id) . "'");
            return ['success' => true, 'parasut_shipment_id' => $shipment_id, 'error' => ''];
        }

        // Probe 7: totally different JSON:API type — maybe `delivery_note_details` or bare `details`.
        $probe7_body = $body;
        foreach ($probe7_body['data']['relationships']['details']['data'] as &$dref) {
            $dref['type'] = 'delivery_note_details';
        }
        unset($dref);
        $probe7 = _parasut_request('POST', _parasut_prefix() . '/shipment_documents', $probe7_body, $token);
        error_log('PARASUT_SHIP_PROBE7 (type=delivery_note_details) http=' . $probe7['http_code'] . ' response=' . json_encode($probe7['body']));
        if (in_array($probe7['http_code'], [200, 201]) && !empty($probe7['body']['data']['id'])) {
            $shipment_id = (string) $probe7['body']['data']['id'];
            db("UPDATE orders SET parasut_shipment_id = '" . escape($shipment_id) . "' WHERE id = '" . escape($order_id) . "'");
            return ['success' => true, 'parasut_shipment_id' => $shipment_id, 'error' => ''];
        }

        // Probe 8: GET a known-good shipment_document (if any) via list, to see the exact schema Paraşüt returns.
        $list = _parasut_request('GET', _parasut_prefix() . '/shipment_documents?include=details&page[size]=1', null, $token);
        error_log('PARASUT_SHIP_PROBE8 (GET list schema) http=' . $list['http_code'] . ' response=' . json_encode($list['body']));
        // === END PROBES ========================================================

        $msg = _parasut_extract_error($result);
        return ['success' => false, 'parasut_shipment_id' => null, 'error' => 'Shipment create failed: ' . $msg];
    }

    $shipment_id = (string) $result['body']['data']['id'];

    db("UPDATE orders SET parasut_shipment_id = '" . escape($shipment_id) . "' WHERE id = '" . escape($order_id) . "'");

    return ['success' => true, 'parasut_shipment_id' => $shipment_id, 'error' => ''];
}

/**
 * Check if a VKN/TCKN is registered for e-invoice in the GİB system.
 *
 * @param string $vkn  Tax/identity number to look up
 * @return array ['success' => bool, 'data' => array|null, 'error' => string]
 */
function parasut_check_einvoice_address($vkn)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'data' => null, 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    $url = _parasut_prefix() . '/e_invoice_inboxes?filter[vkn]=' . urlencode($vkn);
    $result = _parasut_request('GET', $url, null, $token);

    if ($result['http_code'] !== 200) {
        return ['success' => false, 'data' => null, 'error' => _parasut_extract_error($result)];
    }

    $items = $result['body']['data'] ?? [];
    return ['success' => true, 'data' => $items, 'error' => ''];
}

/**
 * List all e-invoice inboxes (registered VKN/address pairs) for the company.
 *
 * @param array $filters  Optional: ['vkn' => '...']
 * @param int   $page     Page number (1-based)
 * @param int   $per_page Items per page
 * @return array ['success' => bool, 'data' => array, 'meta' => array, 'error' => string]
 */
function parasut_list_einvoice_inboxes($filters = [], $page = 1, $per_page = 25)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'data' => [], 'meta' => [], 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    $params = [
        'page[number]' => $page,
        'page[size]' => $per_page,
    ];
    if (!empty($filters['vkn'])) {
        $params['filter[vkn]'] = $filters['vkn'];
    }

    $url = _parasut_prefix() . '/e_invoice_inboxes?' . http_build_query($params);
    $result = _parasut_request('GET', $url, null, $token);

    if ($result['http_code'] !== 200) {
        return ['success' => false, 'data' => [], 'meta' => [], 'error' => _parasut_extract_error($result)];
    }

    return [
        'success' => true,
        'data' => $result['body']['data'] ?? [],
        'meta' => $result['body']['meta'] ?? [],
        'error' => '',
    ];
}

/**
 * List purchase bills (incoming invoices) from Parasut.
 *
 * @param array $filters  Optional: ['start_date' => 'Y-m-d', 'end_date' => 'Y-m-d', 'contact_id' => '...', 'item_type' => '...']
 * @param int   $page
 * @param int   $per_page
 * @return array ['success' => bool, 'data' => array, 'included' => array, 'meta' => array, 'error' => string]
 */
function parasut_list_purchase_bills($filters = [], $page = 1, $per_page = 25)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'data' => [], 'included' => [], 'meta' => [], 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    $params = [
        'page[number]' => $page,
        'page[size]' => $per_page,
        'sort' => '-issue_date',
        'include' => 'supplier',
    ];
    if (!empty($filters['start_date'])) {
        $params['filter[issue_date][gte]'] = $filters['start_date'];
    }
    if (!empty($filters['end_date'])) {
        $params['filter[issue_date][lte]'] = $filters['end_date'];
    }
    if (!empty($filters['contact_id'])) {
        $params['filter[supplier_id]'] = $filters['contact_id'];
    }
    if (!empty($filters['item_type'])) {
        $params['filter[item_type]'] = $filters['item_type'];
    }

    $url = _parasut_prefix() . '/purchase_bills?' . http_build_query($params);
    $result = _parasut_request('GET', $url, null, $token);

    if ($result['http_code'] !== 200) {
        return ['success' => false, 'data' => [], 'included' => [], 'meta' => [], 'error' => _parasut_extract_error($result)];
    }

    // Build a lookup map for included contacts (id => name).
    $included_contacts = [];
    foreach (($result['body']['included'] ?? []) as $inc) {
        if ($inc['type'] === 'contacts') {
            $included_contacts[$inc['id']] = $inc['attributes']['name'] ?? '';
        }
    }

    return [
        'success' => true,
        'data' => $result['body']['data'] ?? [],
        'contacts' => $included_contacts,
        'meta' => $result['body']['meta'] ?? [],
        'error' => '',
    ];
}

/**
 * Get a single purchase bill with full details.
 *
 * @param string $bill_id  Parasut purchase bill ID
 * @return array ['success' => bool, 'data' => array|null, 'error' => string]
 */
function parasut_get_purchase_bill($bill_id)
{
    $token_result = parasut_get_token();
    if (!$token_result['success']) {
        return ['success' => false, 'data' => null, 'error' => $token_result['error']];
    }
    $token = $token_result['token'];

    $url = _parasut_prefix() . '/purchase_bills/' . urlencode($bill_id) . '?include=supplier,details';
    $result = _parasut_request('GET', $url, null, $token);

    if ($result['http_code'] !== 200) {
        return ['success' => false, 'data' => null, 'error' => _parasut_extract_error($result)];
    }

    $data = $result['body']['data'] ?? null;
    $included = $result['body']['included'] ?? [];

    // Attach contact name.
    $contact_name = '';
    $contact_id = $data['relationships']['supplier']['data']['id'] ?? ($data['relationships']['contact']['data']['id'] ?? null);
    if ($contact_id) {
        foreach ($included as $inc) {
            if ($inc['type'] === 'contacts' && $inc['id'] === $contact_id) {
                $contact_name = $inc['attributes']['name'] ?? '';
                break;
            }
        }
    }

    // Attach line items.
    $details = [];
    foreach ($included as $inc) {
        if ($inc['type'] === 'purchase_bill_details') {
            $details[] = $inc['attributes'];
        }
    }

    return [
        'success' => true,
        'data' => $data,
        'contact_name' => $contact_name,
        'details' => $details,
        'error' => '',
    ];
}

