/**
 * Checks if the sitemap content has changed and securely pings IndexNow if necessary.
 * This unifies the sitemap check logic safely on the backend.
 *
 * @return bool True if sitemap hashed content changed and ping fired/attempted, false otherwise.
 */
function update_sitemap_and_ping()
{
    // Record that a check is being performed now. (We do it securely at the start to block recursion on failures).
    $query = "UPDATE config SET last_sitemap_check_timestamp = UNIX_TIMESTAMP()";
    mysqli_query(db::$con, $query);

    require_once(dirname(__FILE__) . '/get_sitemap_info.php');
    $sitemap_info = get_sitemap_info();

    if ($sitemap_info['urls_exist'] === true) {

        $sitemap_check_hash = md5($sitemap_info['content']);

        if ($sitemap_check_hash != LAST_SITEMAP_CHECK_HASH) {

            $sitemap_url = URL_SCHEME . HOSTNAME_SETTING . PATH . 'sitemap.xml';

            if (defined('INDEXNOW_KEY') && !empty(INDEXNOW_KEY)) {
                $indexnow_url = 'https://api.indexnow.org/indexnow';
                $post_data = json_encode([
                    "host" => HOSTNAME_SETTING,
                    "key" => INDEXNOW_KEY,
                    "urlList" => [$sitemap_url]
                ]);

                $ch = curl_init($indexnow_url);
                // Identify this installation on outgoing requests. Sent with no
                // User-Agent, a request looks like an anonymous client to the receiving
                // server's firewall and gets rejected — which is how Pinegrap ended up
                // blocking its own licence and update checks.
                curl_setopt($ch, CURLOPT_USERAGENT, function_exists('pinegrap_user_agent') ? pinegrap_user_agent() : 'Pinegrap');
                curl_setopt($ch, CURLOPT_POST, true);
                curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);
                curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 8);
                curl_setopt($ch, CURLOPT_TIMEOUT, 10);

                $response = curl_exec($ch);

                if ($response === false) {
                    log_activity(lang('IndexNow ping failed: ') . curl_error($ch), '');
                } else {
                    log_activity(lang('IndexNow ping sent successfully.'), '');
                }

                curl_close($ch);
            } else {
                log_activity(lang('IndexNow skipped: INDEXNOW_KEY not defined or empty.'), '');
            }

            log_activity(lang('daily sitemap.xml check detected updated sitemap.xml'), '');

            $query = "UPDATE config SET last_sitemap_check_hash = '" . escape($sitemap_check_hash) . "'";
            mysqli_query(db::$con, $query);

            return true;
        }
    }

    return false;
}

// ----------------------------------------------------------------------------
// Performance monitor
// ----------------------------------------------------------------------------
// Records per-request metrics (duration, peak memory, CPU) into perf_log,
// after the response has been flushed to the client. Intended cost on the
// request path: a getrusage() call at start + one INSERT during shutdown.
//
// Behavior is governed by optional config.php constants — if undefined, sane
// defaults apply, so the system works out of the box once the migration runs.
//
//   PERF_MONITOR                 — enable/disable (default: true)
//   PERF_MONITOR_SAMPLE_RATE     — 1..100 percent of requests recorded (default: 100)
//   PERF_MONITOR_RETENTION_DAYS  — rows older than this are pruned (default: 30)
//   PERF_MONITOR_MIN_DURATION_MS — only log requests slower than this (default: 0)

/**
 * Verify a downloaded payload really is a ZIP archive.
 *
 * A download can "succeed" and still not be an archive: the far end may have
 * returned a 403 from its own firewall, a 404 page, or a proxy error, and all
 * of those arrive as a perfectly valid HTTP body. Writing that to disk under a
 * .zip name and handing it to ZipArchive produces a confusing failure several
 * steps later, pointing at the wrong subsystem.
 *
 * Checks the local file header signature. Empty archives use PK\x05\x06 and
 * spanned ones PK\x07\x08; all three are accepted.
 */
/**
 * Apply TLS verification to a cURL handle used for code or licence traffic.
 *
 * These paths were pinned to CURLOPT_SSL_VERIFYPEER = 0, which disables
 * certificate validation entirely. CURLOPT_SSL_VERIFYHOST = 2 sat next to it
 * and did nothing useful: with no chain validation there is no verified
 * certificate whose hostname could be checked.
 *
 * On an update channel that matters more than anywhere else. Anyone able to
 * sit between this server and the update server — poisoned DNS, a hostile
 * network, a compromised upstream — could serve their own archive, and it
 * would be unpacked straight into the web root and executed. The update
 * mechanism becomes the delivery mechanism.
 *
 * Deliberately does NOT retry without verification when it fails. A silent
 * downgrade is worse than no verification at all, because an attacker only has
 * to break the first attempt to get the insecure second one. Turning it off is
 * an explicit, documented decision the operator makes in config.php.
 */
function pg_curl_tls($ch)
{
    curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 1);
    curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 2);

    // Servers whose CA bundle is not on the default search path can point at
    // one instead of giving up verification.
    if (defined('CURL_CA_BUNDLE') && CURL_CA_BUNDLE !== '' && is_file(CURL_CA_BUNDLE)) {
        curl_setopt($ch, CURLOPT_CAINFO, CURL_CA_BUNDLE);
    }

    // Last resort for a host with no usable CA store at all.
    if (defined('ALLOW_INSECURE_UPDATE_TLS') && ALLOW_INSECURE_UPDATE_TLS === true) {
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0);
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
    }
}

/**
 * Turn a certificate-related cURL error number into an actionable sentence.
 *
 * Without this the operator sees "cURL error 60" and has no idea that the
 * cause is a stale CA bundle on their own server rather than a fault at the
 * other end.
 */
function pg_curl_tls_hint($errno)
{
    $errno = (int) $errno;

    // 60 CURLE_PEER_FAILED_VERIFICATION, 77 CURLE_SSL_CACERT_BADFILE,
    // 35 CURLE_SSL_CONNECT_ERROR.
    if ($errno !== 60 && $errno !== 77 && $errno !== 35) {
        return '';
    }

    return ' The certificate could not be verified. This server is most likely'
        . ' missing an up-to-date CA bundle. Point CURL_CA_BUNDLE at a cacert.pem'
        . ' in data/config.php, or as a last resort set'
        . ' ALLOW_INSECURE_UPDATE_TLS to true there.';
}

/**
 * SQL expression that folds every name for the home page into one group.
 *
 * The home page is not a fixed page. Any page can carry page_home = 'yes',
 * more than one can carry it at a time, and get_page.php picks between them
 * with ORDER BY RAND() — so the site root can serve a different page on each
 * request, by design.
 *
 * Visitor tracking stores whatever the visitor asked for, so the same page is
 * recorded under two different names: an empty landing_page_name when someone
 * opened the site root, and its own name when someone opened it directly or
 * followed a link to it. Reports then showed the same page twice, splitting
 * its traffic and pushing it down the ranking.
 *
 * Read from the database on every call rather than cached in config, because
 * the operator can change which page is home at any time and a stale answer
 * would merge the wrong rows — a subtler wrong than not merging at all.
 *
 * Returns an expression to GROUP BY, mapping every home alias to ''.
 */
function pg_home_page_group_expression($column = 'landing_page_name')
{
    static $expression = null;

    if ($expression !== null) {
        return str_replace('landing_page_name', $column, $expression);
    }

    $names = array();
    $result = @mysqli_query(db::$con, "SELECT page_name FROM page WHERE page_home = 'yes'");

    if ($result) {
        while ($row = @mysqli_fetch_assoc($result)) {
            if (trim($row['page_name']) !== '') {
                $names[] = "'" . escape(trim($row['page_name'])) . "'";
            }
        }
    }

    // Always-present aliases for the root, whatever the home page happens to
    // be. 'example.com/' is a legacy value some installs recorded.
    $aliases = array("''", "'/'", "'index.php'", "'example.com/'");
    $all = array_merge($aliases, $names);

    $expression = "CASE WHEN landing_page_name IN (" . implode(', ', $all) . ") THEN '' ELSE landing_page_name END";

    return str_replace('landing_page_name', $column, $expression);
}

/**
 * Resolve a site URL to a file on disk, or '' if it is not one of ours.
 *
 * Two roots, because a Pinegrap URL can mean two different places:
 * uploaded files are served from the site root but physically live in
 * data/files, while software assets sit where their URL says they do.
 */
function pg_asset_path($url)
{
    // Anything with a host is somebody else's server.
    if (preg_match('#^(?:[a-z][a-z0-9+.-]*:)?//#i', $url) || strpos($url, 'data:') === 0) {
        return '';
    }

    $path = $url;

    // Strip the install path so "/sub/styles.css" becomes "styles.css".
    if (defined('PATH') && PATH !== '' && PATH !== '/' && strpos($path, PATH) === 0) {
        $path = substr($path, strlen(PATH));
    }

    $path = ltrim($path, '/');

    if ($path === '' || strpos($path, '..') !== false) {
        return '';
    }

    $path = rawurldecode($path);

    // Uploaded files first: that is where a designer's own assets live.
    $candidate = FILE_DIRECTORY_PATH . '/' . $path;

    if (is_file($candidate)) {
        return $candidate;
    }

    // Then the web root, for software assets and anything dropped in by hand.
    $candidate = dirname(dirname(__FILE__)) . '/' . $path;

    if (is_file($candidate)) {
        return $candidate;
    }

    return '';
}

/**
 * Append ?v=<last modified> to local asset URLs, at output time.
 *
 * The version never enters the stored markup. A designer writes
 * src="{path}avatar-1.png" and that is what stays in the database; the query
 * string is added to the response on its way out, so editing the file changes
 * the URL the browser sees without anyone editing the page.
 *
 * This is the only thing that reliably invalidates a CDN. A browser can be
 * told to reload, but Cloudflare caches .css, .js and images by default and
 * neither Ctrl+F5 nor DevTools "disable cache" reaches it — those bypass the
 * browser and the request still lands on the edge, which answers from its own
 * copy. Changing the URL changes the cache key, so there is nothing to purge.
 *
 * Matching is by FILE EXTENSION, not by tag. Rewriting every href would
 * rewrite page links too, and appending a version to /urun/xyz would be a
 * visible bug on every link in the site. An extension list cannot do that:
 * ordinary page URLs do not end in .css or .png.
 *
 * URLs that already carry a query string are left alone — an explicit ?v= is
 * someone's deliberate choice and overriding it would be rude.
 */
function pg_version_assets($html)
{
    if (!is_string($html) || $html === '') {
        return $html;
    }

    return preg_replace_callback(
        '#\b(src|href)(\s*=\s*)(["\'])([^"\'>]+?\.(?:css|js|mjs|png|jpe?g|gif|svg|webp|avif|ico|bmp|woff2?|ttf|otf|eot|mp4|webm|ogg|mp3))(\3)#i',
        'pg_version_assets_callback',
        $html
    );
}

function pg_version_assets_callback($match)
{
    static $versions = array();

    $url = $match[4];

    // Already versioned, or carrying its own parameters.
    if (strpos($url, '?') !== false) {
        return $match[0];
    }

    if (!array_key_exists($url, $versions)) {
        $file = pg_asset_path($url);
        $versions[$url] = $file !== '' ? @filemtime($file) : false;
    }

    if (!$versions[$url]) {
        return $match[0];
    }

    return $match[1] . $match[2] . $match[3] . $url . '?v=' . $versions[$url] . $match[5];
}

function pg_looks_like_zip($bytes)
{
    if (!is_string($bytes) || strlen($bytes) < 4) {
        return false;
    }

    $magic = substr($bytes, 0, 4);

    return ($magic === "PK\x03\x04" || $magic === "PK\x05\x06" || $magic === "PK\x07\x08");
}

/**
 * Extract an update archive and PROVE every entry landed on disk.
 *
 * ZipArchive::extractTo() returns a boolean that the update flow ignored, and
 * that single omission is the cause of the recurring "the update left files
 * missing" problem. Extraction stops at the first entry it cannot write — a
 * permission denied, a file held open by another process, a full disk,
 * open_basedir — and everything after that entry is simply never created.
 * The caller saw no error and reported success, leaving a half-updated
 * installation that then had to be repaired by hand.
 *
 * Three things are checked here, in increasing order of cost:
 *
 *   1. The archive opens with CHECKCONS, so a truncated or corrupt download is
 *      rejected before a single file is touched rather than half-applied.
 *   2. extractTo() succeeded.
 *   3. Every entry the archive claims to contain now exists on disk. This is
 *      the check that actually catches a partial extraction, because step 2
 *      can still return true on some platforms after skipping entries.
 *
 * Returns array('ok' => bool, 'message' => string, 'missing' => array).
 */
function pg_extract_archive($archive_path, $destination)
{
    if (!class_exists('ZipArchive')) {
        return array('ok' => false, 'message' => 'The ZipArchive extension is not available on this server.', 'missing' => array());
    }

    if (!is_file($archive_path) || filesize($archive_path) < 4) {
        return array('ok' => false, 'message' => 'The downloaded archive is missing or empty.', 'missing' => array());
    }

    $zip = new ZipArchive();

    // CHECKCONS makes the consistency of the archive a precondition. Without
    // it a damaged file can open on the strength of its central directory
    // alone and then extract nonsense.
    $opened = $zip->open($archive_path, ZipArchive::CHECKCONS);

    if ($opened !== true) {
        // Fall back to a plain open so an archive that merely fails the strict
        // check still reports a useful error rather than a bare code.
        $opened = $zip->open($archive_path);

        if ($opened !== true) {
            return array(
                'ok' => false,
                'message' => 'The downloaded archive could not be opened (code ' . (int) $opened . '). It is most likely incomplete — try again.',
                'missing' => array(),
            );
        }
    }

    $entries = array();

    for ($i = 0; $i < $zip->numFiles; $i++) {
        $stat = $zip->statIndex($i);

        if ($stat && isset($stat['name']) && substr($stat['name'], -1) !== '/') {
            $entries[] = $stat['name'];
        }
    }

    $extracted = $zip->extractTo($destination);
    $zip->close();

    if (!$extracted) {
        return array(
            'ok' => false,
            'message' => 'Extraction failed. The web server may not have write permission for the software directory, or the disk may be full.',
            'missing' => array(),
        );
    }

    // Prove it. This is the check the update flow never had.
    $missing = array();
    $destination = rtrim($destination, '/\\') . '/';

    foreach ($entries as $entry) {
        if (!file_exists($destination . $entry)) {
            $missing[] = $entry;

            if (count($missing) >= 25) {
                break;
            }
        }
    }

    if ($missing) {
        return array(
            'ok' => false,
            'message' => count($missing) . '+ file(s) from the archive were not written. The installation is now partially updated and should be repaired.',
            'missing' => $missing,
        );
    }

    return array('ok' => true, 'message' => '', 'missing' => array());
}

function perf_monitor_init()
{
    if (defined('PERF_MONITOR') && PERF_MONITOR === false) {
        return;
    }

    // Skip CLI / cron contexts: no useful URL, and they distort percentile views.
    if (PHP_SAPI === 'cli') {
        return;
    }

    $sample_rate = defined('PERF_MONITOR_SAMPLE_RATE') ? (int) PERF_MONITOR_SAMPLE_RATE : 100;
    if ($sample_rate < 1) {
        return;
    }
    if ($sample_rate < 100 && mt_rand(1, 100) > $sample_rate) {
        return;
    }

    // Prefer REQUEST_TIME_FLOAT — PHP populates it before our code runs, so it captures
    // the true entry timestamp rather than "now, after init has already partially executed".
    // The value has to be positive to be usable. Some SAPIs expose the key
    // with a zero or empty value rather than omitting it, and isset() happily
    // returns true for that — the duration then comes out as the current unix
    // time in milliseconds, roughly 1.7 trillion, which MySQL silently clamps
    // to the column ceiling and which then poisons the hourly average for
    // good, because a summary row keeps what it was given.
    $start_time = (isset($_SERVER['REQUEST_TIME_FLOAT']) && (float) $_SERVER['REQUEST_TIME_FLOAT'] > 0)
        ? (float) $_SERVER['REQUEST_TIME_FLOAT']
        : microtime(true);

    $start_rusage = function_exists('getrusage') ? @getrusage() : null;

    $GLOBALS['perf_monitor'] = array(
        'start_time'   => $start_time,
        'start_rusage' => $start_rusage,
    );

    register_shutdown_function('perf_monitor_shutdown');
}

function perf_monitor_shutdown()
{
    if (empty($GLOBALS['perf_monitor'])) {
        return;
    }

    // Flush the response before doing DB work, so logging never sits on the
    // user-visible path.
    //
    // fastcgi_finish_request() is PHP-FPM only. Under mod_php, CGI or IIS it
    // does not exist, and everything below runs BEFORE the response is
    // finished — the monitor then costs the visitor real milliseconds. Track
    // which case we are in so the expensive housekeeping can be skipped when
    // the visitor is still waiting.
    $flushed = false;

    if (function_exists('fastcgi_finish_request')) {
        $flushed = (bool) @fastcgi_finish_request();
    }

    if (!isset(db::$con) || !db::$con) {
        return;
    }

    // Site Settings switch. Checked here rather than in perf_monitor_init(),
    // which runs before the config row is read. Everything expensive is below
    // this line, so turning it off leaves only a few microseconds of timers.
    if (defined('PERF_MONITOR_ENABLED') && !PERF_MONITOR_ENABLED) {
        return;
    }

    $state = $GLOBALS['perf_monitor'];
    $now = microtime(true);
    $duration_ms = (int) round(($now - $state['start_time']) * 1000);

    // Sanity gate.
    //
    // A summary table cannot forget. One nonsensical duration is added into
    // total_ms and pushed into max_ms, and every average computed from that
    // bucket is wrong until the bucket ages out — which is exactly what
    // happened on a live install: a single bad measurement produced an
    // average of 595,400,352,033 ms and a peak of 4,294,967,295 ms, the
    // unsigned 32-bit ceiling.
    //
    // MySQL will not object. Strict mode is deliberately off in this codebase,
    // so an out-of-range value is clamped and a negative one is reinterpreted
    // as huge, both without an error. The check therefore has to happen here.
    //
    // An hour is far beyond any real request: PHP's own max_execution_time is
    // measured in seconds. Anything past it is a broken clock or a broken
    // start time, and the right answer is to record nothing rather than
    // something false.
    if ($duration_ms < 0 || $duration_ms > 3600000) {
        return;
    }

    $script_name = isset($_SERVER['SCRIPT_NAME']) ? basename($_SERVER['SCRIPT_NAME']) : '';

    // Scripts the operator does not want measured. api.php is excluded by
    // default: it is the internal AJAX endpoint, so every dashboard widget and
    // every autocomplete keystroke is one of its requests. Grouped under a
    // single name it sat at the top of every report while telling nobody
    // anything about which page is slow.
    $ignored = defined('PERF_MONITOR_IGNORE_SCRIPTS')
        ? PERF_MONITOR_IGNORE_SCRIPTS
        : 'api.php';

    if ($ignored !== '' && $script_name !== '') {
        foreach (preg_split('/[\s,;]+/', $ignored) as $ignored_script) {
            if ($ignored_script !== '' && strcasecmp($ignored_script, $script_name) === 0) {
                return;
            }
        }
    }

    // Same reasoning, cheaper to state: clamp rather than discard, because a
    // memory reading being odd is no reason to lose a good duration.
    $peak_memory_kb = (int) round(memory_get_peak_usage(true) / 1024);

    if ($peak_memory_kb < 0 || $peak_memory_kb > 16777216) {
        $peak_memory_kb = 0;
    }

    $cpu_user_ms = 0;
    $cpu_system_ms = 0;
    if (is_array($state['start_rusage']) && function_exists('getrusage')) {
        $end_rusage = @getrusage();
        if (is_array($end_rusage)) {
            $u = (($end_rusage['ru_utime.tv_sec'] - $state['start_rusage']['ru_utime.tv_sec']) * 1000)
               + (($end_rusage['ru_utime.tv_usec'] - $state['start_rusage']['ru_utime.tv_usec']) / 1000);
            $s = (($end_rusage['ru_stime.tv_sec'] - $state['start_rusage']['ru_stime.tv_sec']) * 1000)
               + (($end_rusage['ru_stime.tv_usec'] - $state['start_rusage']['ru_stime.tv_usec']) / 1000);
            if ($u >= 0 && $u <= 3600000) { $cpu_user_ms = (int) round($u); }
            if ($s >= 0 && $s <= 3600000) { $cpu_system_ms = (int) round($s); }
        }
    }

    // Backend vs frontend: router.php sets PHP_SETTINGS_UPDATED before including init.php,
    // so its presence means the request was routed (i.e. a public-facing page or asset).
    $area = defined('PHP_SETTINGS_UPDATED') ? 'frontend' : 'backend';

    $request_url = '';
    if (defined('REQUEST_URL')) {
        $request_url = REQUEST_URL;
    } elseif (isset($_SERVER['REQUEST_URI'])) {
        $request_url = $_SERVER['REQUEST_URI'];
    }

    $query_string = '';
    $qpos = strpos($request_url, '?');
    if ($qpos !== false) {
        $query_string = substr($request_url, $qpos + 1, 500);
        $request_url = substr($request_url, 0, $qpos);
    }
    if (strlen($request_url) > 510) {
        $request_url = substr($request_url, 0, 510);
    }

    $http_status = function_exists('http_response_code') ? (int) http_response_code() : 200;

    // Grouping label: the URL identifies a front-end page, the script name a
    // back-end screen.
    $label = ($area === 'frontend')
        ? ($request_url === '' || $request_url === '/' ? '[home]' : $request_url)
        : $script_name;

    // Anything that failed is grouped under its status code instead of its URL.
    //
    // Two reasons, and the second is the important one.
    //
    // A missing file is not a page. The rewrite rule sends any request whose
    // file does not exist to the router, so a stale asset reference or a
    // scanner probing /install/api.php runs the whole PHP stack and lands in
    // the report next to real pages, where it means nothing.
    //
    // More seriously, those URLs are chosen by whoever is making the request.
    // perf_stats keeps one row per label per hour, so a scanner walking a
    // hundred thousand paths would create a hundred thousand buckets an hour —
    // letting a stranger decide how large this table gets, which is precisely
    // what the summary design exists to prevent. Folding them into one label
    // keeps the signal (how many failures, and how slow they are to produce)
    // and caps the cost at a single row.
    //
    // The individual slow rows below still record the real URL, so a 404 that
    // is somehow taking seconds can still be traced.
    if ($http_status >= 400) {
        $label = '[' . $http_status . ']';
    }

    if (strlen($label) > 250) {
        $label = substr($label, 0, 250);
    }

    $slow_ms = defined('PERF_MONITOR_SLOW_MS') ? (int) PERF_MONITOR_SLOW_MS : 1000;
    $is_slow = ($slow_ms > 0 && $duration_ms >= $slow_ms) ? 1 : 0;

    // ── Every request: fold into an hourly bucket ────────────────────────
    //
    // One statement, and the table stops growing with traffic — the same
    // request an hour from now updates a different row, the same request a
    // minute from now updates this one. This is what replaces a million rows
    // of ordinary traffic that nobody was ever going to read individually.
    $hour_start = $now - ((int) $now % 3600);

    // Which record this measurement belongs to, resolved while the process
    // that rendered it is still alive. The SEO score joins on this; without
    // it the report would have to turn a URL back into a record, and
    // '/katalog/urun-adi' turns into the catalog detail template rather than
    // into the product, which would file every product under one page.
    //
    // Only for front-end requests that succeeded. A back-end screen is not a
    // scored record, and a failure has already been folded into a '[404]'
    // label that no longer identifies anything.
    $entity_type = '';
    $entity_id = 0;

    // Probed once, and only where the answer can change anything: a back-end
    // screen is not a scored record and a failure has already been folded into
    // a '[404]' label that identifies nothing. Under mod_php, CGI and IIS
    // there is no fastcgi_finish_request(), so everything here still runs while
    // the visitor waits - a metadata round trip on every request would be new
    // cost on the public path for no answer.
    $has_entity_columns = false;

    if (($area === 'frontend') && ($http_status < 400)) {

        $has_entity_columns = pg_perf_stats_has_entity();
        $entity = pg_measured_entity();
        $entity_type = $entity['type'];
        $entity_id = (int) $entity['id'];
    }

    // The record is part of the bucket key, not just a column on it.
    //
    // One label does not always mean one record. '[home]' is shared by every
    // page carrying page_home, and get_page.php picks between them at random
    // by design. A catalogue reached as '/urun-detay?pid=5' has its query
    // string stripped, so every product behind it shares one label. Storing
    // the identity as a plain column would hand the whole bucket to whichever
    // record happened to be rendered first that hour and quietly credit one
    // page with another page's timings.
    //
    // This does not widen the cost problem the summary design exists to solve.
    // A label already carries whatever cardinality it had: a '[404]' never
    // carries a record at all, and the page types that accept a trailing path
    // segment (system layouts, catalog and catalog detail) were already
    // producing one label per requested path before this change, all of them
    // resolving to the same record. What the record adds is one bucket per
    // record behind a shared label, which is bounded by the site's own content
    // - the same bound visitor_content_hourly already accepts.
    // PERF_MONITOR_MAX_ROWS remains the backstop for the paths that were
    // unbounded to begin with.
    // Only split the bucket when the identity can actually be written. Before
    // the upgrade has run there is nowhere to record which record a bucket
    // belongs to, so splitting would produce indistinguishable rows and spend
    // the row cap several times faster for no benefit at all.
    $bucket_key = $has_entity_columns
        ? sha1($area . '|' . $label . '|' . $entity_type . '|' . $entity_id)
        : sha1($area . '|' . $label);

    $sql_entity_columns = '';
    $sql_entity_values = '';

    if ($has_entity_columns) {
        $sql_entity_columns = ', entity_type, entity_id';
        $sql_entity_values = ", '" . escape($entity_type) . "', " . (int) $entity_id;
    }

    @mysqli_query(
        db::$con,
        "INSERT INTO perf_stats
            (bucket_key, hour_start, label, area, hits, slow_hits,
             total_ms, min_ms, max_ms, total_kb, max_kb, total_cpu_ms" . $sql_entity_columns . ")
         VALUES
            ('" . escape($bucket_key) . "', " . (int) $hour_start . ",
             '" . escape($label) . "', '" . escape($area) . "', 1, " . $is_slow . ",
             " . $duration_ms . ", " . $duration_ms . ", " . $duration_ms . ",
             " . $peak_memory_kb . ", " . $peak_memory_kb . ",
             " . ($cpu_user_ms + $cpu_system_ms) . $sql_entity_values . ")
         ON DUPLICATE KEY UPDATE
            hits         = hits + 1,
            slow_hits    = slow_hits + " . $is_slow . ",
            total_ms     = total_ms + " . $duration_ms . ",
            min_ms       = LEAST(min_ms, " . $duration_ms . "),
            max_ms       = GREATEST(max_ms, " . $duration_ms . "),
            total_kb     = total_kb + " . $peak_memory_kb . ",
            max_kb       = GREATEST(max_kb, " . $peak_memory_kb . "),
            total_cpu_ms = total_cpu_ms + " . ($cpu_user_ms + $cpu_system_ms)
    );

    // ── Slow requests only: keep the full detail ─────────────────────────
    //
    // A summary tells you a page is slow; it cannot tell you which request
    // took 101 seconds or who made it. These rows are rare by construction —
    // on a site averaging 48 ms, almost nothing crosses the threshold — so
    // they cost little and carry the parameters, address and client that make
    // the outlier investigable.
    if ($is_slow) {
        $method = isset($_SERVER['REQUEST_METHOD']) ? substr($_SERVER['REQUEST_METHOD'], 0, 8) : 'GET';
        $is_ajax = (isset($_SERVER['HTTP_X_REQUESTED_WITH'])
            && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest') ? 1 : 0;
        $user_id = (defined('USER_ID') && USER_ID !== '') ? (int) USER_ID : 0;

        $ip_address = function_exists('waf_client_ip')
            ? waf_client_ip()
            : (isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '');

        $user_agent = isset($_SERVER['HTTP_USER_AGENT'])
            ? substr($_SERVER['HTTP_USER_AGENT'], 0, 250)
            : '';

        @mysqli_query(
            db::$con,
            "INSERT INTO perf_log
                (request_url, query_string, script_name, area, method, http_status,
                 duration_ms, peak_memory_kb, cpu_user_ms, cpu_system_ms,
                 ip_address, user_agent, user_id, is_ajax, log_timestamp)
             VALUES (
                '" . escape($request_url) . "',
                '" . escape($query_string) . "',
                '" . escape($script_name) . "',
                '" . escape($area) . "',
                '" . escape($method) . "',
                " . (int) $http_status . ",
                " . (int) $duration_ms . ",
                " . (int) $peak_memory_kb . ",
                " . (int) $cpu_user_ms . ",
                " . (int) $cpu_system_ms . ",
                '" . escape($ip_address) . "',
                '" . escape($user_agent) . "',
                " . (int) $user_id . ",
                " . (int) $is_ajax . ",
                UNIX_TIMESTAMP()
            )"
        );
    }

    // ── Housekeeping ─────────────────────────────────────────────────────
    //
    // Only when the response has already been flushed. A DELETE is the most
    // expensive thing this function can do, and on a server where we could not
    // flush first it would land squarely on the visitor's wait.
    if (!$flushed) {
        return;
    }

    if (mt_rand(1, 200) !== 1) {
        return;
    }

    $retention = defined('PERF_MONITOR_RETENTION_DAYS') ? (int) PERF_MONITOR_RETENTION_DAYS : 30;

    if ($retention > 0) {
        $cutoff = time() - ($retention * 86400);
        @mysqli_query(db::$con, "DELETE FROM perf_stats WHERE hour_start < " . (int) $cutoff . " LIMIT 2000");
        @mysqli_query(db::$con, "DELETE FROM perf_log WHERE log_timestamp < " . (int) $cutoff . " LIMIT 1000");
    }

    // Row cap as a backstop. Both tables are bounded by design now, but a site
    // with very high URL cardinality can still accumulate buckets faster than
    // retention removes them.
    $max_rows = defined('PERF_MONITOR_MAX_ROWS') ? (int) PERF_MONITOR_MAX_ROWS : 200000;

    if ($max_rows > 0) {
        $oldest = @mysqli_query(db::$con,
            "SELECT hour_start FROM perf_stats ORDER BY hour_start DESC LIMIT 1 OFFSET " . (int) $max_rows);

        if ($oldest && @mysqli_num_rows($oldest)) {
            $row = @mysqli_fetch_assoc($oldest);
            @mysqli_query(db::$con,
                "DELETE FROM perf_stats WHERE hour_start <= " . (int) $row['hour_start'] . " LIMIT 5000");
        }
    }
}

/**
 * Shared core for order cancellation (customer self-service via cancel_order.php
 * + admin per-row / bulk cancel via edit_orders.php).
 *
 * Responsibilities:
 *   1. Status check (idempotency).
 *   2. Pre-shipment guard — CUSTOMERS ONLY, keyed on tracking code.
 *      $is_admin === true skips it entirely.
 *   3. Persist cancellation columns (status / cancelled_at / cancelled_by /
 *      cancellation_reason).
 *   4. Expire gift cards that were issued by this order.
 *   5. Log activity + REFUND ACTION REQUIRED reminder for the operator.
 *   6. Optional: customer email notification (ECOMMERCE_CANCEL_EMAIL_NOTIFICATION).
 *   7. Optional: Iyzipay auto-refund (ECOMMERCE_ORDER_CANCEL_AUTO_REFUND) — writes
 *      orders.refund_status / refunded_at / refund_reference when the 2026.1.27
 *      migration has run; otherwise silently skips the columns.
 *
 * Returns associative array:
 *   ['status' => 'success'|'already'|'shipped'|'not_found'|'error',
 *    'message' => 'human-readable string for the operator/log',
 *    'refund_status' => '' | 'pending' | 'refunded' | 'failed' | 'manual_required',
 *    'order_id' => (int)]
 *
 * Callers are responsible for CSRF + ownership/permission gates. This function
 * trusts $is_admin to mean "caller has already validated the user is an admin".
 * That flag is load-bearing: besides the activity-log note, it BYPASSES the
 * pre-shipment guard. Never pass true from a visitor-reachable path without
 * having checked the role first.
 *
 * @param int      $order_id       Target order PK
 * @param string   $reason         Visitor / operator typed reason (≤ 500 chars)
 * @param bool     $is_admin       True when invoked from an admin context
 * @param int      $user_id        Canceller's user_id (0 for guest)
 * @param bool|null $attempt_refund NULL (default) follows the
 *                                 ECOMMERCE_ORDER_CANCEL_AUTO_REFUND config
 *                                 define. Pass TRUE to force the gateway void
 *                                 regardless of the define — used by the admin
 *                                 detail-screen modal, where the operator has
 *                                 explicitly confirmed "void the payment".
 *                                 Pass FALSE to suppress it.
 * @return array
 */
function process_order_cancellation($order_id, $reason = '', $is_admin = false, $user_id = 0, $attempt_refund = null)
{
    $order_id = (int) $order_id;
    if ($order_id <= 0) {
        return array('status' => 'error', 'message' => 'Order id is missing.', 'refund_status' => '', 'order_id' => 0);
    }

    // Minimal selection — enough for cancel gating + email + refund.
    $order = db_item(
        "SELECT id, status, user_id, payment_method, transaction_id, total,
                billing_first_name, billing_last_name, billing_email_address,
                order_number, order_date
         FROM orders
         WHERE id = '" . e($order_id) . "'
         LIMIT 1"
    );

    if (!$order) {
        return array('status' => 'not_found', 'message' => 'Order not found.', 'refund_status' => '', 'order_id' => $order_id);
    }

    // Already cancelled — idempotent no-op.
    if ($order['status'] === 'cancelled') {
        return array('status' => 'already', 'message' => 'Order was already cancelled.', 'refund_status' => '', 'order_id' => $order_id);
    }

    // ── Pre-shipment guard (CUSTOMERS ONLY) ─────────────────────────────
    // Admins are never blocked. An operator cancelling from the panel has
    // context the code does not — a customer phoned, the courier returned the
    // parcel, the order was a duplicate — so the shipment state is advisory
    // for them, not a lock. The ECOMMERCE_ORDER_CANCEL_UNTIL_SHIPPED define
    // therefore governs the SELF-SERVICE path only.
    //
    // "Shipped" means a tracking code exists (see _order_has_shipped).
    // ship_date is NOT consulted: it is often pre-filled with a planned
    // dispatch date at order time, and gating on it locked customers out of
    // orders that had not actually left yet.
    $cancel_until_shipped = !defined('ECOMMERCE_ORDER_CANCEL_UNTIL_SHIPPED')
        || ECOMMERCE_ORDER_CANCEL_UNTIL_SHIPPED !== false;
    if (!$is_admin && $cancel_until_shipped && _order_has_shipped($order_id)) {
        return array('status' => 'shipped', 'message' => 'Order has already shipped.', 'refund_status' => '', 'order_id' => $order_id);
    }

    $reason_clean = trim(mb_substr((string) $reason, 0, 500));

    // ── Persist cancellation ────────────────────────────────────────────
    db(
        "UPDATE orders SET
            status              = 'cancelled',
            cancelled_at        = '" . time() . "',
            cancelled_by        = '" . (int) $user_id . "',
            cancellation_reason = '" . escape($reason_clean) . "'
         WHERE id = '" . e($order_id) . "'"
    );

    // ── Expire gift cards issued by this order ──────────────────────────
    // Folded in from the removed legacy cancel_order(). A cancelled order
    // must not leave spendable gift cards behind, so we push their
    // expiration to yesterday (immediately invalid) and leave an audit note.
    // Rows that already expired earlier are left untouched.
    $yesterday   = date('Y-m-d', strtotime('-1 day'));
    $cancel_note = escape(lang('This gift card was automatically expired because the associated order was cancelled.'));
    db(
        "UPDATE gift_cards
         SET
            expiration_date = '" . $yesterday . "',
            notes = CONCAT(IF(notes IS NULL OR notes = '', '', CONCAT(notes, '\n')), '" . $cancel_note . "')
         WHERE order_id = '" . e($order_id) . "'
           AND (expiration_date = '0000-00-00' OR expiration_date > '" . $yesterday . "')"
    );

    log_activity(
        'Order #' . $order_id . ' cancelled by ' .
        ($is_admin ? 'admin' : 'customer') . ' (user_id=' . (int) $user_id . ').' .
        ($reason_clean !== '' ? ' Reason: ' . $reason_clean : '')
    );

    // ── Iyzipay auto-refund (opt-in) ────────────────────────────────────
    // Default OFF. When ECOMMERCE_ORDER_CANCEL_AUTO_REFUND === true and the
    // payment was made with Iyzipay, attempt a void via the Cancel API.
    // Failures here MUST NOT roll back the cancellation — refunds can be
    // retried manually from the gateway dashboard. We just record the
    // outcome on the order row so the operator can audit.
    $refund_status_outcome = '';
    $refund_reference      = '';
    $refund_columns_exist  = _orders_has_refund_columns();

    // $attempt_refund overrides the config define when the caller is explicit
    // (admin detail screen: the operator confirmed a modal that says the
    // payment will be voided, so honour that regardless of the site default).
    if ($attempt_refund === null) {
        $auto_refund = defined('ECOMMERCE_ORDER_CANCEL_AUTO_REFUND') && ECOMMERCE_ORDER_CANCEL_AUTO_REFUND === true;
    } else {
        $auto_refund = (bool) $attempt_refund;
    }
    $is_iyzipay  = in_array($order['payment_method'], array('Iyzipay', 'Pay With Iyzico'), true);
    $has_txn     = !empty($order['transaction_id']);
    $order_total = (int) $order['total']; // cents

    if ($auto_refund && $is_iyzipay && $has_txn && defined('ECOMMERCE_IYZIPAY_API_KEY') && $order_total > 0) {
        try {
            require_once(dirname(__FILE__) . '/assets/iyzipay-php/IyzipayBootstrap.php');
            IyzipayBootstrap::init();

            $gateway_host = (defined('ECOMMERCE_PAYMENT_GATEWAY_MODE') && ECOMMERCE_PAYMENT_GATEWAY_MODE == 'test')
                ? 'https://sandbox-api.iyzipay.com'
                : 'https://api.iyzipay.com';

            $options = new \Iyzipay\Options();
            $options->setApiKey(ECOMMERCE_IYZIPAY_API_KEY);
            $options->setSecretKey(ECOMMERCE_IYZIPAY_SECRET_KEY);
            $options->setBaseUrl($gateway_host);

            $request = new \Iyzipay\Request\CreateCancelRequest();
            $request->setLocale(\Iyzipay\Model\Locale::TR);
            $request->setConversationId((string) $order_id . '-' . time());
            $request->setPaymentId((string) $order['transaction_id']);
            $request->setIp(isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '127.0.0.1');

            if ($reason_clean !== '') {
                $request->setDescription(mb_substr($reason_clean, 0, 240));
            }

            $cancel = \Iyzipay\Model\Cancel::create($request, $options);

            if ($cancel->getStatus() == 'success') {
                $refund_status_outcome = 'refunded';
                $refund_reference      = (string) ($cancel->getPaymentId() ?: $order['transaction_id']);
                log_activity('Auto-refund SUCCESS via Iyzipay — order #' . $order_id . ' (payment ' . $refund_reference . ').');
            } else {
                $refund_status_outcome = 'failed';
                $err_msg = method_exists($cancel, 'getErrorMessage') ? (string) $cancel->getErrorMessage() : '';
                log_activity(
                    'Auto-refund FAILED via Iyzipay — order #' . $order_id .
                    '. MANUAL REFUND REQUIRED. Gateway message: ' . ($err_msg !== '' ? $err_msg : '(no message)')
                );
                $refund_status_outcome = 'manual_required';
            }
        } catch (\Throwable $e) {
            // PHP 7+ — Throwable catches both Exception and Error. Keeps the
            // cancellation persisted; refund just needs operator follow-up.
            $refund_status_outcome = 'manual_required';
            log_activity('Auto-refund EXCEPTION — order #' . $order_id . '. MANUAL REFUND REQUIRED. ' . $e->getMessage());
        } catch (\Exception $e) {
            $refund_status_outcome = 'manual_required';
            log_activity('Auto-refund EXCEPTION — order #' . $order_id . '. MANUAL REFUND REQUIRED. ' . $e->getMessage());
        }
    } elseif ($order_total > 0 && (string) $order['payment_method'] !== '' && (string) $order['payment_method'] !== 'Offline Payment') {
        // No auto-refund — but money did change hands, so flag for the operator.
        $refund_status_outcome = 'manual_required';
        log_activity(
            'REFUND ACTION REQUIRED — order #' . $order_id . ' was cancelled. ' .
            'Payment method: ' . $order['payment_method'] . '. ' .
            'Amount: ' . number_format($order_total / 100, 2, '.', ',') . '. ' .
            'Process refund in the gateway dashboard.'
        );
    }

    if ($refund_columns_exist && $refund_status_outcome !== '') {
        $refunded_at_sql = ($refund_status_outcome === 'refunded') ? "'" . time() . "'" : 'NULL';
        db(
            "UPDATE orders SET
                refund_status    = '" . escape($refund_status_outcome) . "',
                refunded_at      = " . $refunded_at_sql . ",
                refund_reference = '" . escape($refund_reference) . "'
             WHERE id = '" . e($order_id) . "'"
        );
    }

    // ── Customer email notification ─────────────────────────────────────
    // Defensive: a flaky SMTP server must not block the cancel itself.
    $email_enabled = !defined('ECOMMERCE_CANCEL_EMAIL_NOTIFICATION')
        || ECOMMERCE_CANCEL_EMAIL_NOTIFICATION !== false;
    if ($email_enabled) {
        try {
            _send_order_cancellation_email($order, $reason_clean, $refund_status_outcome);
        } catch (\Throwable $e) {
            log_activity('Cancellation email failed for order #' . $order_id . ': ' . $e->getMessage());
        } catch (\Exception $e) {
            log_activity('Cancellation email failed for order #' . $order_id . ': ' . $e->getMessage());
        }
    }

    return array(
        'status'        => 'success',
        'message'       => 'Order cancelled.',
        'refund_status' => $refund_status_outcome,
        'order_id'      => $order_id,
    );
}

/**
 * Has this order physically gone out?
 *
 * The operator's workflow is the source of truth here: an order counts as
 * shipped the moment a TRACKING CODE is recorded — not when a ship_date is
 * filled in. ship_tos.ship_date is a *planned* dispatch date that gets set at
 * order time on many configurations, so gating on it blocked cancellation of
 * orders that had not left the building yet. It is deliberately ignored.
 *
 * Two stores hold tracking data and either one counts:
 *   1. orders.tracking_code             — single code for the whole order
 *                                          (what the admin list column and the
 *                                          order_view __tracking_code token use)
 *   2. shipping_tracking_numbers.number — per-ship_to codes, used by
 *                                          multi-recipient orders
 *
 * Only the CUSTOMER-facing cancel path consults this. Admins cancel regardless
 * (see process_order_cancellation()).
 *
 * @param  int  $order_id
 * @return bool
 */
function _order_has_shipped($order_id)
{
    $order_id = (int) $order_id;
    if ($order_id <= 0) return false;

    // Order-level code.
    $code = (string) db_value(
        "SELECT tracking_code FROM orders WHERE id = '" . e($order_id) . "' LIMIT 1"
    );
    if (trim($code) !== '') return true;

    // Per-recipient codes. Blank rows don't count as shipped.
    $per_recipient = (int) db_value(
        "SELECT COUNT(*) FROM shipping_tracking_numbers
         WHERE order_id = '" . e($order_id) . "'
           AND TRIM(number) != ''"
    );

    return $per_recipient > 0;
}

/**
 * Probe orders.refund_status — true only after the 2026.1.27 upgrade has run.
 * Cached per-request so we don't issue SHOW COLUMNS on every cancel.
 */
function _orders_has_refund_columns()
{
    static $cached = null;
    if ($cached !== null) return $cached;
    $row = db_item("SHOW COLUMNS FROM orders LIKE 'refund_status'");
    $cached = !empty($row);
    return $cached;
}

/**
 * Send a Turkish-localised cancellation email to the order's billing address.
 * Skips silently when the order has no billing email or required globals
 * (EMAIL_ADDRESS / ORGANIZATION_NAME) aren't configured.
 */
function _send_order_cancellation_email($order, $reason, $refund_status)
{
    $to = isset($order['billing_email_address']) ? trim((string) $order['billing_email_address']) : '';
    if ($to === '' || strpos($to, '@') === false) {
        return false;
    }
    if (!defined('EMAIL_ADDRESS') || EMAIL_ADDRESS === '') {
        return false;
    }

    $from_name = defined('ORGANIZATION_NAME') && ORGANIZATION_NAME !== ''
        ? ORGANIZATION_NAME
        : (defined('HOSTNAME_SETTING') ? HOSTNAME_SETTING : 'Pinegrap');

    $order_id     = (int) $order['id'];
    $order_number = isset($order['order_number']) && $order['order_number'] !== ''
        ? (string) $order['order_number']
        : (string) $order_id;
    $total_amount = isset($order['total']) ? (int) $order['total'] : 0;
    $amount_str   = $total_amount > 0 ? number_format($total_amount / 100, 2, ',', '.') : '';
    $customer     = trim((string) ($order['billing_first_name'] ?? '') . ' ' . (string) ($order['billing_last_name'] ?? ''));

    $subject = lang(array(
        'string' => 'Your order #{var:1} has been cancelled',
        'vars'   => array($order_number),
    ));

    $refund_paragraph = '';
    if ($refund_status === 'refunded') {
        $refund_paragraph = '<p style="margin:0 0 12px;">'
            . h(lang('Your payment has been refunded to the original payment method. Bank settlement may take a few business days.'))
            . '</p>';
    } elseif ($refund_status === 'manual_required' || $refund_status === 'failed' || $refund_status === 'pending') {
        $refund_paragraph = '<p style="margin:0 0 12px;">'
            . h(lang('Payment refunds are processed manually. Please contact us for refund status.'))
            . '</p>';
    }

    $reason_paragraph = '';
    if ($reason !== '') {
        $reason_paragraph = '<p style="margin:0 0 12px;"><strong>' . h(lang('Cancellation reason')) . ':</strong> ' . h($reason) . '</p>';
    }

    $amount_paragraph = '';
    if ($amount_str !== '') {
        $amount_paragraph = '<p style="margin:0 0 12px;"><strong>' . h(lang('Order Total')) . ':</strong> ' . h($amount_str) . '</p>';
    }

    $body = '<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;background:#f7f7f7;padding:20px;">'
        . '<div style="max-width:560px;margin:0 auto;background:#fff;padding:24px;border-radius:6px;border:1px solid #e5e5e5;">'
        . '<h2 style="margin:0 0 16px;font-size:18px;color:#b02a37;">' . h(lang('Order Cancelled')) . '</h2>'
        . '<p style="margin:0 0 12px;">' . h(lang('Hello')) . ($customer !== '' ? ' ' . h($customer) : '') . ',</p>'
        . '<p style="margin:0 0 12px;">'
        . h(lang(array(
            'string' => 'Your order #{var:1} has been cancelled.',
            'vars'   => array($order_number),
        ))) . '</p>'
        . $amount_paragraph
        . $reason_paragraph
        . $refund_paragraph
        . '<p style="margin:16px 0 0;color:#666;font-size:12px;">' . h($from_name) . '</p>'
        . '</div></body></html>';

    return email(array(
        'to'                 => $to,
        'to_name'            => $customer,
        'from_name'          => $from_name,
        'from_email_address' => EMAIL_ADDRESS,
        'subject'            => $subject,
        'format'             => 'html',
        'body'               => $body,
        'type'               => 'system',
    ));
}

// ─────────────────────────────────────────────────────────────────────────────
// Express Order — recipient_loop_area support (multi-recipient designer
// customization). The designer drops a `recipient_loop_area` node into the
// tree; its children form a template that the server renders ONCE per
// shipping recipient. Field bindings (eo_field='shipping_first_name', …) are
// rewritten per iteration to `shipping_<rid>_*` so each recipient gets its
// own POST keys. Per-iteration text tokens (^^__recipient_index^^,
// ^^__recipient_name^^, ^^__recipient_id^^) are replaced at template-clone time.
//
// Single-recipient orders with a recipient_loop_area still work — the loop
// runs exactly once. Trees WITHOUT a recipient_loop_area fall through to the
// existing server-rendered _eo_render_shipping_section() pipeline (backwards
// compat).
// ─────────────────────────────────────────────────────────────────────────────

// Detect: does the tree contain at least one recipient_loop_area node?
function _eo_tree_has_recipient_loop_area($tree)
{
    if (!is_array($tree)) return false;
    if (isset($tree['type']) && $tree['type'] === 'recipient_loop_area') return true;
    if (!empty($tree['children']) && is_array($tree['children'])) {
        foreach ($tree['children'] as $child) {
            if (_eo_tree_has_recipient_loop_area($child)) return true;
        }
    }
    return false;
}

// Walk the tree, locate the FIRST recipient_loop_area, capture its children
// as a per-recipient template and replace the node with a marker comment.
// Returns: ['static_tree' => $tree_clone, 'template_children' => array|null]
//
// Mirrors _split_widget_tree (cart-item loop) but for recipient iteration.
// Only one recipient_loop_area is honored per widget tree (designer guard
// enforces 1-per-widget too).
function _eo_split_recipient_loop_area($tree)
{
    if (!is_array($tree)) return array('static_tree' => $tree, 'template_children' => null);
    $clone = json_decode(json_encode($tree), true);
    $template_children = null;

    $marker_node = array(
        'type'     => 'content',
        'props'    => array('contentType' => 'custom_html', 'html' => '<!--pg-recipient-loop-slot-->'),
        'children' => array(),
    );

    $walk = function (&$node) use (&$walk, &$template_children, $marker_node) {
        if (!is_array($node) || empty($node['children']) || $template_children !== null) return;
        foreach ($node['children'] as $i => $child) {
            if ($template_children !== null) return;
            if (isset($child['type']) && $child['type'] === 'recipient_loop_area') {
                $template_children = isset($child['children']) ? $child['children'] : array();
                $node['children'][$i] = $marker_node;
                return;
            }
            $walk($node['children'][$i]);
        }
    };
    $walk($clone);

    return array('static_tree' => $clone, 'template_children' => $template_children);
}

// Build per-recipient ^^__token^^ replacements for a single iteration of the
// recipient loop. Keys are tokens that the designer can place inside the
// recipient_loop_area template (text bindings on heading/paragraph/span).
//
// Tokens:
//   ^^__recipient_index^^              "1", "2", …          (1-based)
//   ^^__recipient_count^^              "3"                  (total recipients)
//   ^^__recipient_id^^                 "612"                (ship_tos.id; for input ids)
//   ^^__recipient_name^^               "Ayşe Yılmaz"        (ship_to_name, falls back to "Alıcı N")
//   ^^__recipient_address_first_name^^ session/db value for shipping_<rid>_first_name
//   ^^__recipient_address_last_name^^
//   ^^__recipient_address_street^^     (alias of address_1)
//   ^^__recipient_address_address_1^^
//   ^^__recipient_address_address_2^^
//   ^^__recipient_address_city^^
//   ^^__recipient_address_state^^
//   ^^__recipient_address_zip^^        (alias of zip_code)
//   ^^__recipient_address_zip_code^^
//   ^^__recipient_address_country^^
//   ^^__recipient_address_phone^^      (alias of phone_number)
//   ^^__recipient_address_phone_number^^
//
// The address tokens are intended for read-only display (e.g. summary card).
// For actual input fields use _bindings.eo_field='shipping_first_name' inside
// the recipient_loop_area — the field-binding walker rewrites the name to
// shipping_<rid>_first_name automatically.
function _eo_compute_recipient_tokens($recipient, $index, $count, $lf = null)
{
    if (!is_array($recipient)) $recipient = array();
    $rid = isset($recipient['id']) ? (int)$recipient['id'] : 0;
    $get = function ($field) use ($lf, $recipient, $rid) {
        if ($lf && $rid > 0) {
            $key = 'shipping_' . $rid . '_' . $field;
            $v = $lf->get_field_value($key);
            if ($v !== '' && $v !== null) return (string)$v;
        }
        return isset($recipient[$field]) ? (string)$recipient[$field] : '';
    };

    $name = '';
    if (isset($recipient['ship_to_name']) && (string)$recipient['ship_to_name'] !== '') {
        $name = (string)$recipient['ship_to_name'];
    } else {
        $first = $get('first_name');
        $last  = $get('last_name');
        $full  = trim($first . ' ' . $last);
        if ($full !== '') {
            $name = $full;
        } else {
            $name = (string)lang('Recipient') . ' ' . $index;
        }
    }

    $addr1 = $get('address_1');
    $zip   = $get('zip_code');
    $phone = $get('phone_number');

    return array(
        '^^__recipient_index^^'                  => (string)$index,
        '^^__recipient_count^^'                  => (string)$count,
        '^^__recipient_id^^'                     => (string)$rid,
        '^^__recipient_name^^'                   => h($name),
        '^^__recipient_address_first_name^^'     => h($get('first_name')),
        '^^__recipient_address_last_name^^'      => h($get('last_name')),
        '^^__recipient_address_company^^'        => h($get('company')),
        '^^__recipient_address_street^^'         => h($addr1),
        '^^__recipient_address_address_1^^'      => h($addr1),
        '^^__recipient_address_address_2^^'      => h($get('address_2')),
        '^^__recipient_address_city^^'           => h($get('city')),
        '^^__recipient_address_state^^'          => h($get('state')),
        '^^__recipient_address_zip^^'            => h($zip),
        '^^__recipient_address_zip_code^^'       => h($zip),
        '^^__recipient_address_country^^'        => h($get('country')),
        '^^__recipient_address_phone^^'          => h($phone),
        '^^__recipient_address_phone_number^^'   => h($phone),
    );
}

// Render the per-recipient template for every shipping recipient.
//
// For each $recipients row:
//   1. Deep-clone the template_children
//   2. Run _eo_apply_field_bindings with that recipient's rid → rewrites every
//      `_bindings.eo_field='shipping_X'` to `shipping_<rid>_X` and pre-fills
//      the value from liveform session (per-recipient)
//   3. Run _eo_prefill_input_values_in_tree (covers raw <input name="...">
//      shipping_<rid>_* fields if the designer typed them manually)
//   4. Render each template child to HTML, concatenate
//   5. Replace per-recipient ^^__recipient_*^^ tokens
//
// Returns the concatenated HTML for all recipients. Returns '' on no
// recipients or empty template.
function _eo_render_recipient_loop($template_children, $recipients, $lf)
{
    if (!is_array($template_children) || empty($template_children)) return '';
    if (!is_array($recipients) || empty($recipients)) return '';

    $out = '';
    $count = count($recipients);
    $i = 0;
    foreach ($recipients as $r) {
        $i++;
        $rid = isset($r['id']) ? (int)$r['id'] : 0;

        // Deep-clone the template (json round-trip — template is small).
        $clone = json_decode(json_encode($template_children), true);
        if (!is_array($clone)) continue;

        // Apply field bindings PER-RECIPIENT so the eo_field walker rewrites
        // shipping_<field> → shipping_<rid>_<field> for THIS recipient's rid.
        // Walker expects a tree node; wrap children in a synthetic root.
        $wrap = array('type' => 'root', 'props' => array(), 'children' => $clone);
        if ($lf) {
            _eo_apply_field_bindings($wrap, $lf, $rid);
            _eo_prefill_input_values_in_tree($wrap, $lf);
        }
        _eo_apply_action_bindings($wrap);

        // Render each cloned child node.
        $row_html = '';
        if (!empty($wrap['children']) && is_array($wrap['children'])) {
            foreach ($wrap['children'] as $kid) {
                $row_html .= (string)_render_tree_node($kid, 0, 0);
            }
        }

        // Per-recipient token replacement (^^__recipient_index^^ etc.).
        $tokens = _eo_compute_recipient_tokens($r, $i, $count, $lf);
        $row_html = strtr($row_html, $tokens);

        $out .= $row_html;
    }
    return $out;
}

